export const DUAS = [{"id":1,"c":"namaz","t":{"ro":"Wudu ke baad ki dua","hi":"वुज़ू के बाद की दुआ","en":"Dua after Wudu"},"a":"أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ","tl":"Ashhadu an la ilaha illallahu wahdahu la sharika lah, wa ashhadu anna Muhammadan 'abduhu wa rasuluh","m":{"ur":"میں گواہی دیتا ہوں کہ اللہ کے سوا کوئی معبود نہیں، وہ اکیلا ہے، اس کا کوئی شریک نہیں، اور میں گواہی دیتا ہوں کہ محمد ﷺ اس کے بندے اور رسول ہیں۔","ro":"Main gawahi deta hoon ke Allah ke siwa koi mabood nahin, woh akela hai, uska koi shareek nahin, aur main gawahi deta hoon ke Muhammad ﷺ uske bande aur rasool hain.","hi":"मैं गवाही देता हूँ कि अल्लाह के सिवा कोई माबूद नहीं, वह अकेला है, उसका कोई शरीक नहीं, और मैं गवाही देता हूँ कि मुहम्मद ﷺ उसके बंदे और रसूल हैं।","en":"I bear witness that there is no deity worthy of worship except Allah, He is One and has no partner, and I bear witness that Muhammad ﷺ is His servant and Messenger."},"r":"Sahih Muslim 234","n":{"ur":"جو شخص اچھی طرح وضو کر کے یہ دعا پڑھے، اس کے لیے جنت کے آٹھوں دروازے کھول دیے جاتے ہیں۔","ro":"Jo shakhs achhi tarah wudu karke yeh dua padhe, uske liye jannat ke aathon darwaze khol diye jate hain.","hi":"जो शख़्स अच्छी तरह वुज़ू करके यह दुआ पढ़े, उसके लिए जन्नत के आठों दरवाज़े खोल दिए जाते हैं।","en":"Whoever performs wudu well and then recites this dua, all eight gates of Paradise are opened for him."}},{"id":2,"c":"namaz","t":{"ro":"Azan ka jawab","hi":"अज़ान का जवाब","en":"Replying to the Adhan"},"a":"لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ","tl":"La hawla wa la quwwata illa billah","m":{"ur":"گناہ سے بچنے کی کوئی طاقت اور نیکی کی کوئی قوت نہیں مگر اللہ کی مدد سے۔","ro":"Gunah se bachne ki koi taqat aur neki ki koi quwwat nahin magar Allah ki madad se.","hi":"गुनाह से बचने की कोई ताक़त और नेकी की कोई क़ुव्वत नहीं मगर अल्लाह की मदद से।","en":"There is no power to avoid sin and no strength to do good except with Allah's help."},"r":"Sahih al-Bukhari 611; Sahih Muslim 385","n":{"ur":"موذن کے کلمات دہرائیں؛ صرف 'حی علی الصلاۃ' اور 'حی علی الفلاح' کے جواب میں یہ کہیں۔","ro":"Muazzin ke kalimat dohrayen; sirf 'Hayya alas-salah' aur 'Hayya alal-falah' ke jawab mein yeh kahen.","hi":"मुअज़्ज़िन के कलिमात दोहराएँ; सिर्फ़ 'हय्या अलस-सलाह' और 'हय्या अलल-फ़लाह' के जवाब में यह कहें।","en":"Repeat the words of the muezzin; only in reply to 'Hayya alas-salah' and 'Hayya alal-falah' say this."}},{"id":3,"c":"namaz","t":{"ro":"Azan ke baad shahadat aur raza ka iqrar","hi":"अज़ान के बाद शहादत और रज़ा का इक़रार","en":"Testimony of faith and declaration of contentment after the Adhan"},"a":"وَأَنَا أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، وَأَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ، رَضِيتُ بِاللَّهِ رَبَّا، وَبِمُحَمَّدٍ رَسُولًا، وَبِالْإِسْلَامِ دِينًا","tl":"Wa ana ashhadu an la ilaha illallahu wahdahu la sharika lah, wa anna Muhammadan 'abduhu wa rasuluh, raditu billahi rabban wa bi Muhammadin rasulan wa bil-Islami dinan","m":{"ur":"اور میں بھی گواہی دیتا ہوں کہ اللہ کے سوا کوئی معبود نہیں، وہ اکیلا ہے، اس کا کوئی شریک نہیں، اور یہ کہ محمد ﷺ اس کے بندے اور رسول ہیں۔ میں اللہ کے رب ہونے، محمد ﷺ کے رسول ہونے اور اسلام کے دین ہونے پر راضی ہوں۔","ro":"Aur main bhi gawahi deta hoon ke Allah ke siwa koi mabood nahin, woh akela hai, uska koi shareek nahin, aur yeh ke Muhammad ﷺ uske bande aur rasool hain. Main Allah ke Rab hone, Muhammad ﷺ ke Rasool hone aur Islam ke deen hone par razi hoon.","hi":"और मैं भी गवाही देता हूँ कि अल्लाह के सिवा कोई माबूद नहीं, वह अकेला है, उसका कोई शरीक नहीं, और यह कि मुहम्मद ﷺ उसके बंदे और रसूल हैं। मैं अल्लाह के रब होने, मुहम्मद ﷺ के रसूल होने और इस्लाम के दीन होने पर राज़ी हूँ।","en":"And I too bear witness that there is no deity worthy of worship except Allah, He is One and has no partner, and that Muhammad ﷺ is His servant and Messenger. I am pleased with Allah as my Lord, with Muhammad ﷺ as Messenger, and with Islam as my religion."},"r":"Sahih Muslim 386","n":{"ur":"جو موذن کو سن کر یہ کہے، اس کے گناہ معاف کر دیے جاتے ہیں۔","ro":"Jo muazzin ko sun kar yeh kahe, uske gunah maaf kar diye jate hain.","hi":"जो मुअज़्ज़िन को सुनकर यह कहे, उसके गुनाह माफ़ कर दिए जाते हैं।","en":"Whoever says this after hearing the muezzin, his sins are forgiven."}},{"id":4,"c":"namaz","t":{"ro":"Azan ke baad darood aur wasila ki dua","hi":"अज़ान के बाद दरूद और वसीले की दुआ","en":"Durood and the Wasilah dua after the Adhan"},"a":"اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ. اللَّهُمَّ بَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا بَارَكْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ. ثُمَّ: اللَّهُمَّ رَبَّ هَذِهِ الدَّعْوَةِ التَّامَّةِ وَالصَّلَاةِ الْقَائِمَةِ، آتِ مُحَمَّدًا الْوَسِيلَةَ وَالْفَضِيلَةَ، وَابْعَثْهُ مَقَامًا مَحْمُودًا الَّذِي وَعَدْتَهُ","tl":"Allahumma salli 'ala Muhammadin wa 'ala ali Muhammad, kama sallayta 'ala Ibrahima wa 'ala ali Ibrahim, innaka Hamidun Majid. Allahumma barik 'ala Muhammadin wa 'ala ali Muhammad, kama barakta 'ala Ibrahima wa 'ala ali Ibrahim, innaka Hamidun Majid. Phir: Allahumma Rabba hadhihid-da'watit-tammati was-salatil-qa'imah, ati Muhammadanil-wasilata wal-fadilah, wab'athhu maqamam-mahmudanil-ladhi wa'adtah.","m":{"ur":"اے اللہ! محمد ﷺ اور آلِ محمد پر رحمت نازل فرما جیسے تو نے ابراہیم اور آلِ ابراہیم پر رحمت نازل فرمائی، بے شک تو تعریف کے لائق، بزرگی والا ہے۔ اے اللہ! محمد ﷺ اور آلِ محمد پر برکت نازل فرما جیسے تو نے ابراہیم اور آلِ ابراہیم پر برکت نازل فرمائی، بے شک تو تعریف کے لائق، بزرگی والا ہے۔ پھر وسیلہ کی دعا: اے اللہ! اس مکمل پکار اور قائم ہونے والی نماز کے رب! محمد ﷺ کو وسیلہ اور فضیلت عطا فرما، اور انہیں اس مقامِ محمود پر پہنچا جس کا تو نے ان سے وعدہ کیا ہے۔","ro":"Ae Allah! Muhammad ﷺ aur Aal-e-Muhammad par rahmat nazil farma jaise tune Ibrahim AS aur Aal-e-Ibrahim par rahmat nazil farmai, beshak tu tareef ke laiq, buzurgi wala hai. Ae Allah! Muhammad ﷺ aur Aal-e-Muhammad par barkat nazil farma jaise tune Ibrahim AS aur Aal-e-Ibrahim par barkat nazil farmai, beshak tu tareef ke laiq, buzurgi wala hai. Phir wasila ki dua: Ae Allah! Is mukammal pukar aur qaim hone wali namaz ke Rab! Muhammad ﷺ ko wasila aur fazilat ata farma, aur unhein us maqam-e-mahmood par pahuncha jiska tune un se wada kiya hai.","hi":"ऐ अल्लाह! मुहम्मद ﷺ और आल-ए-मुहम्मद पर रहमत नाज़िल फ़रमा जैसे तूने इब्राहीम अलैहिस्सलाम और आल-ए-इब्राहीम पर रहमत नाज़िल फ़रमाई, बेशक तू तारीफ़ के लायक़, बुज़ुर्गी वाला है। ऐ अल्लाह! मुहम्मद ﷺ और आल-ए-मुहम्मद पर बरकत नाज़िल फ़रमा जैसे तूने इब्राहीम अलैहिस्सलाम और आल-ए-इब्राहीम पर बरकत नाज़िल फ़रमाई, बेशक तू तारीफ़ के लायक़, बुज़ुर्गी वाला है। फिर वसीले की दुआ: ऐ अल्लाह! इस मुकम्मल पुकार और क़ायम होने वाली नमाज़ के रब! मुहम्मद ﷺ को वसीला और फ़ज़ीलत अता फ़रमा, और उन्हें उस मक़ाम-ए-महमूद पर पहुँचा जिसका तूने उनसे वादा किया है।","en":"O Allah, send blessings upon Muhammad ﷺ and the family of Muhammad, as You sent blessings upon Ibrahim AS and the family of Ibrahim; indeed You are Praiseworthy and Glorious. O Allah, send favour and blessings upon Muhammad ﷺ and the family of Muhammad, as You sent favour and blessings upon Ibrahim AS and the family of Ibrahim; indeed You are Praiseworthy and Glorious. Then the dua for the Wasilah: O Allah, Lord of this perfect call and the prayer that is about to be established, grant Muhammad ﷺ the Wasilah and the Virtue, and raise him to the praised station that You have promised him."},"r":"Sahih Muslim 384; Sahih al-Bukhari 614","n":{"ur":"جو شخص یہ دعا پڑھے، اس کے لیے قیامت کے دن نبی ﷺ کی شفاعت واجب ہو جاتی ہے۔","ro":"Jo shakhs yeh dua padhe, uske liye qayamat ke din Nabi ﷺ ki shafaat wajib ho jati hai.","hi":"जो शख़्स यह दुआ पढ़े, उसके लिए क़यामत के दिन नबी ﷺ की शफ़ाअत वाजिब हो जाती है।","en":"Whoever recites this dua, the intercession of the Prophet ﷺ becomes due for him on the Day of Resurrection."}},{"id":5,"c":"namaz","t":{"ro":"Masjid mein dakhil hote waqt","hi":"मस्जिद में दाख़िल होते वक़्त","en":"When entering the mosque"},"a":"اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ","tl":"Allahummaf tah li abwaba rahmatik","m":{"ur":"اے اللہ! میرے لیے اپنی رحمت کے دروازے کھول دے۔","ro":"Ae Allah! Mere liye apni rahmat ke darwaze khol de.","hi":"ऐ अल्लाह! मेरे लिए अपनी रहमत के दरवाज़े खोल दे।","en":"O Allah, open for me the doors of Your mercy."},"r":"Sahih Muslim 713","n":{"ur":"مسجد میں داخل ہوتے وقت یہ پڑھنا سنت ہے۔","ro":"Masjid mein dakhil hote waqt yeh padhna sunnat hai.","hi":"मस्जिद में दाख़िल होते वक़्त यह पढ़ना सुन्नत है।","en":"It is Sunnah to recite this when entering the mosque."}},{"id":6,"c":"namaz","t":{"ro":"Masjid se nikalte waqt","hi":"मस्जिद से निकलते वक़्त","en":"When leaving the mosque"},"a":"اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ","tl":"Allahumma inni as'aluka min fadlik","m":{"ur":"اے اللہ! میں تجھ سے تیرے فضل کا سوال کرتا ہوں۔","ro":"Ae Allah! Main tujh se tere fazl ka sawal karta hoon.","hi":"ऐ अल्लाह! मैं तुझसे तेरे फ़ज़्ल का सवाल करता हूँ।","en":"O Allah, I ask You for Your bounty."},"r":"Sahih Muslim 713","n":{"ur":"مسجد سے نکلتے وقت یہ دعا پڑھی جاتی ہے۔","ro":"Masjid se nikalte waqt yeh dua padhi jati hai.","hi":"मस्जिद से निकलते वक़्त यह दुआ पढ़ी जाती है।","en":"This dua is recited when leaving the mosque."}},{"id":7,"c":"namaz","t":{"ro":"Istiftah (1) - Allahumma ba'id bayni","hi":"इस्तिफ़्ताह (1) - अल्लाहुम्मा बाइद बैनी","en":"Opening supplication (1) - Allahumma ba'id bayni"},"a":"اللَّهُمَّ بَاعِدْ بَيْنِي وَبَيْنَ خَطَايَايَ كَمَا بَاعَدْتَ بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ، اللَّهُمَّ نَقِّنِي مِنَ الْخَطَايَا كَمَا يُنَقَّى الثَّوْبُ الْأَبْيَضُ مِنَ الدَّنَسِ، اللَّهُمَّ اغْسِلْنِي مِنْ خَطَايَايَ بِالثَّلْجِ وَالْمَاءِ وَالْبَرَدِ","tl":"Allahumma ba'id bayni wa bayna khatayaya kama ba'adta baynal-mashriqi wal-maghrib. Allahumma naqqini minal-khataya kama yunaqqath-thawbul-abyadu minad-danas. Allahummaghsilni min khatayaya bith-thalji wal-ma'i wal-barad.","m":{"ur":"اے اللہ! میرے اور میرے گناہوں کے درمیان اتنی دوری کر دے جتنی تو نے مشرق اور مغرب کے درمیان رکھی ہے۔ اے اللہ! مجھے گناہوں سے ایسے پاک کر دے جیسے سفید کپڑا میل سے صاف کیا جاتا ہے۔ اے اللہ! میرے گناہوں کو برف، پانی اور اولوں سے دھو دے۔","ro":"Ae Allah! Mere aur mere gunahon ke darmiyan itni doori kar de jitni tune mashriq aur maghrib ke darmiyan rakhi hai. Ae Allah! Mujhe gunahon se aise paak kar de jaise safed kapda mail se saaf kiya jata hai. Ae Allah! Mere gunahon ko barf, pani aur olon se dho de.","hi":"ऐ अल्लाह! मेरे और मेरे गुनाहों के दरमियान इतनी दूरी कर दे जितनी तूने मशरिक़ और मग़रिब के दरमियान रखी है। ऐ अल्लाह! मुझे गुनाहों से ऐसे पाक कर दे जैसे सफ़ेद कपड़ा मैल से साफ़ किया जाता है। ऐ अल्लाह! मेरे गुनाहों को बर्फ़, पानी और ओलों से धो दे।","en":"O Allah, put a distance between me and my sins as great as the distance You have put between the east and the west. O Allah, cleanse me of my sins as a white garment is cleansed of dirt. O Allah, wash away my sins with snow, water and hail."},"r":"Sahih al-Bukhari 744; Sahih Muslim 598","n":{"ur":"نماز شروع کرنے کی دعاؤں میں سے ایک ہے۔","ro":"Namaz shuru karne ki duaon mein se ek hai.","hi":"नमाज़ शुरू करने की दुआओं में से एक है।","en":"It is one of the supplications for starting the prayer."}},{"id":8,"c":"namaz","t":{"ro":"Istiftah (2) - Subhanaka Allahumma","hi":"इस्तिफ़्ताह (2) - सुब्हानकल्लाहुम्मा","en":"Opening supplication (2) - Subhanaka Allahumma"},"a":"سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، وَتَبَارَكَ اسْمُكَ، وَتَعَالَى جَدُّكَ، وَلَا إِلَهَ غَيْرُكَ","tl":"Subhanaka Allahumma wa bihamdika, wa tabarakasmuka, wa ta'ala jadduka, wa la ilaha ghayruk","m":{"ur":"اے اللہ! تو پاک ہے اور تیری ہی تعریف ہے، تیرا نام بابرکت ہے، تیری شان بلند ہے اور تیرے سوا کوئی معبود نہیں۔","ro":"Ae Allah! Tu paak hai aur teri hi tareef hai, tera naam barkat wala hai, teri shan buland hai aur tere siwa koi mabood nahin.","hi":"ऐ अल्लाह! तू पाक है और तेरी ही तारीफ़ है, तेरा नाम बरकत वाला है, तेरी शान बुलंद है और तेरे सिवा कोई माबूद नहीं।","en":"O Allah, You are glorified and praised, Your name is blessed, Your majesty is exalted, and there is no deity worthy of worship except You."},"r":"Sunan Abi Dawud 776 - Sahih","n":{"ur":"یہ بھی نماز کی ابتدائی دعا ہے۔","ro":"Yeh bhi namaz ki ibtidai dua hai.","hi":"यह भी नमाज़ की इब्तिदाई दुआ है।","en":"This is also an opening supplication of the prayer."}},{"id":9,"c":"namaz","t":{"ro":"Istiftah (3) - Wajjahtu wajhiya","hi":"इस्तिफ़्ताह (3) - वज्जहतु वज्ही","en":"Opening supplication (3) - Wajjahtu wajhiya"},"a":"وَجَّهْتُ وَجْهِيَ لِلَّذِي فَطَرَ السَّمَاوَاتِ وَالْأَرْضَ حَنِيفًا وَمَا أَنَا مِنَ الْمُشْرِكِينَ، إِنَّ صَلَاتِي وَنُسُكِي وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ، لَا شَرِيكَ لَهُ وَبِذَلِكَ أُمِرْتُ وَأَنَا مِنَ الْمُسْلِمِينَ. اللَّهُمَّ أَنْتَ الْمَلِكُ لَا إِلَهَ إِلَّا أَنْتَ، أَنْتَ رَبِّي وَأَنَا عَبْدُكَ، ظَلَمْتُ نَفْسِي وَاعْتَرَفْتُ بِذَنْبِي فَاغْفِرْ لِي ذُنُوبِي جَمِيعًا، إِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ، وَاهْدِنِي لِأَحْسَنِ الْأَخْلَاقِ لَا يَهْدِي لِأَحْسَنِهَا إِلَّا أَنْتَ، وَاصْرِفْ عَنِّي سَيِّئَهَا لَا يَصْرِفُ عَنِّي سَيِّئَهَا إِلَّا أَنْتَ، لَبَّيْكَ وَسَعْدَيْكَ، وَالْخَيْرُ كُلُّهُ فِي يَدَيْكَ، وَالشَّرُّ لَيْسَ إِلَيْكَ، أَنَا بِكَ وَإِلَيْكَ، تَبَارَكْتَ وَتَعَالَيْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ","tl":"Wajjahtu wajhiya lilladhi fataras-samawati wal-arda hanifan wa ma ana minal-mushrikin. Inna salati wa nusuki wa mahyaya wa mamati lillahi Rabbil-'alamin, la sharika lah, wa bidhalika umirtu wa ana minal-muslimin. Allahumma antal-Maliku la ilaha illa ant, anta Rabbi wa ana 'abduk, zalamtu nafsi wa'taraftu bidhanbi faghfir li dhunubi jami'a, innahu la yaghfirudh-dhunuba illa ant. Wahdini li-ahsanil-akhlaqi la yahdi li-ahsaniha illa ant, wasrif 'anni sayyi'aha la yasrifu 'anni sayyi'aha illa ant. Labbayka wa sa'dayk, wal-khayru kulluhu fi yadayk, wash-sharru laysa ilayk, ana bika wa ilayk, tabarakta wa ta'alayt, astaghfiruka wa atubu ilayk.","m":{"ur":"میں نے اپنا رخ اس ذات کی طرف کر لیا جس نے آسمانوں اور زمین کو پیدا کیا، ہر طرف سے یکسو ہو کر، اور میں مشرکوں میں سے نہیں۔ بے شک میری نماز، میری قربانی، میری زندگی اور میری موت سب اللہ کے لیے ہے جو تمام جہانوں کا رب ہے، اس کا کوئی شریک نہیں، مجھے اسی کا حکم دیا گیا ہے اور میں فرمانبرداروں میں سے ہوں۔ اے اللہ! تو ہی بادشاہ ہے، تیرے سوا کوئی معبود نہیں، تو میرا رب ہے اور میں تیرا بندہ ہوں، میں نے اپنی جان پر ظلم کیا اور اپنے گناہ کا اعتراف کیا، پس میرے سب گناہ بخش دے، بے شک تیرے سوا کوئی گناہ نہیں بخشتا۔ مجھے بہترین اخلاق کی ہدایت دے، تیرے سوا کوئی بہترین اخلاق کی ہدایت نہیں دیتا، اور مجھ سے برے اخلاق دور کر دے، تیرے سوا کوئی انہیں دور نہیں کرتا۔ میں حاضر ہوں اور تیرے حکم کے لیے تیار ہوں، ساری بھلائی تیرے ہاتھ میں ہے اور برائی تیری طرف منسوب نہیں۔ میں تیرے سہارے ہوں اور تیری ہی طرف (میری واپسی) ہے، تو برکت والا اور بلند ہے، میں تجھ سے بخشش مانگتا ہوں اور تیری طرف توبہ کرتا ہوں۔","ro":"Maine apna rukh us zaat ki taraf kar liya jisne aasmanon aur zameen ko paida kiya, har taraf se yaksu hokar, aur main mushrikon mein se nahin. Beshak meri namaz, meri qurbani, meri zindagi aur meri maut sab Allah ke liye hai jo tamam jahanon ka Rab hai, uska koi shareek nahin, mujhe isi ka hukm diya gaya hai aur main farmanbardaron mein se hoon. Ae Allah! Tu hi badshah hai, tere siwa koi mabood nahin, tu mera Rab hai aur main tera banda hoon, maine apni jaan par zulm kiya aur apne gunah ka aitraf kiya, pas mere sab gunah bakhsh de, beshak tere siwa koi gunah nahin bakhshta. Mujhe behtareen akhlaq ki hidayat de, tere siwa koi behtareen akhlaq ki hidayat nahin deta, aur mujh se bure akhlaq door kar de, tere siwa koi unhein door nahin karta. Main hazir hoon aur tere hukm ke liye tayyar hoon, saari bhalai tere haath mein hai aur burai teri taraf mansoob nahin. Main tere sahare hoon aur teri hi taraf (meri wapsi) hai, tu barkat wala aur buland hai, main tujh se bakhshish mangta hoon aur teri taraf tauba karta hoon.","hi":"मैंने अपना रुख़ उस ज़ात की तरफ़ कर लिया जिसने आसमानों और ज़मीन को पैदा किया, हर तरफ़ से यकसू होकर, और मैं मुशरिकों में से नहीं। बेशक मेरी नमाज़, मेरी क़ुर्बानी, मेरी ज़िंदगी और मेरी मौत सब अल्लाह के लिए है जो तमाम जहानों का रब है, उसका कोई शरीक नहीं, मुझे इसी का हुक्म दिया गया है और मैं फ़रमांबरदारों में से हूँ। ऐ अल्लाह! तू ही बादशाह है, तेरे सिवा कोई माबूद नहीं, तू मेरा रब है और मैं तेरा बंदा हूँ, मैंने अपनी जान पर ज़ुल्म किया और अपने गुनाह का ऐतराफ़ किया, पस मेरे सब गुनाह बख़्श दे, बेशक तेरे सिवा कोई गुनाह नहीं बख़्शता। मुझे बेहतरीन अख़लाक़ की हिदायत दे, तेरे सिवा कोई बेहतरीन अख़लाक़ की हिदायत नहीं देता, और मुझसे बुरे अख़लाक़ दूर कर दे, तेरे सिवा कोई उन्हें दूर नहीं करता। मैं हाज़िर हूँ और तेरे हुक्म के लिए तैयार हूँ, सारी भलाई तेरे हाथ में है और बुराई तेरी तरफ़ मंसूब नहीं। मैं तेरे सहारे हूँ और तेरी ही तरफ़ (मेरी वापसी) है, तू बरकत वाला और बुलंद है, मैं तुझसे बख़्शिश माँगता हूँ और तेरी तरफ़ तौबा करता हूँ।","en":"I have turned my face towards the One who created the heavens and the earth, upright and devoted, and I am not among the polytheists. Indeed my prayer, my sacrifice, my life and my death are all for Allah, Lord of all the worlds; He has no partner. This I have been commanded, and I am among those who submit. O Allah, You are the King, there is no deity worthy of worship except You; You are my Lord and I am Your servant. I have wronged myself and I acknowledge my sin, so forgive all my sins, for none forgives sins except You. Guide me to the best of character, for none guides to the best of it except You, and turn the evil of character away from me, for none turns it away except You. Here I am, at Your service and ready for Your command; all goodness is in Your hands, and evil is not attributed to You. I am by Your support and my return is to You; You are Blessed and Exalted. I seek Your forgiveness and turn to You in repentance."},"r":"Sahih Muslim 771","n":{"ur":"نبی ﷺ کی نماز کی ایک اور مسنون دعا ہے۔","ro":"Nabi ﷺ ki namaz ki ek aur masnoon dua hai.","hi":"नबी ﷺ की नमाज़ की एक और मस्नून दुआ है।","en":"This is another Sunnah supplication from the prayer of the Prophet ﷺ."}},{"id":10,"c":"namaz","t":{"ro":"Ta'awwudh","hi":"तअव्वुज़ (अऊज़ु बिल्लाह)","en":"Seeking refuge (Ta'awwudh)"},"a":"أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ","tl":"A'udhu billahi minash-shaytanir-rajim","m":{"ur":"میں شیطان مردود سے اللہ کی پناہ مانگتا ہوں۔","ro":"Main shaitan mardood se Allah ki panah mangta hoon.","hi":"मैं शैतान मरदूद से अल्लाह की पनाह माँगता हूँ।","en":"I seek refuge with Allah from the accursed Satan."},"r":"Surah An-Nahl 16:98","n":{"ur":"قراءت شروع کرنے سے پہلے پڑھی جاتی ہے۔","ro":"Qirat shuru karne se pehle padhi jati hai.","hi":"क़िरअत शुरू करने से पहले पढ़ी जाती है।","en":"It is recited before beginning the recitation."}},{"id":11,"c":"namaz","t":{"ro":"Surah Al-Fatiha","hi":"सूरह अल-फ़ातिहा","en":"Surah Al-Fatiha"},"a":"بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ ﴿١﴾ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ﴿٢﴾ الرَّحْمَٰنِ الرَّحِيمِ ﴿٣﴾ مَالِكِ يَوْمِ الدِّينِ ﴿٤﴾ إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ ﴿٥﴾ اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ ﴿٦﴾ صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ ﴿٧﴾","tl":"Bismillahir-Rahmanir-Rahim. Alhamdu lillahi Rabbil-'alamin. Ar-Rahmanir-Rahim. Maliki yawmid-din. Iyyaka na'budu wa iyyaka nasta'in. Ihdinas-siratal-mustaqim. Siratal-ladhina an'amta 'alayhim, ghayril-maghdubi 'alayhim wa lad-dallin.","m":{"ur":"اللہ کے نام سے جو بہت مہربان، نہایت رحم والا ہے۔ تمام تعریف اللہ کے لیے ہے جو سارے جہانوں کا رب ہے۔ بہت مہربان، نہایت رحم والا۔ بدلے کے دن کا مالک۔ ہم تیری ہی عبادت کرتے ہیں اور تجھی سے مدد مانگتے ہیں۔ ہمیں سیدھے راستے کی ہدایت دے۔ ان لوگوں کے راستے کی جن پر تو نے انعام کیا، نہ ان کے راستے کی جن پر غضب ہوا اور نہ گمراہوں کے۔","ro":"Allah ke naam se jo bahut meherbaan, nihayat rahm wala hai. Tamam tareef Allah ke liye hai jo saare jahanon ka Rab hai. Bahut meherbaan, nihayat rahm wala. Badle ke din ka malik. Hum teri hi ibadat karte hain aur tujhi se madad mangte hain. Hamein seedhe raste ki hidayat de. Un logon ke raste ki jin par tune inaam kiya, na un ke raste ki jin par ghazab hua aur na gumrahon ke.","hi":"अल्लाह के नाम से जो बहुत मेहरबान, निहायत रहम वाला है। तमाम तारीफ़ अल्लाह के लिए है जो सारे जहानों का रब है। बहुत मेहरबान, निहायत रहम वाला। बदले के दिन का मालिक। हम तेरी ही इबादत करते हैं और तुझी से मदद माँगते हैं। हमें सीधे रास्ते की हिदायत दे। उन लोगों के रास्ते की जिन पर तूने इनाम किया, न उनके रास्ते की जिन पर ग़ज़ब हुआ और न गुमराहों के।","en":"In the name of Allah, the Most Gracious, the Most Merciful. All praise is for Allah, Lord of all the worlds. The Most Gracious, the Most Merciful. Master of the Day of Judgement. You alone we worship, and You alone we ask for help. Guide us to the straight path. The path of those You have blessed, not of those who earned anger, nor of those who went astray."},"r":"Sahih al-Bukhari 756; Sahih Muslim 394","n":{"ur":"یہ نماز کا رکن ہے، اس کے بغیر نماز نہیں ہوتی۔","ro":"Yeh namaz ka rukn hai, iske baghair namaz nahin hoti.","hi":"यह नमाज़ का रुक्न है, इसके बग़ैर नमाज़ नहीं होती।","en":"It is a pillar of the prayer; without it the prayer is not valid."}},{"id":12,"c":"namaz","t":{"ro":"Ameen","hi":"आमीन","en":"Ameen"},"a":"آمِين","tl":"Ameen","m":{"ur":"اے اللہ! ہماری دعا قبول فرما۔","ro":"Ae Allah! Hamari dua qubool farma.","hi":"ऐ अल्लाह! हमारी दुआ क़ुबूल फ़रमा।","en":"O Allah, accept our supplication."},"r":"Sahih al-Bukhari 780; Sahih Muslim 410","n":{"ur":"جب امام آمین کہے تو مقتدی بھی آمین کہیں۔","ro":"Jab Imam Ameen kahe to muqtadi bhi Ameen kahen.","hi":"जब इमाम आमीन कहे तो मुक़तदी भी आमीन कहें।","en":"When the Imam says Ameen, the followers should also say Ameen."}},{"id":13,"c":"namaz","t":{"ro":"Ruku ki tasbeeh","hi":"रुकूअ की तस्बीह","en":"Tasbih in Ruku"},"a":"سُبْحَانَ رَبِّيَ الْعَظِيمِ","tl":"Subhana Rabbiyal-'Azim","m":{"ur":"میرا رب پاک ہے، بہت عظمت والا۔","ro":"Mera Rab paak hai, bahut azmat wala.","hi":"मेरा रब पाक है, बहुत अज़मत वाला।","en":"Glory be to my Lord, the Most Great."},"r":"Sahih Muslim 772","n":{"ur":"رکوع میں پڑھی جاتی ہے؛ تین بار پڑھنا بہتر ہے۔","ro":"Ruku mein padhi jaati hai; teen baar padhna behtar hai.","hi":"रुकूअ में पढ़ी जाती है; तीन बार पढ़ना बेहतर है।","en":"Recited in Ruku; reciting it three times is better."}},{"id":14,"c":"namaz","t":{"ro":"Ruku ki dua (Ali RA)","hi":"रुकूअ की दुआ (अली रज़ि.)","en":"Dua in Ruku (Ali RA)"},"a":"اللَّهُمَّ لَكَ رَكَعْتُ، وَبِكَ آمَنْتُ، وَلَكَ أَسْلَمْتُ، خَشَعَ لَكَ سَمْعِي وَبَصَرِي وَمُخِّي وَعَظْمِي وَعَصَبِي","tl":"Allahumma laka raka'tu wa bika amantu wa laka aslamtu, khasha'a laka sam'i wa basari wa mukhkhi wa 'azmi wa 'asabi","m":{"ur":"اے اللہ! میں نے تیرے لیے رکوع کیا، تجھ پر ایمان لایا اور تیرا فرمانبردار ہوا؛ میرے کان، میری آنکھ، میرا مغز، میری ہڈیاں اور میرے پٹھے تیرے لیے جھک گئے۔","ro":"Ae Allah! Maine tere liye ruku kiya, tujh par iman laya aur tera farmanbardar hua; mere kaan, meri aankh, mera maghz, meri haddiyan aur mere patthe tere liye jhuk gaye.","hi":"ऐ अल्लाह! मैंने तेरे लिए रुकूअ किया, तुझ पर ईमान लाया और तेरा फ़रमांबरदार हुआ; मेरे कान, मेरी आँख, मेरा मग़्ज़, मेरी हड्डियाँ और मेरे पट्ठे तेरे लिए झुक गए।","en":"O Allah, I have bowed to You, believed in You and submitted to You; my hearing, my sight, my brain, my bones and my sinews have humbled themselves before You."},"r":"Sahih Muslim 771","n":{"ur":"نبی ﷺ رکوع میں یہ دعا بھی پڑھتے تھے۔","ro":"Nabi ﷺ ruku mein yeh dua bhi padhte the.","hi":"नबी ﷺ रुकूअ में यह दुआ भी पढ़ते थे।","en":"The Prophet ﷺ would also recite this dua in Ruku."}},{"id":15,"c":"namaz","t":{"ro":"Ruku/Sajde mein gunahon ki muafi","hi":"रुकूअ/सज्दे में गुनाहों की माफ़ी","en":"Seeking forgiveness in Ruku and Sajdah"},"a":"سُبْحَانَكَ اللَّهُمَّ رَبَّنَا وَبِحَمْدِكَ، اللَّهُمَّ اغْفِرْ لِي","tl":"Subhanaka Allahumma Rabbana wa bihamdika, Allahummaghfir li","m":{"ur":"اے اللہ! اے ہمارے رب! تو پاک ہے اور تیری ہی حمد ہے، اے اللہ! مجھے بخش دے۔","ro":"Ae Allah! Ae hamare Rab! Tu paak hai aur teri hi hamd hai, ae Allah! Mujhe bakhsh de.","hi":"ऐ अल्लाह! ऐ हमारे रब! तू पाक है और तेरी ही हम्द है, ऐ अल्लाह! मुझे बख़्श दे।","en":"O Allah, our Lord, glory be to You and all praise is Yours; O Allah, forgive me."},"r":"Sahih al-Bukhari 817; Sahih Muslim 484","n":{"ur":"نبی ﷺ رکوع اور سجدے میں یہ دعا پڑھتے تھے۔","ro":"Nabi ﷺ ruku aur sajde mein yeh dua padhte the.","hi":"नबी ﷺ रुकूअ और सज्दे में यह दुआ पढ़ते थे।","en":"The Prophet ﷺ used to recite this dua in Ruku and Sajdah."}},{"id":16,"c":"namaz","t":{"ro":"Ruku/Sajde mein Subbuhun Quddus","hi":"रुकूअ/सज्दे में सुब्बूहुन कुद्दूसुन","en":"Subbuhun Quddus in Ruku and Sajdah"},"a":"سُبُّوحٌ قُدُّوسٌ رَبُّ الْمَلَائِكَةِ وَالرُّوحِ","tl":"Subbuhun Quddusun Rabbul-mala'ikati war-ruh","m":{"ur":"بہت پاک، بہت مقدس، فرشتوں اور جبریل (روح) کا رب۔","ro":"Bahut paak, bahut muqaddas, farishton aur Jibreel (Ruh) ka Rab.","hi":"बहुत पाक, बहुत मुक़द्दस, फ़रिश्तों और जिब्रील (रूह) का रब।","en":"Most Glorious, Most Holy, Lord of the angels and of Jibreel (the Spirit)."},"r":"Sahih Muslim 487","n":{"ur":"نبی ﷺ رکوع اور سجدے میں یہ بھی کہتے تھے۔","ro":"Nabi ﷺ ruku aur sajde mein yeh bhi kahte the.","hi":"नबी ﷺ रुकूअ और सज्दे में यह भी कहते थे।","en":"The Prophet ﷺ would also say this in Ruku and Sajdah."}},{"id":17,"c":"namaz","t":{"ro":"Ruku se uthte hue (Qawmah)","hi":"रुकूअ से उठते हुए (क़ौमा)","en":"Rising from Ruku (Qawmah)"},"a":"سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ، رَبَّنَا وَلَكَ الْحَمْدُ حَمْدًا كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ","tl":"Sami'allahu liman hamidah, Rabbana wa lakal-hamdu hamdan kathiran tayyiban mubarakan fih","m":{"ur":"اللہ نے اس کی سن لی جس نے اس کی حمد کی۔ اے ہمارے رب! تیری ہی حمد ہے، بہت زیادہ، پاکیزہ اور برکت والی حمد۔","ro":"Allah ne uski sun li jisne uski hamd ki. Ae hamare Rab! Teri hi hamd hai, bahut zyada, pakeeza aur barkat wali hamd.","hi":"अल्लाह ने उसकी सुन ली जिसने उसकी हम्द की। ऐ हमारे रब! तेरी ही हम्द है, बहुत ज़्यादा, पाकीज़ा और बरकत वाली हम्द।","en":"Allah hears the one who praises Him. Our Lord, all praise is Yours, abundant, pure and blessed praise."},"r":"Sahih al-Bukhari 799","n":{"ur":"ایک صحابی نے یہ پڑھا تو نبی ﷺ نے فرمایا کہ 30 سے زائد فرشتے اسے لکھنے میں جلدی کر رہے تھے۔","ro":"Ek sahabi ne yeh padha to Nabi ﷺ ne farmaya ke 30 se zaid farishte ise likhne mein jaldi kar rahe the.","hi":"एक सहाबी ने यह पढ़ा तो नबी ﷺ ने फ़रमाया कि 30 से ज़्यादा फ़रिश्ते इसे लिखने में जल्दी कर रहे थे।","en":"A Companion recited this, and the Prophet ﷺ said that more than thirty angels were rushing to record it."}},{"id":18,"c":"namaz","t":{"ro":"Sajde ki tasbeeh","hi":"सज्दे की तस्बीह","en":"Tasbih in Sajdah"},"a":"سُبْحَانَ رَبِّيَ الْأَعْلَى","tl":"Subhana Rabbiyal-A'la","m":{"ur":"میرا رب پاک ہے، سب سے بلند۔","ro":"Mera Rab paak hai, sab se buland.","hi":"मेरा रब पाक है, सबसे बुलंद।","en":"Glory be to my Lord, the Most High."},"r":"Sahih Muslim 772","n":{"ur":"سجدے میں پڑھی جاتی ہے؛ تین بار پڑھنا بہتر ہے۔","ro":"Sajde mein padhi jaati hai; teen baar padhna behtar hai.","hi":"सज्दे में पढ़ी जाती है; तीन बार पढ़ना बेहतर है।","en":"Recited in Sajdah; reciting it three times is better."}},{"id":19,"c":"namaz","t":{"ro":"Sajde ki dua (Ali RA)","hi":"सज्दे की दुआ (अली रज़ि.)","en":"Dua in Sajdah (Ali RA)"},"a":"اللَّهُمَّ لَكَ سَجَدْتُ، وَبِكَ آمَنْتُ، وَلَكَ أَسْلَمْتُ، سَجَدَ وَجْهِي لِلَّذِي خَلَقَهُ وَصَوَّرَهُ، وَشَقَّ سَمْعَهُ وَبَصَرَهُ، تَبَارَكَ اللَّهُ أَحْسَنُ الْخَالِقِينَ","tl":"Allahumma laka sajadtu wa bika amantu wa laka aslamtu, sajada wajhiya lilladhi khalaqahu wa sawwarahu, wa shaqqa sam'ahu wa basarah, tabarakallahu ahsanul-khaliqin.","m":{"ur":"اے اللہ! میں نے تیرے لیے سجدہ کیا، تجھ پر ایمان لایا اور تیرا فرمانبردار ہوا۔ میرا چہرہ اس ذات کے لیے سجدہ ریز ہوا جس نے اسے پیدا کیا، صورت دی اور اس کے کان اور آنکھ کھول دیے۔ اللہ برکت والا ہے، سب سے بہتر پیدا کرنے والا۔","ro":"Ae Allah! Maine tere liye sajda kiya, tujh par iman laya aur tera farmanbardar hua. Mera chehra us zaat ke liye sajda-rez hua jisne use paida kiya, surat di aur uske kaan aur aankh khol diye. Allah barkat wala hai, sab se behtar paida karne wala.","hi":"ऐ अल्लाह! मैंने तेरे लिए सज्दा किया, तुझ पर ईमान लाया और तेरा फ़रमांबरदार हुआ। मेरा चेहरा उस ज़ात के लिए सज्दा-रेज़ हुआ जिसने उसे पैदा किया, सूरत दी और उसके कान और आँख खोल दिए। अल्लाह बरकत वाला है, सबसे बेहतर पैदा करने वाला।","en":"O Allah, I have prostrated to You, believed in You and submitted to You. My face has prostrated to the One who created it, shaped it, and opened its hearing and sight. Blessed is Allah, the Best of creators."},"r":"Sahih Muslim 771","n":{"ur":"نبی ﷺ سجدے میں یہ دعا پڑھتے تھے۔","ro":"Nabi ﷺ sajde mein yeh dua padhte the.","hi":"नबी ﷺ सज्दे में यह दुआ पढ़ते थे।","en":"The Prophet ﷺ used to recite this dua in Sajdah."}},{"id":20,"c":"namaz","t":{"ro":"Sajde mein saare gunahon ki muafi","hi":"सज्दे में सारे गुनाहों की माफ़ी","en":"Seeking forgiveness for all sins in Sajdah"},"a":"اللَّهُمَّ اغْفِرْ لِي ذَنْبِي كُلَّهُ، دِقَّهُ وَجِلَّهُ، وَأَوَّلَهُ وَآخِرَهُ، وَعَلَانِيَتَهُ وَسِرَّهُ","tl":"Allahummaghfir li dhanbi kullahu, diqqahu wa jillahu, wa awwalahu wa akhirahu, wa 'alaniyatahu wa sirrah","m":{"ur":"اے اللہ! میرے سارے گناہ بخش دے، چھوٹے بھی اور بڑے بھی، پہلے بھی اور بعد کے بھی، کھلے بھی اور چھپے بھی۔","ro":"Ae Allah! Mere saare gunah bakhsh de, chhote bhi aur bade bhi, pehle bhi aur baad ke bhi, khule bhi aur chhupe bhi.","hi":"ऐ अल्लाह! मेरे सारे गुनाह बख़्श दे, छोटे भी और बड़े भी, पहले भी और बाद के भी, खुले भी और छुपे भी।","en":"O Allah, forgive all my sins, the small and the great, the first and the last, the open and the secret."},"r":"Sahih Muslim 483","n":{"ur":"سجدہ وہ حالت ہے جب بندہ اپنے رب کے سب سے قریب ہوتا ہے، اس میں دعا کی کثرت کریں۔","ro":"Sajda woh halat hai jab banda apne Rab ke sab se qareeb hota hai, is mein dua ki kasrat karen.","hi":"सज्दा वह हालत है जब बंदा अपने रब के सबसे क़रीब होता है, इसमें दुआ की कसरत करें।","en":"Sajdah is the state in which a servant is closest to his Lord, so make abundant dua in it."}},{"id":21,"c":"namaz","t":{"ro":"Do sajdon ke darmiyan (Jalsa)","hi":"दो सज्दों के दरमियान (जलसा)","en":"Between the two prostrations (Jalsa)"},"a":"رَبِّ اغْفِرْ لِي، رَبِّ اغْفِرْ لِي","tl":"Rabbighfir li, Rabbighfir li","m":{"ur":"اے میرے رب! مجھے بخش دے، اے میرے رب! مجھے بخش دے۔","ro":"Ae mere Rab! Mujhe bakhsh de, ae mere Rab! Mujhe bakhsh de.","hi":"ऐ मेरे रब! मुझे बख़्श दे, ऐ मेरे रब! मुझे बख़्श दे।","en":"My Lord, forgive me; my Lord, forgive me."},"r":"Sunan Ibn Majah 897 - Sahih (Albani: Asl Sifat Salat, 3/809)","n":{"ur":"دو سجدوں کے درمیان یہ دعا پڑھی جاتی ہے۔","ro":"Do sajdon ke darmiyan yeh dua padhi jati hai.","hi":"दो सज्दों के दरमियान यह दुआ पढ़ी जाती है।","en":"This dua is recited between the two prostrations."}},{"id":22,"c":"namaz","t":{"ro":"Do sajdon ke darmiyan mukammal dua","hi":"दो सज्दों के दरमियान मुकम्मल दुआ","en":"Complete dua between the two prostrations"},"a":"اللَّهُمَّ اغْفِرْ لِي، وَارْحَمْنِي، وَاجْبُرْنِي، وَاهْدِنِي، وَارْزُقْنِي","tl":"Allahummaghfir li, warhamni, wajburni, wahdini, warzuqni","m":{"ur":"اے اللہ! مجھے بخش دے، مجھ پر رحم فرما، میری حالت درست کر دے، مجھے ہدایت دے اور مجھے رزق عطا فرما۔","ro":"Ae Allah! Mujhe bakhsh de, mujh par rahm farma, meri halat durust kar de, mujhe hidayat de aur mujhe rizq ata farma.","hi":"ऐ अल्लाह! मुझे बख़्श दे, मुझ पर रहम फ़रमा, मेरी हालत दुरुस्त कर दे, मुझे हिदायत दे और मुझे रिज़्क़ अता फ़रमा।","en":"O Allah, forgive me, have mercy on me, set right my condition, guide me and provide for me."},"r":"Sunan at-Tirmidhi 284; Sunan Ibn Majah 898 - Sahih (Albani: Asl Sifat Salat, 3/809)","n":{"ur":"نبی ﷺ دو سجدوں کے درمیان یہ دعا پڑھتے تھے۔","ro":"Nabi ﷺ do sajdon ke darmiyan yeh dua padhte the.","hi":"नबी ﷺ दो सज्दों के दरमियान यह दुआ पढ़ते थे।","en":"The Prophet ﷺ used to recite this dua between the two prostrations."}},{"id":23,"c":"namaz","t":{"ro":"Tashahhud (At-Tahiyyat)","hi":"तशह्हुद (अत-तहिय्यात)","en":"Tashahhud (At-Tahiyyat)"},"a":"التَّحِيَّاتُ لِلَّهِ وَالصَّلَوَاتُ وَالطَّيِّبَاتُ، السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ","tl":"At-tahiyyatu lillahi was-salawatu wat-tayyibat, as-salamu 'alayka ayyuhan-nabiyyu wa rahmatullahi wa barakatuh, as-salamu 'alayna wa 'ala 'ibadillahis-salihin. Ashhadu an la ilaha illallah, wa ashhadu anna Muhammadan 'abduhu wa rasuluh.","m":{"ur":"تمام قولی، فعلی اور مالی عبادتیں اللہ کے لیے ہیں۔ اے نبی ﷺ! آپ پر سلام ہو اور اللہ کی رحمت اور برکتیں ہوں۔ ہم پر اور اللہ کے نیک بندوں پر بھی سلام ہو۔ میں گواہی دیتا ہوں کہ اللہ کے سوا کوئی معبود نہیں اور میں گواہی دیتا ہوں کہ محمد ﷺ اس کے بندے اور رسول ہیں۔","ro":"Tamam qauli, fa'li aur maali ibadatein Allah ke liye hain. Ae Nabi ﷺ! Aap par salam ho aur Allah ki rahmat aur barkatein hon. Hum par aur Allah ke nek bandon par bhi salam ho. Main gawahi deta hoon ke Allah ke siwa koi mabood nahin aur main gawahi deta hoon ke Muhammad ﷺ uske bande aur rasool hain.","hi":"तमाम क़ौली, फ़ेअली और माली इबादतें अल्लाह के लिए हैं। ऐ नबी ﷺ! आप पर सलाम हो और अल्लाह की रहमत और बरकतें हों। हम पर और अल्लाह के नेक बंदों पर भी सलाम हो। मैं गवाही देता हूँ कि अल्लाह के सिवा कोई माबूद नहीं और मैं गवाही देता हूँ कि मुहम्मद ﷺ उसके बंदे और रसूल हैं।","en":"All verbal, physical and financial acts of worship are for Allah. Peace be upon you, O Prophet ﷺ, and the mercy of Allah and His blessings. Peace be upon us and upon the righteous servants of Allah. I bear witness that there is no deity worthy of worship except Allah, and I bear witness that Muhammad ﷺ is His servant and Messenger."},"r":"Sahih al-Bukhari 831; Sahih Muslim 402","n":{"ur":"یہ نماز کی قعدہ کی دعا ہے، جس کے بعد درود پڑھا جاتا ہے۔","ro":"Yeh namaz ke qaida ki dua hai, jiske baad darood padha jata hai.","hi":"यह नमाज़ के क़ादा की दुआ है, जिसके बाद दरूद पढ़ा जाता है।","en":"This is the dua of the sitting (Qa'dah) in prayer, after which Durood is recited."}},{"id":24,"c":"namaz","t":{"ro":"Darood Ibrahim","hi":"दरूद इब्राहीम","en":"Durood Ibrahim"},"a":"اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ. اللَّهُمَّ بَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا بَارَكْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ","tl":"Allahumma salli 'ala Muhammadin wa 'ala ali Muhammad, kama sallayta 'ala Ibrahima wa 'ala ali Ibrahim, innaka Hamidun Majid. Allahumma barik 'ala Muhammadin wa 'ala ali Muhammad, kama barakta 'ala Ibrahima wa 'ala ali Ibrahim, innaka Hamidun Majid.","m":{"ur":"اے اللہ! محمد ﷺ اور آلِ محمد پر رحمت نازل فرما جیسے تو نے ابراہیم اور آلِ ابراہیم پر رحمت نازل فرمائی، بے شک تو تعریف کے لائق، بزرگی والا ہے۔ اے اللہ! محمد ﷺ اور آلِ محمد پر برکت نازل فرما جیسے تو نے ابراہیم اور آلِ ابراہیم پر برکت نازل فرمائی، بے شک تو تعریف کے لائق، بزرگی والا ہے۔","ro":"Ae Allah! Muhammad ﷺ aur Aal-e-Muhammad par rahmat nazil farma jaise tune Ibrahim AS aur Aal-e-Ibrahim par rahmat nazil farmai, beshak tu tareef ke laiq, buzurgi wala hai. Ae Allah! Muhammad ﷺ aur Aal-e-Muhammad par barkat nazil farma jaise tune Ibrahim AS aur Aal-e-Ibrahim par barkat nazil farmai, beshak tu tareef ke laiq, buzurgi wala hai.","hi":"ऐ अल्लाह! मुहम्मद ﷺ और आल-ए-मुहम्मद पर रहमत नाज़िल फ़रमा जैसे तूने इब्राहीम अलैहिस्सलाम और आल-ए-इब्राहीम पर रहमत नाज़िल फ़रमाई, बेशक तू तारीफ़ के लायक़, बुज़ुर्गी वाला है। ऐ अल्लाह! मुहम्मद ﷺ और आल-ए-मुहम्मद पर बरकत नाज़िल फ़रमा जैसे तूने इब्राहीम अलैहिस्सलाम और आल-ए-इब्राहीम पर बरकत नाज़िल फ़रमाई, बेशक तू तारीफ़ के लायक़, बुज़ुर्गी वाला है।","en":"O Allah, send blessings upon Muhammad ﷺ and the family of Muhammad, as You sent blessings upon Ibrahim AS and the family of Ibrahim; indeed You are Praiseworthy and Glorious. O Allah, send favour and blessings upon Muhammad ﷺ and the family of Muhammad, as You sent favour and blessings upon Ibrahim AS and the family of Ibrahim; indeed You are Praiseworthy and Glorious."},"r":"Sahih al-Bukhari 3370; Sahih Muslim 406","n":{"ur":"آخری قعدے میں تشہد کے بعد درود پڑھنا نبی ﷺ کی تعلیم ہے۔","ro":"Aakhri qa'de mein tashahhud ke baad darood padhna Nabi ﷺ ki taleem hai.","hi":"आख़िरी क़ादे में तशह्हुद के बाद दरूद पढ़ना नबी ﷺ की तालीम है।","en":"Reciting durood after the tashahhud in the final sitting is the teaching of the Prophet ﷺ."}},{"id":25,"c":"namaz","t":{"ro":"Jahannam, qabr aur dajjal se panah","hi":"जहन्नम, क़ब्र और दज्जाल से पनाह","en":"Refuge from Hell, the grave and the Dajjal"},"a":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ جَهَنَّمَ، وَمِنْ عَذَابِ الْقَبْرِ، وَمِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ، وَمِنْ شَرِّ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ","tl":"Allahumma inni a'udhu bika min 'adhabi jahannam, wa min 'adhabil-qabr, wa min fitnatil-mahya wal-mamat, wa min sharri fitnatil-Masihid-Dajjal.","m":{"ur":"اے اللہ! میں تیری پناہ مانگتا ہوں جہنم کے عذاب سے، قبر کے عذاب سے، زندگی اور موت کے فتنے سے، اور مسیح دجال کے فتنے کے شر سے۔","ro":"Ae Allah! Main teri panah mangta hoon jahannam ke azab se, qabr ke azab se, zindagi aur maut ke fitne se, aur Maseeh Dajjal ke fitne ke shar se.","hi":"ऐ अल्लाह! मैं तेरी पनाह माँगता हूँ जहन्नम के अज़ाब से, क़ब्र के अज़ाब से, ज़िंदगी और मौत के फ़ितने से, और मसीह दज्जाल के फ़ितने के शर से।","en":"O Allah, I seek refuge in You from the punishment of Hell, from the punishment of the grave, from the trials of life and death, and from the evil of the trial of the false Messiah, the Dajjal."},"r":"Sahih Muslim 588","n":{"ur":"آخری تشہد کے بعد یہ دعا پڑھی جاتی ہے۔","ro":"Aakhri tashahhud ke baad yeh dua padhi jati hai.","hi":"आख़िरी तशह्हुद के बाद यह दुआ पढ़ी जाती है।","en":"This dua is recited after the final Tashahhud."}},{"id":26,"c":"namaz","t":{"ro":"Salam se pehle (Abu Bakr RA ki dua)","hi":"सलाम से पहले (अबू बक्र रज़ि. की दुआ)","en":"Before the Salam (the dua of Abu Bakr RA)"},"a":"اللَّهُمَّ إِنِّي ظَلَمْتُ نَفْسِي ظُلْمًا كَثِيرًا، وَلَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ، فَاغْفِرْ لِي مَغْفِرَةً مِنْ عِنْدِكَ وَارْحَمْنِي، إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ","tl":"Allahumma inni zalamtu nafsi zulman kathiran, wa la yaghfirudh-dhunuba illa ant, faghfir li maghfiratam-min 'indika warhamni, innaka antal-Ghafurur-Rahim.","m":{"ur":"اے اللہ! میں نے اپنی جان پر بہت ظلم کیا، اور گناہوں کو تیرے سوا کوئی نہیں بخشتا، پس اپنی طرف سے مجھے بخشش عطا فرما اور مجھ پر رحم کر، بے شک تو ہی بخشنے والا، نہایت رحم کرنے والا ہے۔","ro":"Ae Allah! Maine apni jaan par bahut zulm kiya, aur gunahon ko tere siwa koi nahin bakhshta, pas apni taraf se mujhe bakhshish ata farma aur mujh par rahm kar, beshak tu hi bakhshne wala, nihayat rahm karne wala hai.","hi":"ऐ अल्लाह! मैंने अपनी जान पर बहुत ज़ुल्म किया, और गुनाहों को तेरे सिवा कोई नहीं बख़्शता, पस अपनी तरफ़ से मुझे बख़्शिश अता फ़रमा और मुझ पर रहम कर, बेशक तू ही बख़्शने वाला, निहायत रहम करने वाला है।","en":"O Allah, I have greatly wronged myself, and none forgives sins except You. So grant me forgiveness from Yourself and have mercy on me; indeed You are the Forgiving, the Most Merciful."},"r":"Sahih al-Bukhari 834; Sahih Muslim 2705","n":{"ur":"نبی ﷺ نے حضرت ابو بکر رضی اللہ عنہ کو یہ دعا سکھائی تھی۔","ro":"Nabi ﷺ ne Hazrat Abu Bakr RA ko yeh dua sikhai thi.","hi":"नबी ﷺ ने हज़रत अबू बक्र रज़ि. को यह दुआ सिखाई थी।","en":"The Prophet ﷺ taught this dua to Abu Bakr RA."}},{"id":27,"c":"namaz","t":{"ro":"Namaz khatam karne waqt salam","hi":"नमाज़ ख़त्म करते वक़्त सलाम","en":"Salam at the end of the prayer"},"a":"السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ","tl":"As-salamu 'alaykum wa rahmatullah","m":{"ur":"تم پر سلامتی ہو اور اللہ کی رحمت۔","ro":"Tum par salamati ho aur Allah ki rahmat.","hi":"तुम पर सलामती हो और अल्लाह की रहमत।","en":"Peace be upon you and the mercy of Allah."},"r":"Sahih Muslim 582","n":{"ur":"نماز ختم کرتے وقت پہلے دائیں پھر بائیں طرف سلام پھیرا جاتا ہے۔","ro":"Namaz khatam karte waqt pehle dayen phir bayen taraf salam phera jata hai.","hi":"नमाज़ ख़त्म करते वक़्त पहले दाएँ फिर बाएँ तरफ़ सलाम फेरा जाता है।","en":"At the end of the prayer, the Salam is given first to the right and then to the left."}},{"id":28,"c":"namaz","t":{"ro":"Salam ke baad takbir","hi":"सलाम के बाद तकबीर","en":"Takbir after the Salam"},"a":"اللَّهُ أَكْبَرُ","tl":"Allahu Akbar","m":{"ur":"اللہ سب سے بڑا ہے۔","ro":"Allah sab se bada hai.","hi":"अल्लाह सबसे बड़ा है।","en":"Allah is the Greatest."},"r":"Sahih al-Bukhari 842; Sahih Muslim 583","n":{"ur":"نماز کے خاتمے کا اعلان۔","ro":"Namaz ke khatme ka elan.","hi":"नमाज़ के ख़ात्मे का एलान।","en":"An announcement of the end of the prayer."}},{"id":29,"c":"namaz","t":{"ro":"Salam ke baad Istighfar aur Salamati","hi":"सलाम के बाद इस्तिग़फ़ार और सलामती","en":"Istighfar and peace after the Salam"},"a":"أَسْتَغْفِرُ اللَّهَ (3 بار) اللَّهُمَّ أَنْتَ السَّلَامُ وَمِنْكَ السَّلَامُ، تَبَارَكْتَ يَا ذَا الْجَلَالِ وَالْإِكْرَامِ","tl":"Astaghfirullah (3 times). Allahumma antas-salamu wa minkas-salam, tabarakta ya dhal-jalali wal-ikram.","m":{"ur":"میں اللہ سے بخشش مانگتا ہوں (تین بار)۔ اے اللہ! تو سلامتی والا ہے اور تجھ ہی سے سلامتی ہے، تو بابرکت ہے، اے جلال اور اکرام والے۔","ro":"Main Allah se bakhshish mangta hoon (teen baar). Ae Allah! Tu salamati wala hai aur tujh hi se salamati hai, tu barkat wala hai, ae jalal aur ikram wale.","hi":"मैं अल्लाह से बख़्शिश माँगता हूँ (तीन बार)। ऐ अल्लाह! तू सलामती वाला है और तुझ ही से सलामती है, तू बाबरकत है, ऐ जलाल और इकराम वाले।","en":"I seek Allah's forgiveness (three times). O Allah, You are Peace and from You comes peace; blessed are You, O Possessor of Majesty and Honour."},"r":"Sahih Muslim 591","n":{"ur":"نماز کے بعد یہ اذکار پڑھنا سنت ہے۔","ro":"Namaz ke baad yeh azkar padhna sunnat hai.","hi":"नमाज़ के बाद ये अज़्कार पढ़ना सुन्नत है।","en":"It is Sunnah to recite these adhkar after the prayer."}},{"id":30,"c":"namaz","t":{"ro":"Tauheed aur Allah ke ata karne ka iqrar","hi":"तौहीद और अल्लाह के अता करने का इक़रार","en":"Declaration of Tawhid and of Allah's giving"},"a":"لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، اللَّهُمَّ لَا مَانِعَ لِمَا أَعْطَيْتَ، وَلَا مُعْطِيَ لِمَا مَنَعْتَ، وَلَا يَنْفَعُ ذَا الْجَدِّ مِنْكَ الْجَدُّ","tl":"La ilaha illallahu wahdahu la sharika lah, lahul-mulku wa lahul-hamd, wa huwa 'ala kulli shay'in qadir. Allahumma la mani'a lima a'tayt, wa la mu'tiya lima mana't, wa la yanfa'u dhal-jaddi minkal-jadd.","m":{"ur":"اللہ کے سوا کوئی معبود نہیں، وہ اکیلا ہے، اس کا کوئی شریک نہیں، اسی کی بادشاہی ہے، اسی کی حمد ہے اور وہ ہر چیز پر قادر ہے۔ اے اللہ! جو تو دے اسے کوئی روکنے والا نہیں، اور جو تو روک لے اسے کوئی دینے والا نہیں، اور کسی شان والے کو اس کی شان تیرے مقابلے میں فائدہ نہیں دیتی۔","ro":"Allah ke siwa koi mabood nahin, woh akela hai, uska koi shareek nahin, usi ki badshahi hai, usi ki hamd hai aur woh har cheez par qadir hai. Ae Allah! Jo tu de use koi rokne wala nahin, aur jo tu rok le use koi dene wala nahin, aur kisi shan wale ko uski shan tere muqable mein faida nahin deti.","hi":"अल्लाह के सिवा कोई माबूद नहीं, वह अकेला है, उसका कोई शरीक नहीं, उसी की बादशाही है, उसी की हम्द है और वह हर चीज़ पर क़ादिर है। ऐ अल्लाह! जो तू दे उसे कोई रोकने वाला नहीं, और जो तू रोक ले उसे कोई देने वाला नहीं, और किसी शान वाले को उसकी शान तेरे मुक़ाबले में फ़ायदा नहीं देती।","en":"There is no deity worthy of worship except Allah, He is One and has no partner; His is the dominion and His is the praise, and He has power over all things. O Allah, none can withhold what You give, and none can give what You withhold, and the might of the mighty is of no benefit against You."},"r":"Sahih al-Bukhari 844; Sahih Muslim 593","n":{"ur":"ہر فرض نماز کے بعد پڑھنا مسنون ہے۔","ro":"Har farz namaz ke baad padhna masnoon hai.","hi":"हर फ़र्ज़ नमाज़ के बाद पढ़ना मस्नून है।","en":"It is Sunnah to recite this after every obligatory prayer."}},{"id":31,"c":"namaz","t":{"ro":"Tasbeehat: 33+33+33 aur kalima-e-tauheed","hi":"तस्बीहात: 33+33+33 और कलिमा-ए-तौहीद","en":"Tasbihat: 33+33+33 and the Kalimah of Tawhid"},"a":"سُبْحَانَ اللَّهِ (٣٣) الْحَمْدُ لِلَّهِ (٣٣) اللَّهُ أَكْبَرُ (٣٣) ثُمَّ: لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ","tl":"Subhanallah (33), Alhamdulillah (33), Allahu Akbar (33). Phir: La ilaha illallahu wahdahu la sharika lah, lahul-mulku wa lahul-hamd, wa huwa 'ala kulli shay'in qadir.","m":{"ur":"اللہ پاک ہے (۳۳ بار)، تمام تعریف اللہ کے لیے ہے (۳۳ بار)، اللہ سب سے بڑا ہے (۳۳ بار)۔ پھر (سو پورے کرنے کے لیے): اللہ کے سوا کوئی معبود نہیں، وہ اکیلا ہے، اس کا کوئی شریک نہیں، اسی کی بادشاہی ہے، اسی کی حمد ہے اور وہ ہر چیز پر قادر ہے۔","ro":"Allah paak hai (33 baar), tamam tareef Allah ke liye hai (33 baar), Allah sab se bada hai (33 baar). Phir (sau poore karne ke liye): Allah ke siwa koi mabood nahin, woh akela hai, uska koi shareek nahin, usi ki badshahi hai, usi ki hamd hai aur woh har cheez par qadir hai.","hi":"अल्लाह पाक है (33 बार), तमाम तारीफ़ अल्लाह के लिए है (33 बार), अल्लाह सबसे बड़ा है (33 बार)। फिर (सौ पूरे करने के लिए): अल्लाह के सिवा कोई माबूद नहीं, वह अकेला है, उसका कोई शरीक नहीं, उसी की बादशाही है, उसी की हम्द है और वह हर चीज़ पर क़ादिर है।","en":"Allah is glorified (33 times), all praise is for Allah (33 times), Allah is the Greatest (33 times). Then, to complete one hundred: There is no deity worthy of worship except Allah, He is One and has no partner; His is the dominion and His is the praise, and He has power over all things."},"r":"Sahih Muslim 597","n":{"ur":"نماز کے بعد یہ تسبیحات گناہوں کو معاف کرواتی ہیں۔","ro":"Namaz ke baad yeh tasbihat gunahon ko maaf karwati hain.","hi":"नमाज़ के बाद ये तस्बीहात गुनाहों को माफ़ करवाती हैं।","en":"These glorifications after prayer bring forgiveness of sins."}},{"id":32,"c":"namaz","t":{"ro":"Mu'aqqibat: 33+33+34","hi":"मुअक़्क़िबात: 33+33+34","en":"Mu'aqqibat: 33+33+34"},"a":"سُبْحَانَ اللَّهِ (33) الْحَمْدُ لِلَّهِ (33) اللَّهُ أَكْبَرُ (34)","tl":"Subhanallah (33), Alhamdulillah (33), Allahu Akbar (34)","m":{"ur":"اللہ پاک ہے (33)، سب تعریف اللہ کے لیے ہے (33)، اللہ سب سے بڑا ہے (34)۔","ro":"Allah paak hai (33), sab tareef Allah ke liye hai (33), Allah sab se bada hai (34).","hi":"अल्लाह पाक है (33), सब तारीफ़ अल्लाह के लिए है (33), अल्लाह सबसे बड़ा है (34)।","en":"Allah is glorified (33), all praise is for Allah (33), Allah is the Greatest (34)."},"r":"Sahih Muslim 596","n":{"ur":"فرض نماز کے بعد یہ تسبیحات پڑھنا بہت بڑا اجر ہے۔","ro":"Farz namaz ke baad yeh tasbihat padhne ka bahut bada ajr hai.","hi":"फ़र्ज़ नमाज़ के बाद ये तस्बीहात पढ़ने का बहुत बड़ा अज्र है।","en":"There is a great reward in reciting these glorifications after the obligatory prayer."}},{"id":33,"c":"namaz","t":{"ro":"Ayatul Kursi (Har namaz ke baad)","hi":"आयतुल कुर्सी (हर नमाज़ के बाद)","en":"Ayatul Kursi (after every prayer)"},"a":"اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ ۚ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ ۚ لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ ۗ مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ إِلَّا بِمَا شَاءَ ۚ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ ۖ وَلَا يَئُودُهُ حِفْظُهُمَا ۚ وَهُوَ الْعَلِيُّ الْعَظِيمُ","tl":"Allahu la ilaha illa huwal-Hayyul-Qayyum, la ta'khudhuhu sinatun wa la nawm, lahu ma fis-samawati wa ma fil-ard, man dhal-ladhi yashfa'u 'indahu illa bi-idhnih, ya'lamu ma bayna aydihim wa ma khalfahum, wa la yuhituna bishay'im-min 'ilmihi illa bima sha', wasi'a kursiyyuhus-samawati wal-ard, wa la ya'uduhu hifzuhuma, wa huwal-'Aliyyul-'Azim.","m":{"ur":"اللہ کے سوا کوئی معبود نہیں، وہ زندہ ہے، سب کو تھامنے والا ہے۔ اسے نہ اونگھ آتی ہے نہ نیند۔ جو کچھ آسمانوں میں اور زمین میں ہے سب اسی کا ہے۔ کون ہے جو اس کی اجازت کے بغیر اس کے پاس سفارش کرے؟ وہ جانتا ہے جو ان کے سامنے ہے اور جو ان کے پیچھے ہے، اور وہ اس کے علم میں سے کسی چیز کا احاطہ نہیں کر سکتے مگر جتنا وہ چاہے۔ اس کی کرسی آسمانوں اور زمین کو گھیرے ہوئے ہے، اور ان کی حفاظت اسے تھکاتی نہیں، اور وہ بلند و عظمت والا ہے۔","ro":"Allah ke siwa koi mabood nahin, woh zinda hai, sab ko thamne wala hai. Use na unghh aati hai na neend. Jo kuchh aasmanon mein aur zameen mein hai sab usi ka hai. Kaun hai jo uski ijazat ke baghair uske paas sifarish kare? Woh jaanta hai jo unke samne hai aur jo unke peechhe hai, aur woh uske ilm mein se kisi cheez ka ihata nahin kar sakte magar jitna woh chahe. Uski kursi aasmanon aur zameen ko gheray hue hai, aur unki hifazat use thakati nahin, aur woh buland o azmat wala hai.","hi":"अल्लाह के सिवा कोई माबूद नहीं, वह ज़िंदा है, सबको थामने वाला है। उसे न ऊँघ आती है न नींद। जो कुछ आसमानों में और ज़मीन में है सब उसी का है। कौन है जो उसकी इजाज़त के बग़ैर उसके पास सिफ़ारिश करे? वह जानता है जो उनके सामने है और जो उनके पीछे है, और वह उसके इल्म में से किसी चीज़ का इहाता नहीं कर सकते मगर जितना वह चाहे। उसकी कुर्सी आसमानों और ज़मीन को घेरे हुए है, और उनकी हिफ़ाज़त उसे थकाती नहीं, और वह बुलंद व अज़मत वाला है।","en":"Allah, there is no deity worthy of worship except Him, the Ever-Living, the Sustainer of all. Neither drowsiness overtakes Him nor sleep. To Him belongs whatever is in the heavens and whatever is on the earth. Who is there that can intercede with Him except by His permission? He knows what is before them and what is behind them, and they encompass nothing of His knowledge except what He wills. His Kursi extends over the heavens and the earth, and their preservation does not tire Him, and He is the Most High, the Most Great."},"r":"an-Nasa'i (as-Sunan al-Kubra) 9848 - Sahih (Albani: Sahih al-Jami' 6464, as-Sahiha 972)","n":{"ur":"ہر فرض نماز کے بعد پڑھنے سے جنت میں داخلے سے صرف موت روکتی ہے۔","ro":"Har farz namaz ke baad padhne se jannat mein dakhil hone se sirf maut rokti hai.","hi":"हर फ़र्ज़ नमाज़ के बाद पढ़ने से जन्नत में दाख़िल होने से सिर्फ़ मौत रोकती है।","en":"For one who recites it after every obligatory prayer, nothing but death prevents him from entering Paradise."}},{"id":34,"c":"namaz","t":{"ro":"Mu'awwidhat (Teeno Qul)","hi":"मुअव्विज़ात (तीनों क़ुल)","en":"Al-Mu'awwidhat (the three Quls)"},"a":"قُلْ هُوَ اللَّهُ أَحَدٌ ﴿١﴾ اللَّهُ الصَّمَدُ ﴿٢﴾ لَمْ يَلِدْ وَلَمْ يُولَدْ ﴿٣﴾ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ ﴿٤﴾ قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ ﴿١﴾ مِنْ شَرِّ مَا خَلَقَ ﴿٢﴾ وَمِنْ شَرِّ غَاسِقٍ إِذَا وَقَبَ ﴿٣﴾ وَمِنْ شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ ﴿٤﴾ وَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ ﴿٥﴾ قُلْ أَعُوذُ بِرَبِّ النَّاسِ ﴿١﴾ مَلِكِ النَّاسِ ﴿٢﴾ إِلَٰهِ النَّاسِ ﴿٣﴾ مِنْ شَرِّ الْوَسْوَاسِ الْخَنَّاسِ ﴿٤﴾ الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ ﴿٥﴾ مِنَ الْجِنَّةِ وَالنَّاسِ ﴿٦﴾","tl":"Qul huwallahu ahad. Allahus-Samad. Lam yalid wa lam yulad. Wa lam yakun lahu kufuwan ahad. Qul a'udhu bi Rabbil-falaq. Min sharri ma khalaq. Wa min sharri ghasiqin idha waqab. Wa min sharrin-naffathati fil-'uqad. Wa min sharri hasidin idha hasad. Qul a'udhu bi Rabbin-nas. Malikin-nas. Ilahin-nas. Min sharril-waswasil-khannas. Alladhi yuwaswisu fi sudurin-nas. Minal-jinnati wan-nas.","m":{"ur":"کہہ دیجیے: وہ اللہ ایک ہے۔ اللہ بے نیاز ہے۔ نہ اس نے کسی کو جنا اور نہ وہ جنا گیا۔ اور نہ کوئی اس کے برابر کا ہے۔ کہہ دیجیے: میں صبح کے رب کی پناہ میں آتا ہوں، اس کی مخلوق کے شر سے، اور اندھیری رات کے شر سے جب وہ چھا جائے، اور گرہوں میں پھونکنے والیوں کے شر سے، اور حسد کرنے والے کے شر سے جب وہ حسد کرے۔ کہہ دیجیے: میں لوگوں کے رب کی پناہ میں آتا ہوں، لوگوں کے بادشاہ کی، لوگوں کے معبود کی، وسوسہ ڈالنے والے پیچھے ہٹ جانے والے کے شر سے، جو لوگوں کے سینوں میں وسوسے ڈالتا ہے، جنوں میں سے اور انسانوں میں سے۔","ro":"Keh dijiye: Woh Allah ek hai. Allah be-niyaz hai. Na usne kisi ko jana aur na woh jana gaya. Aur na koi uske barabar ka hai. Keh dijiye: Main subah ke Rab ki panah mein aata hoon, uski makhluq ke shar se, aur andheri raat ke shar se jab woh chha jaye, aur girhon mein phoonkne walion ke shar se, aur hasad karne wale ke shar se jab woh hasad kare. Keh dijiye: Main logon ke Rab ki panah mein aata hoon, logon ke badshah ki, logon ke mabood ki, waswasa dalne wale peechhe hat jane wale ke shar se, jo logon ke seenon mein waswase dalta hai, jinnon mein se aur insanon mein se.","hi":"कह दीजिए: वह अल्लाह एक है। अल्लाह बे-नियाज़ है। न उसने किसी को जना और न वह जना गया। और न कोई उसके बराबर का है। कह दीजिए: मैं सुबह के रब की पनाह में आता हूँ, उसकी मख़लूक़ के शर से, और अँधेरी रात के शर से जब वह छा जाए, और गिरहों में फूँकने वालियों के शर से, और हसद करने वाले के शर से जब वह हसद करे। कह दीजिए: मैं लोगों के रब की पनाह में आता हूँ, लोगों के बादशाह की, लोगों के माबूद की, वसवसा डालने वाले पीछे हट जाने वाले के शर से, जो लोगों के सीनों में वसवसे डालता है, जिन्नों में से और इंसानों में से।","en":"Say: He is Allah, the One. Allah is Self-Sufficient. He neither begot nor was begotten. And there is none comparable to Him. Say: I seek refuge in the Lord of the daybreak, from the evil of what He has created, and from the evil of the darkness when it settles, and from the evil of those who blow on knots, and from the evil of the envier when he envies. Say: I seek refuge in the Lord of mankind, the King of mankind, the God of mankind, from the evil of the whispering one who withdraws, who whispers in the hearts of mankind, from among the jinn and mankind."},"r":"Sunan Abi Dawud 1523 - Sahih","n":{"ur":"ہر نماز کے بعد ایک بار، فجر و مغرب میں 3 بار پڑھیں۔","ro":"Har namaz ke baad ek baar, Fajr aur Maghrib mein 3 baar padhen.","hi":"हर नमाज़ के बाद एक बार, फ़ज्र और मग़रिब में 3 बार पढ़ें।","en":"Recite once after every prayer, and 3 times after Fajr and Maghrib."}},{"id":35,"c":"namaz","t":{"ro":"Zikr, Shukr aur Ibadat ki madad","hi":"ज़िक्र, शुक्र और इबादत की मदद","en":"Help to remember Allah, thank Him and worship Him well"},"a":"اللَّهُمَّ أَعِنِّي عَلَى ذِكْرِكَ وَشُكْرِكَ وَحُسْنِ عِبَادَتِكَ","tl":"Allahumma a'inni 'ala dhikrika wa shukrika wa husni 'ibadatik","m":{"ur":"اے اللہ! میری مدد فرما کہ میں تیرا ذکر کروں، تیرا شکر کروں اور بہترین طریقے سے تیری عبادت کروں۔","ro":"Ae Allah! Meri madad farma ke main tera zikr karoon, tera shukr karoon aur behtareen tariqe se teri ibadat karoon.","hi":"ऐ अल्लाह! मेरी मदद फ़रमा कि मैं तेरा ज़िक्र करूँ, तेरा शुक्र करूँ और बेहतरीन तरीक़े से तेरी इबादत करूँ।","en":"O Allah, help me to remember You, to thank You and to worship You in the best manner."},"r":"Sunan Abi Dawud 1522 - Sahih","n":{"ur":"نبی ﷺ نے معاذ رضی اللہ عنہ کو یہ دعا ہر نماز کے بعد کبھی نہ چھوڑنے کی وصیت کی۔","ro":"Nabi ﷺ ne Muaz RA ko yeh dua har namaz ke baad kabhi na chhodne ki wasiyat ki.","hi":"नबी ﷺ ने मुआज़ रज़ि. को यह दुआ हर नमाज़ के बाद कभी न छोड़ने की वसिय्यत की।","en":"The Prophet ﷺ advised Mu'adh RA never to leave this dua after any prayer."}},{"id":36,"c":"namaz","t":{"ro":"Qayamat ke azab se panah","hi":"क़यामत के अज़ाब से पनाह","en":"Refuge from the punishment of the Day of Resurrection"},"a":"رَبِّ قِنِي عَذَابَكَ يَوْمَ تَبْعَثُ عِبَادَكَ","tl":"Rabbi qini 'adhabaka yawma tab'athu 'ibadak","m":{"ur":"اے میرے رب! مجھے اپنے عذاب سے بچا لے، جس دن تو اپنے بندوں کو اٹھائے گا۔","ro":"Ae mere Rab! Mujhe apne azab se bacha le, jis din tu apne bandon ko uthayega.","hi":"ऐ मेरे रब! मुझे अपने अज़ाब से बचा ले, जिस दिन तू अपने बंदों को उठाएगा।","en":"My Lord, protect me from Your punishment on the Day You resurrect Your servants."},"r":"Sahih Muslim 709","n":{"ur":"نبی ﷺ سلام کے بعد یہ دعا پڑھتے تھے۔","ro":"Nabi ﷺ salam ke baad yeh dua padhte the.","hi":"नबी ﷺ सलाम के बाद यह दुआ पढ़ते थे।","en":"The Prophet ﷺ used to recite this dua after the Salam."}},{"id":37,"c":"namaz","t":{"ro":"Namaz ke baad in cheezon se panah","hi":"नमाज़ के बाद इन चीज़ों से पनाह","en":"Seeking refuge from these things after prayer"},"a":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْجُبْنِ، وَأَعُوذُ بِكَ أَنْ أُرَدَّ إِلَى أَرْذَلِ الْعُمُرِ، وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الدُّنْيَا، وَأَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ","tl":"Allahumma inni a'udhu bika minal-jubn, wa a'udhu bika an uradda ila ardhalil-'umur, wa a'udhu bika min fitnatid-dunya, wa a'udhu bika min 'adhabil-qabr.","m":{"ur":"اے اللہ! میں تیری پناہ مانگتا ہوں بزدلی سے، اور تیری پناہ مانگتا ہوں اس سے کہ مجھے سب سے نکمے بڑھاپے کی طرف لوٹا دیا جائے، اور تیری پناہ مانگتا ہوں دنیا کے فتنے سے، اور تیری پناہ مانگتا ہوں قبر کے عذاب سے۔","ro":"Ae Allah! Main teri panah mangta hoon buzdili se, aur teri panah mangta hoon is se ke mujhe sab se nikamme budhape ki taraf lauta diya jaye, aur teri panah mangta hoon duniya ke fitne se, aur teri panah mangta hoon qabr ke azab se.","hi":"ऐ अल्लाह! मैं तेरी पनाह माँगता हूँ बुज़दिली से, और तेरी पनाह माँगता हूँ इससे कि मुझे सबसे निकम्मे बुढ़ापे की तरफ़ लौटा दिया जाए, और तेरी पनाह माँगता हूँ दुनिया के फ़ितने से, और तेरी पनाह माँगता हूँ क़ब्र के अज़ाब से।","en":"O Allah, I seek refuge in You from cowardice, and I seek refuge in You from being returned to the worst old age, and I seek refuge in You from the trial of this world, and I seek refuge in You from the punishment of the grave."},"r":"Sahih al-Bukhari 2822","n":{"ur":"حضرت سعد رضی اللہ عنہ اپنے بچوں کو یہ دعا اس طرح سکھاتے جیسے لکھنا سکھاتے ہیں۔","ro":"Hazrat Sa'd RA apne bachchon ko yeh dua is tarah sikhate jaise likhna sikhate.","hi":"हज़रत सअद रज़ि. अपने बच्चों को यह दुआ इस तरह सिखाते जैसे लिखना सिखाते।","en":"Sa'd RA used to teach this dua to his children just as he taught them writing."}},{"id":38,"c":"namaz","t":{"ro":"Fajr ke baad: ilm, rizq aur amal ki dua","hi":"फ़ज्र के बाद: इल्म, रिज़्क़ और अमल की दुआ","en":"After Fajr: dua for knowledge, provision and deeds"},"a":"اللَّهُمَّ إِنِّي أَسْأَلُكَ عِلْمًا نَافِعًا، وَرِزْقًا طَيِّبًا، وَعَمَلًا مُتَقَبَّلًا","tl":"Allahumma inni as'aluka 'ilman nafi'an, wa rizqan tayyiban, wa 'amalan mutaqabbalan","m":{"ur":"اے اللہ! میں تجھ سے نفع بخش علم، پاکیزہ (حلال) رزق اور مقبول عمل کا سوال کرتا ہوں۔","ro":"Ae Allah! Main tujh se nafa bakhsh ilm, pakeeza (halal) rizq aur maqbool amal ka sawal karta hoon.","hi":"ऐ अल्लाह! मैं तुझसे नफ़ा बख़्श इल्म, पाकीज़ा (हलाल) रिज़्क़ और मक़बूल अमल का सवाल करता हूँ।","en":"O Allah, I ask You for beneficial knowledge, pure (halal) provision and accepted deeds."},"r":"Sunan Ibn Majah 925 (Albani: Ibn Majah ki sanad mein ek majhul raawi hai, magar Tabarani ki jayyid sanad se saabit — Tamam al-Minna, p. 233)","n":{"ur":"صرف فجر کی نماز کے بعد پڑھی جاتی ہے۔","ro":"Sirf Fajr ki namaz ke baad padhi jati hai.","hi":"सिर्फ़ फ़ज्र की नमाज़ के बाद पढ़ी जाती है।","en":"It is recited only after the Fajr prayer."}},{"id":39,"c":"namaz","t":{"ro":"Panj waqta farz namaz","hi":"पाँच वक़्त की फ़र्ज़ नमाज़","en":"The five daily obligatory prayers"},"a":"إِنَّ الصَّلَاةَ كَانَتْ عَلَى الْمُؤْمِنِينَ كِتَابًا مَوْقُوتًا","tl":"Fajr 2, Zuhr 4, Asr 4, Maghrib 3, Isha 4 rak'at (farz). Inna as-salata kanat 'alal-mu'minina kitaban mawquta.","m":{"ur":"بے شک نماز مومنوں پر مقررہ اوقات میں فرض ہے۔ فجر ۲، ظہر ۴، عصر ۴، مغرب ۳ اور عشاء ۴ رکعت۔","ro":"Beshak namaz momino par muqarrara auqat mein farz hai. Fajr 2, Zuhr 4, Asr 4, Maghrib 3 aur Isha 4 rakat.","hi":"बेशक नमाज़ मोमिनों पर मुक़र्रर औक़ात में फ़र्ज़ है। फ़ज्र 2, ज़ुहर 4, अस्र 4, मग़रिब 3 और इशा 4 रकअत।","en":"Indeed, prayer is prescribed for the believers at fixed times. Fajr 2, Zuhr 4, Asr 4, Maghrib 3 and Isha 4 rak'ahs."},"r":"Sahih al-Bukhari 8; Sahih Muslim 16; Surah an-Nisa 4:103","n":{"ur":"اسلام کا ستون۔ مردوں کے لیے مسجد میں جماعت سے پڑھنا تاکیدی ہے۔","ro":"Islam ka sutoon. Mardon ke liye masjid mein jamaat se padhna takeedi hai.","hi":"इस्लाम का सुतून। मर्दों के लिए मस्जिद में जमाअत से पढ़ना ताकीदी है।","en":"A pillar of Islam. For men, praying in congregation in the mosque is strongly emphasized."}},{"id":40,"c":"namaz","t":{"ro":"Sunnat-e-Mu'akkadah (Rawatib) - 12 rak'at","hi":"सुन्नत-ए-मुअक्कदा (रवातिब) - 12 रकअत","en":"Sunnah Mu'akkadah (Rawatib) - 12 rak'ahs"},"a":"","tl":"Fajr 2, Zuhr 4+2, Maghrib 2, Isha 2","m":{"ur":"فرض کے علاوہ روزانہ 12 رکعت سنتیں پڑھنے والے کے لیے جنت میں گھر ہے۔","ro":"Farz ke ilawa rozana 12 rakat sunnatein padhne wale ke liye jannat mein ghar hai.","hi":"फ़र्ज़ के अलावा रोज़ाना 12 रकअत सुन्नतें पढ़ने वाले के लिए जन्नत में घर है।","en":"Whoever prays twelve rak'ahs of Sunnah every day besides the obligatory prayers has a house in Paradise."},"r":"Sahih Muslim 728; Sahih al-Bukhari 1180","n":{"ur":"یہ تاکید والی سنتیں ہیں جو فرض کے ساتھ پڑھی جاتی ہیں۔","ro":"Yeh takeed wali sunnatein hain jo farz ke sath padhi jati hain.","hi":"ये ताकीद वाली सुन्नतें हैं जो फ़र्ज़ के साथ पढ़ी जाती हैं।","en":"These are the emphasized Sunnah prayers that are offered along with the obligatory prayers."}},{"id":41,"c":"namaz","t":{"ro":"Fajr ki do sunnatein","hi":"फ़ज्र की दो सुन्नतें","en":"The two Sunnah rak'ahs of Fajr"},"a":"","tl":"Fajr ki farz se pehle 2 rak'at","m":{"ur":"فجر کی دو سنتیں دنیا اور جو کچھ اس میں ہے اس سے بہتر ہیں۔","ro":"Fajr ki do sunnatein duniya aur jo kuchh is mein hai us se behtar hain.","hi":"फ़ज्र की दो सुन्नतें दुनिया और जो कुछ इसमें है उससे बेहतर हैं।","en":"The two rak'ahs of Fajr are better than the world and everything in it."},"r":"Sahih Muslim 725","n":{"ur":"یہ بہت ہلکی اور مختصر پڑھی جاتی ہیں۔","ro":"Yeh bahut halki aur mukhtasar padhi jati hain.","hi":"ये बहुत हल्की और मुख़्तसर पढ़ी जाती हैं।","en":"They are prayed very light and brief."}},{"id":42,"c":"namaz","t":{"ro":"Witr","hi":"वित्र","en":"Witr"},"a":"","tl":"Isha ke baad se Fajr tak, 1, 3, 5, 7, 9 ya 11 rak'at","m":{"ur":"رات کی نماز دو دو رکعت ہے، پھر ایک رکعت ملا کر وتر بنا لیں۔","ro":"Raat ki namaz do do rakat hai, phir ek rakat mila kar witr bana len.","hi":"रात की नमाज़ दो दो रकअत है, फिर एक रकअत मिला कर वित्र बना लें।","en":"The night prayer is two by two; then add one rak'ah to make it Witr."},"r":"Sahih al-Bukhari 990; Sahih Muslim 749","n":{"ur":"رات کی آخری نماز۔","ro":"Raat ki aakhri namaz.","hi":"रात की आख़िरी नमाज़।","en":"The last prayer of the night."}},{"id":43,"c":"namaz","t":{"ro":"Witr ki dua-e-Qunoot","hi":"वित्र की दुआ-ए-क़ुनूत","en":"Dua Qunoot of Witr"},"a":"اللَّهُمَّ اهْدِنِي فِيمَنْ هَدَيْتَ، وَعَافِنِي فِيمَنْ عَافَيْتَ، وَتَوَلَّنِي فِيمَنْ تَوَلَّيْتَ، وَبَارِكْ لِي فِيمَا أَعْطَيْتَ، وَقِنِي شَرَّ مَا قَضَيْتَ، فَإِنَّكَ تَقْضِي وَلَا يُقْضَى عَلَيْكَ، وَإِنَّهُ لَا يَذِلُّ مَنْ وَالَيْتَ، وَلَا يَعِزُّ مَنْ عَادَيْتَ، تَبَارَكْتَ رَبَّنَا وَتَعَالَيْتَ","tl":"Allahummahdini fiman hadayt, wa 'afini fiman 'afayt, wa tawallani fiman tawallayt, wa barik li fima a'tayt, wa qini sharra ma qadayt, fa-innaka taqdi wa la yuqda 'alayk, wa innahu la yadhillu man walayt, wa la ya'izzu man 'adayt, tabarakta Rabbana wa ta'alayt.","m":{"ur":"اے اللہ! مجھے ان میں ہدایت دے جنہیں تو نے ہدایت دی، مجھے ان میں عافیت دے جنہیں تو نے عافیت دی، مجھے ان میں اپنا دوست بنا جنہیں تو نے اپنا دوست بنایا، جو کچھ تو نے مجھے دیا اس میں برکت دے، اور مجھے اس برے فیصلے سے بچا جو تو نے کیا، کیونکہ تو ہی فیصلہ کرتا ہے اور تجھ پر کوئی فیصلہ نہیں کیا جا سکتا؛ جسے تو اپنا دوست بنا لے وہ کبھی ذلیل نہیں ہوتا اور جس سے تو دشمنی کرے وہ کبھی عزت نہیں پاتا۔ اے ہمارے رب! تو برکت والا اور بلند ہے۔","ro":"Ae Allah! Mujhe un mein hidayat de jinhein tune hidayat di, mujhe un mein afiyat de jinhein tune afiyat di, mujhe un mein apna dost bana jinhein tune apna dost banaya, jo kuchh tune mujhe diya us mein barkat de, aur mujhe us bure faisle se bacha jo tune kiya, kyunke tu hi faisla karta hai aur tujh par koi faisla nahin kiya ja sakta; jise tu apna dost bana le woh kabhi zaleel nahin hota aur jis se tu dushmani kare woh kabhi izzat nahin pata. Ae hamare Rab! Tu barkat wala aur buland hai.","hi":"ऐ अल्लाह! मुझे उनमें हिदायत दे जिन्हें तूने हिदायत दी, मुझे उनमें आफ़ियत दे जिन्हें तूने आफ़ियत दी, मुझे उनमें अपना दोस्त बना जिन्हें तूने अपना दोस्त बनाया, जो कुछ तूने मुझे दिया उसमें बरकत दे, और मुझे उस बुरे फ़ैसले से बचा जो तूने किया, क्योंकि तू ही फ़ैसला करता है और तुझ पर कोई फ़ैसला नहीं किया जा सकता; जिसे तू अपना दोस्त बना ले वह कभी ज़लील नहीं होता और जिससे तू दुश्मनी करे वह कभी इज़्ज़त नहीं पाता। ऐ हमारे रब! तू बरकत वाला और बुलंद है।","en":"O Allah, guide me among those You have guided, grant me well-being among those You have granted well-being, take me as a close friend among those You have taken as close friends, bless me in what You have given me, and protect me from the evil of what You have decreed; for You decree and none can decree against You. He whom You take as a friend is never humiliated, and he whom You take as an enemy is never honoured. Our Lord, You are Blessed and Exalted."},"r":"Sunan Abi Dawud 1425 - Sahih (Albani: Sahih Sunan an-Nasa'i 1647; Asl Sifat Salat 3/973)","n":{"ur":"وتر کی دعا جو نبی ﷺ نے حضرت حسنؓ کو سکھائی۔","ro":"Witr ki dua jo Nabi ﷺ ne Hazrat Hasan RA ko sikhayi.","hi":"वित्र की दुआ जो नबी ﷺ ने हज़रत हसन रज़ि. को सिखाई।","en":"A supplication for Witr that the Prophet ﷺ taught to al-Hasan (RA)."}},{"id":44,"c":"namaz","t":{"ro":"Witr ke baad: Subhanal-Malikil-Quddus","hi":"वित्र के बाद: सुब्हानल-मलिकिल-क़ुद्दूस","en":"After Witr: Subhanal-Malikil-Quddus"},"a":"سُبْحَانَ الْمَلِكِ الْقُدُّوسِ","tl":"Subhanal-Malikil-Quddus","m":{"ur":"پاک ہے وہ بادشاہ جو ہر عیب سے پاک ہے۔","ro":"Paak hai woh badshah jo har aib se paak hai.","hi":"पाक है वह बादशाह जो हर ऐब से पाक है।","en":"Glory be to the King, the Most Holy."},"r":"Sunan an-Nasa'i 1700 - Sahih","n":{"ur":"وتر کے سلام کے بعد 3 بار، تیسری بار آواز بلند کر کے۔","ro":"Witr ke salam ke baad 3 baar, teesri baar awaz buland karke.","hi":"वित्र के सलाम के बाद 3 बार, तीसरी बार आवाज़ बुलंद करके।","en":"Say it 3 times after the Salam of Witr, raising the voice the third time."}},{"id":45,"c":"namaz","t":{"ro":"Tahajjud / Qiyam-ul-Layl","hi":"तहज्जुद / क़ियामुल-लैल","en":"Tahajjud / Qiyam al-Layl"},"a":"","tl":"Raat ka aakhri hissa, 2-2 rak'at, aksar 11 rak'at (witr samet)","m":{"ur":"فرض کے بعد سب سے افضل نماز رات کی نماز ہے۔","ro":"Farz ke baad sab se afzal namaz raat ki namaz hai.","hi":"फ़र्ज़ के बाद सबसे अफ़ज़ल नमाज़ रात की नमाज़ है।","en":"The best prayer after the obligatory prayers is the night prayer."},"r":"Sahih Muslim 1163; Sahih al-Bukhari 1145","n":{"ur":"رات کے آخری تہائی حصے میں اللہ کی خاص رحمت کا وقت ہوتا ہے۔","ro":"Raat ke aakhri tihai hisse mein Allah ki khaas rahmat ka waqt hota hai.","hi":"रात के आख़िरी तिहाई हिस्से में अल्लाह की ख़ास रहमत का वक़्त होता है।","en":"The last third of the night is a time of Allah's special mercy."}},{"id":46,"c":"namaz","t":{"ro":"Tarawih (Qiyam-e-Ramadan)","hi":"तरावीह (क़ियाम-ए-रमज़ान)","en":"Tarawih (Qiyam of Ramadan)"},"a":"","tl":"Ramzan ki raaton mein Isha ke baad","m":{"ur":"جو رمضان میں ایمان اور ثواب کی نیت سے قیام کرے، اس کے پچھلے گناہ معاف کر دیے جاتے ہیں۔","ro":"Jo Ramzan mein iman aur sawab ki niyat se qiyam kare, uske pichhle gunah maaf kar diye jate hain.","hi":"जो रमज़ान में ईमान और सवाब की नीयत से क़ियाम करे, उसके पिछले गुनाह माफ़ कर दिए जाते हैं।","en":"Whoever stands in prayer during Ramadan out of faith and seeking reward, his previous sins are forgiven."},"r":"Sahih al-Bukhari 37; Sahih Muslim 759","n":{"ur":"رمضان میں رات کی نماز۔","ro":"Ramzan mein raat ki namaz.","hi":"रमज़ान में रात की नमाज़।","en":"The night prayer in Ramadan."}},{"id":47,"c":"namaz","t":{"ro":"Salat-ud-Duha (Chasht)","hi":"सलातुज़-ज़ुहा (चाश्त)","en":"Salat ad-Duha (Chasht)"},"a":"","tl":"Suraj buland hone ke baad se zawal se pehle tak, kam az kam 2 rak'at","m":{"ur":"ہر جوڑ کے صدقے کے بدلے دو رکعت کافی ہیں۔","ro":"Har jod ke sadqe ke badle do rakat kafi hain.","hi":"हर जोड़ के सदक़े के बदले दो रकअत काफ़ी हैं।","en":"Two rak'ahs suffice in place of the charity owed for every joint."},"r":"Sahih Muslim 720","n":{"ur":"چاشت کے وقت پڑھی جاتی ہے۔","ro":"Chasht ke waqt padhi jati hai.","hi":"चाश्त के वक़्त पढ़ी जाती है।","en":"It is prayed at the time of Duha (mid-morning)."}},{"id":48,"c":"namaz","t":{"ro":"Tahiyyat-ul-Masjid","hi":"तहिय्यतुल-मस्जिद","en":"Tahiyyat al-Masjid"},"a":"","tl":"Masjid mein dakhil hone par baithne se pehle 2 rak'at","m":{"ur":"جب تم میں سے کوئی مسجد میں داخل ہو تو بیٹھنے سے پہلے دو رکعت پڑھ لے۔","ro":"Jab tum mein se koi masjid mein dakhil ho to baithne se pehle do rakat padh le.","hi":"जब तुम में से कोई मस्जिद में दाख़िल हो तो बैठने से पहले दो रकअत पढ़ ले।","en":"When any of you enters the mosque, let him pray two rak'ahs before sitting."},"r":"Sahih al-Bukhari 444; Sahih Muslim 714","n":{"ur":"مسجد کا حق۔","ro":"Masjid ka haq.","hi":"मस्जिद का हक़।","en":"The due right of the mosque."}},{"id":49,"c":"namaz","t":{"ro":"Tahiyyat-ul-Wudu","hi":"तहिय्यतुल-वुज़ू","en":"Tahiyyat al-Wudu"},"a":"","tl":"Wudu ke baad 2 rak'at","m":{"ur":"وضو کے بعد دو رکعت پڑھنا حضرت بلال رضی اللہ عنہ کا معمول تھا۔","ro":"Wudu ke baad do rakat padhna Hazrat Bilal RA ka mamool tha.","hi":"वुज़ू के बाद दो रकअत पढ़ना हज़रत बिलाल रज़ि. का मामूल था।","en":"Praying two rak'ahs after wudu was the habit of Bilal RA."},"r":"Sahih al-Bukhari 1149; Sahih Muslim 2458","n":{"ur":"جس پر نبی ﷺ نے انہیں جنت کی خوشخبری دی۔","ro":"Jis par Nabi ﷺ ne unhein jannat ki khushkhabri di.","hi":"जिस पर नबी ﷺ ने उन्हें जन्नत की ख़ुशख़बरी दी।","en":"For this the Prophet ﷺ gave him the glad tidings of Paradise."}},{"id":50,"c":"namaz","t":{"ro":"Maghrib se pehle 2 rak'at","hi":"मग़रिब से पहले 2 रकअत","en":"Two rak'ahs before Maghrib"},"a":"","tl":"Maghrib ki azan aur iqamat ke darmiyan 2 rak'at","m":{"ur":"مغرب سے پہلے نماز پڑھو (جو چاہے)۔","ro":"Maghrib se pehle namaz padho (jo chahe).","hi":"मग़रिब से पहले नमाज़ पढ़ो (जो चाहे)।","en":"Pray before Maghrib (for whoever wishes)."},"r":"Sahih al-Bukhari 1183","n":{"ur":"یہ سنت غیر مؤکدہ ہے۔","ro":"Yeh sunnat ghair muakkadah hai.","hi":"यह सुन्नत ग़ैर मुअक्कदा है।","en":"This is a non-emphasized (ghayr mu'akkadah) Sunnah."}},{"id":51,"c":"namaz","t":{"ro":"Salat-ut-Taubah","hi":"सलातुत-तौबा","en":"Salat at-Tawbah"},"a":"","tl":"Gunah ho jane ke baad 2 rak'at","m":{"ur":"جو گناہ کرے پھر وضو کر کے دو رکعت پڑھے اور استغفار کرے، اللہ اسے بخش دیتا ہے۔","ro":"Jo gunah kare phir wudu karke do rakat padhe aur istighfar kare, Allah use bakhsh deta hai.","hi":"जो गुनाह करे फिर वुज़ू करके दो रकअत पढ़े और इस्तिग़फ़ार करे, अल्लाह उसे बख़्श देता है।","en":"Whoever commits a sin, then performs wudu, prays two rak'ahs and seeks forgiveness, Allah forgives him."},"r":"Sunan Abi Dawud 1521 - Sahih","n":{"ur":"توبہ کی نماز۔","ro":"Tauba ki namaz.","hi":"तौबा की नमाज़।","en":"The prayer of repentance."}},{"id":52,"c":"namaz","t":{"ro":"Jumu'ah ki namaz","hi":"जुमुअा की नमाज़","en":"The Jumu'ah prayer"},"a":"","tl":"Jumu'ah ke din Zuhr ke bajaye 2 rak'at farz","m":{"ur":"جمعہ کے دن نماز کے لیے پکارا جائے تو اللہ کے ذکر کی طرف دوڑو۔","ro":"Jumua ke din namaz ke liye pukara jaye to Allah ke zikr ki taraf daudo.","hi":"जुमुअा के दिन नमाज़ के लिए पुकारा जाए तो अल्लाह के ज़िक्र की तरफ़ दौड़ो।","en":"When the call to prayer is made on Friday, hasten to the remembrance of Allah."},"r":"Surah Al-Jumu'ah 62:9","n":{"ur":"مردوں پر فرض ہے۔","ro":"Mardon par farz hai.","hi":"मर्दों पर फ़र्ज़ है।","en":"It is obligatory upon men."}},{"id":53,"c":"namaz","t":{"ro":"Eidain ki namaz","hi":"ईदैन की नमाज़","en":"The two Eid prayers"},"a":"","tl":"Eid ul-Fitr aur Eid ul-Adha, 2 rak'at (khutbe se pehle)","m":{"ur":"نبی ﷺ عید کے دن عیدگاہ جاتے، پہلے نماز پڑھتے پھر خطبہ دیتے۔","ro":"Nabi ﷺ Eid ke din Eidgah jate, pehle namaz padhte phir khutba dete.","hi":"नबी ﷺ ईद के दिन ईदगाह जाते, पहले नमाज़ पढ़ते फिर ख़ुत्बा देते।","en":"On the day of Eid the Prophet ﷺ would go out to the Eidgah, pray first and then deliver the sermon."},"r":"Sahih al-Bukhari 956; Sahih Muslim 889","n":{"ur":"عید کی نماز۔","ro":"Eid ki namaz.","hi":"ईद की नमाज़।","en":"The Eid prayer."}},{"id":54,"c":"namaz","t":{"ro":"Namaz-e-Janazah","hi":"नमाज़-ए-जनाज़ा","en":"The funeral prayer (Janazah)"},"a":"","tl":"4 takbirat, bina ruku aur sajde ke","m":{"ur":"جنازے کے ساتھ چلنے والے کو ایک قیراط کا ثواب ہے۔","ro":"Janaze ke sath chalne wale ko ek qirat ka sawab hai.","hi":"जनाज़े के साथ चलने वाले को एक क़ीरात का सवाब है।","en":"Whoever accompanies a funeral receives a reward of one qirat."},"r":"Sahih al-Bukhari 1325; Sahih Muslim 945","n":{"ur":"فرض کفایہ۔","ro":"Farz-e-kifaya.","hi":"फ़र्ज़-ए-किफ़ाया।","en":"A communal obligation (fard kifayah)."}},{"id":55,"c":"namaz","t":{"ro":"Namaz-e-Kusuf","hi":"नमाज़-ए-कुसूफ़","en":"The eclipse prayer (Kusuf)"},"a":"","tl":"Suraj/chand grahan par 2 rak'at, har rak'at mein do ruku","m":{"ur":"سورج اور چاند اللہ کی نشانیاں ہیں، گرہن لگے تو نماز پڑھو، دعا کرو اور صدقہ دو۔","ro":"Sooraj aur chand Allah ki nishaniyan hain, grahan lage to namaz padho, dua karo aur sadqa do.","hi":"सूरज और चाँद अल्लाह की निशानियाँ हैं, ग्रहण लगे तो नमाज़ पढ़ो, दुआ करो और सदक़ा दो।","en":"The sun and the moon are signs of Allah; when an eclipse occurs, pray, make dua and give charity."},"r":"Sahih al-Bukhari 1044; Sahih Muslim 901","n":{"ur":"گرہن کی نماز۔","ro":"Grahan ki namaz.","hi":"ग्रहण की नमाज़।","en":"The prayer of the eclipse."}},{"id":56,"c":"namaz","t":{"ro":"Namaz-e-Istisqa","hi":"नमाज़-ए-इस्तिस्क़ा","en":"The prayer for rain (Istisqa)"},"a":"","tl":"Khushk-sali ke waqt khule maidan mein 2 rak'at","m":{"ur":"نبی ﷺ بارش کی دعا کے لیے میدان میں نکلے، قبلہ کی طرف منہ کیا، چادر الٹی اور دو رکعت پڑھیں۔","ro":"Nabi ﷺ barish ki dua ke liye maidan mein nikle, qibla ki taraf munh kiya, chadar ulti aur do rakat padhin.","hi":"नबी ﷺ बारिश की दुआ के लिए मैदान में निकले, क़िब्ला की तरफ़ मुँह किया, चादर उल्टी और दो रकअत पढ़ीं।","en":"The Prophet ﷺ went out to the open ground to pray for rain, faced the Qiblah, turned his cloak inside out and prayed two rak'ahs."},"r":"Sahih al-Bukhari 1012; Sahih Muslim 894","n":{"ur":"بارش کی نماز۔","ro":"Barish ki namaz.","hi":"बारिश की नमाज़।","en":"The prayer for rain."}},{"id":57,"c":"namaz","t":{"ro":"Safar mein namaz ka qasr","hi":"सफ़र में नमाज़ का क़स्र","en":"Shortening the prayer while travelling"},"a":"","tl":"Zuhr, Asr, Isha ki 4 rak'at ki jagah 2 rak'at","m":{"ur":"یہ ایک صدقہ ہے جو اللہ نے تم پر کیا ہے، اسے قبول کرو۔","ro":"Yeh ek sadqa hai jo Allah ne tum par kiya hai, ise qubool karo.","hi":"यह एक सदक़ा है जो अल्लाह ने तुम पर किया है, इसे क़ुबूल करो।","en":"This is a charity that Allah has bestowed upon you, so accept His charity."},"r":"Sahih Muslim 686","n":{"ur":"سفر میں قصر۔","ro":"Safar mein qasr.","hi":"सफ़र में क़स्र।","en":"Shortening the prayer during travel."}},{"id":58,"c":"namaz","t":{"ro":"Nafl namaz ghar mein","hi":"नफ़्ल नमाज़ घर में","en":"Voluntary prayers at home"},"a":"","tl":"Farz ke alawa nafl ghar mein padhna afzal","m":{"ur":"اپنے گھروں میں نماز پڑھو، کیونکہ انسان کی افضل نماز وہ ہے جو وہ اپنے گھر میں پڑھے (سوائے فرض کے)۔","ro":"Apne gharon mein namaz padho, kyunke insan ki afzal namaz woh hai jo woh apne ghar mein padhe (siwaye farz ke).","hi":"अपने घरों में नमाज़ पढ़ो, क्योंकि इंसान की अफ़ज़ल नमाज़ वह है जो वह अपने घर में पढ़े (सिवाए फ़र्ज़ के)।","en":"Pray in your homes, for the best prayer of a person is the one he prays in his home, except the obligatory prayer."},"r":"Sahih al-Bukhari 731; Sahih Muslim 781","n":{"ur":"گھر میں نفل پڑھنے کی فضیلت۔","ro":"Ghar mein nafl padhne ki fazilat.","hi":"घर में नफ़्ल पढ़ने की फ़ज़ीलत।","en":"The virtue of praying voluntary prayers at home."}},{"id":59,"c":"namaz","t":{"ro":"Salat-ul-Istikhara ka tareeqa","hi":"सलातुल-इस्तिख़ारा का तरीक़ा","en":"How to perform Salat al-Istikhara"},"a":"اللَّهُمَّ إِنِّي أَسْتَخِيرُكَ بِعِلْمِكَ، وَأَسْتَقْدِرُكَ بِقُدْرَتِكَ، وَأَسْأَلُكَ مِنْ فَضْلِكَ الْعَظِيمِ، فَإِنَّكَ تَقْدِرُ وَلَا أَقْدِرُ، وَتَعْلَمُ وَلَا أَعْلَمُ، وَأَنْتَ عَلَّامُ الْغُيُوبِ. اللَّهُمَّ إِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الْأَمْرَ (اپنے کام کا نام لیں) خَيْرٌ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي، فَاقْدُرْهُ لِي وَيَسِّرْهُ لِي ثُمَّ بَارِكْ لِي فِيهِ، وَإِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الْأَمْرَ شَرٌّ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي، فَاصْرِفْهُ عَنِّي وَاصْرِفْنِي عَنْهُ، وَاقْدُرْ لِيَ الْخَيْرَ حَيْثُ كَانَ ثُمَّ أَرْضِنِي بِهِ","tl":"Allahumma inni astakhiruka bi 'ilmik, wa astaqdiruka bi qudratik, wa as'aluka min fadlikal-'azim, fa-innaka taqdiru wa la aqdir, wa ta'lamu wa la a'lam, wa anta 'allamul-ghuyub. Allahumma in kunta ta'lamu anna hadhal-amra (apne kaam ka naam lein) khayrul-li fi dini wa ma'ashi wa 'aqibati amri, faqdurhu li wa yassirhu li thumma barik li fih. Wa in kunta ta'lamu anna hadhal-amra sharrul-li fi dini wa ma'ashi wa 'aqibati amri, fasrifhu 'anni wasrifni 'anhu, waqdur liyal-khayra haythu kana thumma ardini bih.","m":{"ur":"اے اللہ! میں تیرے علم کے وسیلے سے تجھ سے بھلائی طلب کرتا ہوں، تیری قدرت کے وسیلے سے تجھ سے طاقت مانگتا ہوں، اور تجھ سے تیرے عظیم فضل کا سوال کرتا ہوں، کیونکہ تو قدرت رکھتا ہے اور میں نہیں رکھتا، تو جانتا ہے اور میں نہیں جانتا، اور تو غیب کی باتوں کو خوب جاننے والا ہے۔ اے اللہ! اگر تیرے علم میں یہ کام (یہاں اپنے کام کا نام لیں) میرے لیے میرے دین، میری زندگی اور میرے انجام کے لیے بہتر ہے (یا فرمایا: میری دنیا اور آخرت کے لیے) تو اسے میرے لیے مقدر کر دے، میرے لیے آسان کر دے، پھر اس میں میرے لیے برکت دے۔ اور اگر تیرے علم میں یہ کام میرے لیے میرے دین، میری زندگی اور میرے انجام کے لیے برا ہے (یا فرمایا: میری دنیا اور آخرت کے لیے) تو اسے مجھ سے پھیر دے اور مجھے اس سے پھیر دے، اور جہاں بھی بھلائی ہو میرے لیے مقدر کر دے، پھر مجھے اس پر راضی کر دے۔","ro":"Ae Allah! Main tere ilm ke wasile se tujh se bhalai talab karta hoon, teri qudrat ke wasile se tujh se taqat mangta hoon, aur tujh se tere azeem fazl ka sawal karta hoon, kyunke tu qudrat rakhta hai aur main nahin rakhta, tu jaanta hai aur main nahin jaanta, aur tu ghaib ki baaton ko khoob jaanne wala hai. Ae Allah! Agar tere ilm mein yeh kaam (yahan apne kaam ka naam len) mere liye mere deen, meri zindagi aur mere anjam ke liye behtar hai (ya farmaya: meri duniya aur aakhirat ke liye) to ise mere liye muqaddar kar de, mere liye aasan kar de, phir is mein mere liye barkat de. Aur agar tere ilm mein yeh kaam mere liye mere deen, meri zindagi aur mere anjam ke liye bura hai (ya farmaya: meri duniya aur aakhirat ke liye) to ise mujh se phair de aur mujhe is se phair de, aur jahan bhi bhalai ho mere liye muqaddar kar de, phir mujhe us par razi kar de.","hi":"ऐ अल्लाह! मैं तेरे इल्म के वसीले से तुझसे भलाई तलब करता हूँ, तेरी क़ुदरत के वसीले से तुझसे ताक़त माँगता हूँ, और तुझसे तेरे अज़ीम फ़ज़्ल का सवाल करता हूँ, क्योंकि तू क़ुदरत रखता है और मैं नहीं रखता, तू जानता है और मैं नहीं जानता, और तू ग़ैब की बातों को ख़ूब जानने वाला है। ऐ अल्लाह! अगर तेरे इल्म में यह काम (यहाँ अपने काम का नाम लें) मेरे लिए मेरे दीन, मेरी ज़िंदगी और मेरे अंजाम के लिए बेहतर है (या फ़रमाया: मेरी दुनिया और आख़िरत के लिए) तो इसे मेरे लिए मुक़द्दर कर दे, मेरे लिए आसान कर दे, फिर इसमें मेरे लिए बरकत दे। और अगर तेरे इल्म में यह काम मेरे लिए मेरे दीन, मेरी ज़िंदगी और मेरे अंजाम के लिए बुरा है (या फ़रमाया: मेरी दुनिया और आख़िरत के लिए) तो इसे मुझसे फेर दे और मुझे इससे फेर दे, और जहाँ भी भलाई हो मेरे लिए मुक़द्दर कर दे, फिर मुझे उस पर राज़ी कर दे।","en":"O Allah, I seek Your guidance through Your knowledge, I seek ability through Your power, and I ask You of Your immense bounty; for You have power and I have none, You know and I do not, and You are the Knower of the unseen. O Allah, if You know that this matter (mention your matter here) is good for me in my religion, my life and the outcome of my affairs (or he said: in my worldly life and the Hereafter), then decree it for me, make it easy for me, and then bless me in it. And if You know that this matter is bad for me in my religion, my life and the outcome of my affairs (or he said: in my worldly life and the Hereafter), then turn it away from me and turn me away from it, and decree for me the good wherever it may be, and then make me pleased with it."},"r":"Sahih al-Bukhari 1162","n":{"ur":"کسی جائز کام کے ارادے پر 2 رکعت نفل پڑھ کر یہ دعا پڑھیں۔","ro":"Kisi jaiz kaam ke irade par 2 rakat nafl padh kar yeh dua padhen.","hi":"किसी जाइज़ काम के इरादे पर 2 रकअत नफ़्ल पढ़कर यह दुआ पढ़ें।","en":"When intending to do a permissible matter, pray 2 rak'ahs of voluntary prayer and then recite this dua."}},{"id":60,"c":"subah","t":{"ro":"Neend se uthne ki dua","hi":"नींद से उठने की दुआ","en":"Dua upon waking from sleep"},"a":"الْحَمْدُ لِلَّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا وَإِلَيْهِ النُّشُورُ","tl":"Alhamdulillahil-ladhi ahyana ba'da ma amatana wa ilayhin-nushur","m":{"ur":"تمام تعریف اللہ کے لیے ہے جس نے ہمیں (نیند کی) موت کے بعد زندہ کیا، اور اسی کی طرف اٹھ کر جانا ہے۔","ro":"Tamam tareef Allah ke liye hai jisne hamein (neend ki) maut ke baad zinda kiya, aur usi ki taraf uth kar jana hai.","hi":"तमाम तारीफ़ अल्लाह के लिए है जिसने हमें (नींद की) मौत के बाद ज़िंदा किया, और उसी की तरफ़ उठ कर जाना है।","en":"All praise is for Allah who gave us life after causing us to die (sleep), and to Him is the resurrection."},"r":"Sahih al-Bukhari 6312","n":{"ur":"نیند کو ایک قسم کی موت کہا گیا ہے۔ صبح جاگنا ایک نئی زندگی ہے۔","ro":"Neend ko ek qism ki maut kaha gaya hai. Subah jaagna ek nayi zindagi hai.","hi":"नींद को एक क़िस्म की मौत कहा गया है। सुबह जागना एक नई ज़िंदगी है।","en":"Sleep has been described as a kind of death. Waking in the morning is a new life."}},{"id":61,"c":"subah","t":{"ro":"Ghar se nikalte waqt","hi":"घर से निकलते वक़्त","en":"When leaving the house"},"a":"بِسْمِ اللَّهِ، تَوَكَّلْتُ عَلَى اللَّهِ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ","tl":"Bismillah, tawakkaltu 'alallah, wa la hawla wa la quwwata illa billah","m":{"ur":"اللہ کے نام کے ساتھ، میں نے اللہ پر بھروسا کیا، اور گناہ سے بچنے کی کوئی طاقت اور نیکی کی کوئی قوت نہیں مگر اللہ کی مدد سے۔","ro":"Allah ke naam ke saath, maine Allah par bharosa kiya, aur gunah se bachne ki koi taaqat aur neki ki koi quwwat nahi magar Allah ki madad se.","hi":"अल्लाह के नाम के साथ, मैंने अल्लाह पर भरोसा किया, और गुनाह से बचने की कोई ताक़त और नेकी की कोई क़ुव्वत नहीं मगर अल्लाह की मदद से।","en":"In the name of Allah, I place my trust in Allah; there is no power to avoid sin and no strength to do good except with Allah's help."},"r":"Sunan Abi Dawud 5095; Tirmidhi 3426 - Sahih","n":{"ur":"گھر سے نکلتے وقت یہ پڑھنے سے ہدایت، کفایت اور حفاظت کا وعدہ ہے۔","ro":"Ghar se nikalte waqt yeh padhne se hidayat, kifayat aur hifazat ka wada hai.","hi":"घर से निकलते वक़्त यह पढ़ने से हिदायत, किफ़ायत और हिफ़ाज़त का वादा है।","en":"Reciting this when leaving the house carries the promise of guidance, sufficiency and protection."}},{"id":62,"c":"subah","t":{"ro":"Teeno Qul (Subah + Sham 3-3 martaba)","hi":"तीनों क़ुल (सुबह + शाम 3-3 मर्तबा)","en":"The Three Quls (3 times each in the morning and evening)"},"a":"قُلْ هُوَ اللَّهُ أَحَدٌ ﴿١﴾ اللَّهُ الصَّمَدُ ﴿٢﴾ لَمْ يَلِدْ وَلَمْ يُولَدْ ﴿٣﴾ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ ﴿٤﴾ قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ ﴿١﴾ مِنْ شَرِّ مَا خَلَقَ ﴿٢﴾ وَمِنْ شَرِّ غَاسِقٍ إِذَا وَقَبَ ﴿٣﴾ وَمِنْ شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ ﴿٤﴾ وَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ ﴿٥﴾ قُلْ أَعُوذُ بِرَبِّ النَّاسِ ﴿١﴾ مَلِكِ النَّاسِ ﴿٢﴾ إِلَٰهِ النَّاسِ ﴿٣﴾ مِنْ شَرِّ الْوَسْوَاسِ الْخَنَّاسِ ﴿٤﴾ الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ ﴿٥﴾ مِنَ الْجِنَّةِ وَالنَّاسِ ﴿٦﴾","tl":"Qul huwallahu ahad. Allahus-Samad. Lam yalid wa lam yulad. Wa lam yakun lahu kufuwan ahad. Qul a'udhu bi Rabbil-falaq. Min sharri ma khalaq. Wa min sharri ghasiqin idha waqab. Wa min sharrin-naffathati fil-'uqad. Wa min sharri hasidin idha hasad. Qul a'udhu bi Rabbin-nas. Malikin-nas. Ilahin-nas. Min sharril-waswasil-khannas. Alladhi yuwaswisu fi sudurin-nas. Minal-jinnati wan-nas.","m":{"ur":"کہہ دیجیے: وہ اللہ ایک ہے۔ اللہ بے نیاز ہے۔ نہ اس نے کسی کو جنا اور نہ وہ جنا گیا۔ اور نہ کوئی اس کے برابر کا ہے۔ کہہ دیجیے: میں صبح کے رب کی پناہ میں آتا ہوں، اس کی مخلوق کے شر سے، اور اندھیری رات کے شر سے جب وہ چھا جائے، اور گرہوں میں پھونکنے والیوں کے شر سے، اور حسد کرنے والے کے شر سے جب وہ حسد کرے۔ کہہ دیجیے: میں لوگوں کے رب کی پناہ میں آتا ہوں، لوگوں کے بادشاہ کی، لوگوں کے معبود کی، وسوسہ ڈالنے والے پیچھے ہٹ جانے والے کے شر سے، جو لوگوں کے سینوں میں وسوسے ڈالتا ہے، جنوں میں سے اور انسانوں میں سے۔","ro":"Kah dijiye: Woh Allah ek hai. Allah be-niyaz hai. Na us ne kisi ko jana aur na woh jana gaya. Aur na koi uske barabar ka hai. Kah dijiye: Main subah ke Rab ki panah mein aata hoon, uski makhlooq ke shar se, aur andheri raat ke shar se jab woh chha jaye, aur girhon mein phoonkne waliyon ke shar se, aur hasad karne wale ke shar se jab woh hasad kare. Kah dijiye: Main logon ke Rab ki panah mein aata hoon, logon ke badshah ki, logon ke mabood ki, waswasa dalne wale peechhe hat jane wale ke shar se, jo logon ke seenon mein waswase dalta hai, jinnon mein se aur insaanon mein se.","hi":"कह दीजिए: वह अल्लाह एक है। अल्लाह बे-नियाज़ है। न उसने किसी को जना और न वह जना गया। और न कोई उसके बराबर का है। कह दीजिए: मैं सुबह के रब की पनाह में आता हूँ, उसकी मख़लूक़ के शर से, और अँधेरी रात के शर से जब वह छा जाए, और गिरहों में फूँकने वालियों के शर से, और हसद करने वाले के शर से जब वह हसद करे। कह दीजिए: मैं लोगों के रब की पनाह में आता हूँ, लोगों के बादशाह की, लोगों के माबूद की, वसवसा डालने वाले पीछे हट जाने वाले के शर से, जो लोगों के सीनों में वसवसे डालता है, जिन्नों में से और इंसानों में से।","en":"Say: He is Allah, the One. Allah is the Self-Sufficient. He neither begot nor was begotten. And there is none comparable to Him. Say: I seek refuge in the Lord of the daybreak, from the evil of what He has created, and from the evil of the darkness when it settles, and from the evil of those who blow on knots, and from the evil of the envier when he envies. Say: I seek refuge in the Lord of mankind, the King of mankind, the God of mankind, from the evil of the retreating whisperer, who whispers in the hearts of mankind, from among the jinn and mankind."},"r":"Sunan Abi Dawud 5082 - Sahih (Albani: Sahih al-Jami' 4406)","n":{"ur":"صبح و شام 3-3 بار پڑھنا ہر چیز سے کافی ہے۔","ro":"Subah o sham 3-3 baar padhna har cheez se kaafi hai.","hi":"सुबह व शाम 3-3 बार पढ़ना हर चीज़ से काफ़ी है।","en":"Reciting them 3 times each in the morning and evening is sufficient against everything."}},{"id":63,"c":"subah","t":{"ro":"Din ki bhalai maangne ki dua (Asbahna...)","hi":"दिन की भलाई माँगने की दुआ (अस्बहना...)","en":"Dua for the good of the day (Asbahna...)"},"a":"أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلَّهِ، وَالْحَمْدُ لِلَّهِ، لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، رَبِّ أَسْأَلُكَ خَيْرَ مَا فِي هَذَا الْيَوْمِ وَخَيْرَ مَا بَعْدَهُ، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِي هَذَا الْيَوْمِ وَشَرِّ مَا بَعْدَهُ، رَبِّ أَعُوذُ بِكَ مِنَ الْكَسَلِ وَسُوءِ الْكِبَرِ، رَبِّ أَعُوذُ بِكَ مِنْ عَذَابٍ فِي النَّارِ وَعَذَابٍ فِي الْقَبْرِ","tl":"Asbahna wa asbahal-mulku lillah, walhamdu lillah, la ilaha illallahu wahdahu la sharika lah, lahul-mulku wa lahul-hamdu wa huwa 'ala kulli shay'in qadir. Rabbi as'aluka khayra ma fi hadhal-yawmi wa khayra ma ba'dah, wa a'udhu bika min sharri ma fi hadhal-yawmi wa sharri ma ba'dah. Rabbi a'udhu bika minal-kasali wa su'il-kibar, Rabbi a'udhu bika min 'adhabin fin-nari wa 'adhabin fil-qabr. (Sham ko 'Amsayna wa amsal-mulku lillah' kahein aur 'is raat ki bhalai aur is raat ke shar' kahein.)","m":{"ur":"ہم نے صبح کی اور بادشاہی اللہ ہی کی ہے، تمام تعریف اللہ کے لیے ہے، اللہ کے سوا کوئی معبود نہیں، وہ اکیلا ہے اس کا کوئی شریک نہیں، اسی کی بادشاہی ہے اور اسی کی حمد ہے اور وہ ہر چیز پر قادر ہے۔ اے میرے رب! میں تجھ سے اس دن کی بھلائی اور اس کے بعد کی بھلائی مانگتا ہوں، اور اس دن کے شر اور اس کے بعد کے شر سے تیری پناہ چاہتا ہوں۔ اے میرے رب! سستی اور بڑھاپے کی برائی سے تیری پناہ چاہتا ہوں۔ اے میرے رب! جہنم کے عذاب اور قبر کے عذاب سے تیری پناہ چاہتا ہوں۔ (شام کو «أَمْسَيْنَا وَأَمْسَى الْمُلْكُ لِلَّهِ» کہے، اور «اس رات کی بھلائی اور اس رات کے شر» کہے۔)","ro":"Hum ne subah ki aur badshahi Allah hi ki hai, tamam taareef Allah ke liye hai, Allah ke siwa koi mabood nahi, woh akela hai uska koi shareek nahi, usi ki badshahi hai aur usi ki hamd hai aur woh har cheez par qaadir hai. Ae mere Rab! Main tujh se is din ki bhalai aur uske baad ki bhalai maangta hoon, aur is din ke shar aur uske baad ke shar se teri panah chahta hoon. Ae mere Rab! Susti aur budhape ki buraai se teri panah chahta hoon. Ae mere Rab! Jahannam ke azaab aur qabr ke azaab se teri panah chahta hoon. (Sham ko «أَمْسَيْنَا وَأَمْسَى الْمُلْكُ لِلَّهِ» kahe, aur «is raat ki bhalai aur is raat ke shar» kahe.)","hi":"हमने सुबह की और बादशाही अल्लाह ही की है, तमाम तारीफ़ अल्लाह के लिए है, अल्लाह के सिवा कोई माबूद नहीं, वह अकेला है उसका कोई शरीक नहीं, उसी की बादशाही है और उसी की हम्द है और वह हर चीज़ पर क़ादिर है। ऐ मेरे रब! मैं तुझसे इस दिन की भलाई और उसके बाद की भलाई माँगता हूँ, और इस दिन के शर और उसके बाद के शर से तेरी पनाह चाहता हूँ। ऐ मेरे रब! सुस्ती और बुढ़ापे की बुराई से तेरी पनाह चाहता हूँ। ऐ मेरे रब! जहन्नम के अज़ाब और क़ब्र के अज़ाब से तेरी पनाह चाहता हूँ। (शाम को «أَمْسَيْنَا وَأَمْسَى الْمُلْكُ لِلَّهِ» कहे, और «इस रात की भलाई और इस रात के शर» कहे।)","en":"We have reached the morning and the dominion belongs to Allah; all praise is for Allah. There is no god but Allah, alone, with no partner; to Him belongs the dominion and to Him belongs all praise, and He has power over everything. My Lord! I ask You for the good of this day and the good of what follows it, and I seek Your refuge from the evil of this day and the evil of what follows it. My Lord! I seek Your refuge from laziness and the evil of old age. My Lord! I seek Your refuge from the punishment of Hellfire and the punishment of the grave. (In the evening say: «أَمْسَيْنَا وَأَمْسَى الْمُلْكُ لِلَّهِ» and say: \"the good of this night and the evil of this night\".)"},"r":"Sahih Muslim 2723","n":{"ur":"شام کو 'أمسينا' (Amsayna) سے شروع کریں اور رات کا ذکر کریں۔","ro":"Sham ko 'أمسينا' (Amsayna) se shuru karein aur raat ka zikr karein.","hi":"शाम को 'أمسينا' (Amsayna) से शुरू करें और रात का ज़िक्र करें।","en":"In the evening, begin with 'Amsayna' and mention the night instead."}},{"id":64,"c":"subah","t":{"ro":"Nuqsan se hifazat ki dua (3 martaba)","hi":"नुक़सान से हिफ़ाज़त की दुआ (3 मर्तबा)","en":"Dua for protection from harm (3 times)"},"a":"بِسْمِ اللَّهِ الَّذِي لَا يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الْأَرْضِ وَلَا فِي السَّمَاءِ وَهُوَ السَّمِيعُ الْعَلِيمُ","tl":"Bismillahil-ladhi la yadurru ma'asmihi shay'un fil-ardi wa la fis-sama'i wa huwas-Sami'ul-'Alim","m":{"ur":"اللہ کے نام کے ساتھ، جس کے نام کی موجودگی میں زمین و آسمان کی کوئی چیز نقصان نہیں پہنچا سکتی، اور وہ خوب سننے والا، خوب جاننے والا ہے۔","ro":"Allah ke naam ke saath, jiske naam ki maujoodgi mein zameen o aasman ki koi cheez nuqsan nahi pahuncha sakti, aur woh khoob sunne wala, khoob jaanne wala hai.","hi":"अल्लाह के नाम के साथ, जिसके नाम की मौजूदगी में ज़मीन व आसमान की कोई चीज़ नुक़सान नहीं पहुँचा सकती, और वह ख़ूब सुनने वाला, ख़ूब जानने वाला है।","en":"In the name of Allah, with whose name nothing on earth or in the heavens can cause harm, and He is the All-Hearing, the All-Knowing."},"r":"Sunan Abi Dawud 5088 - Sahih (Albani: Sahih al-Jami' 5745)","n":{"ur":"صبح و شام 3 بار پڑھنے سے کوئی چیز نقصان نہیں پہنچا سکتی۔","ro":"Subah o sham 3 baar padhne se koi cheez nuqsan nahi pahuncha sakti.","hi":"सुबह व शाम 3 बार पढ़ने से कोई चीज़ नुक़सान नहीं पहुँचा सकती।","en":"Whoever recites it 3 times in the morning and evening will not be harmed by anything."}},{"id":65,"c":"subah","t":{"ro":"Afiyat (sehat, salamati) ki jaame dua","hi":"आफ़ियत (सेहत, सलामती) की जामे दुआ","en":"Comprehensive dua for well-being (afiyah)"},"a":"اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ، اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي دِينِي وَدُنْيَايَ وَأَهْلِي وَمَالِي، اللَّهُمَّ اسْتُرْ عَوْرَاتِي وَآمِنْ رَوْعَاتِي، اللَّهُمَّ احْفَظْنِي مِنْ بَيْنِ يَدَيَّ وَمِنْ خَلْفِي وَعَنْ يَمِينِي وَعَنْ شِمَالِي وَمِنْ فَوْقِي، وَأَعُوذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِي","tl":"Allahumma inni as'alukal-'afiyata fid-dunya wal-akhirah. Allahumma inni as'alukal-'afwa wal-'afiyata fi dini wa dunyaya wa ahli wa mali. Allahummastur 'awrati wa amin raw'ati. Allahummahfazni min bayni yadayya wa min khalfi wa 'an yamini wa 'an shimali wa min fawqi, wa a'udhu bi 'azamatika an ughtala min tahti.","m":{"ur":"اے اللہ! میں تجھ سے دنیا و آخرت میں عافیت مانگتا ہوں۔ اے اللہ! میں تجھ سے اپنے دین، دنیا، اہل و عیال اور مال میں معافی اور عافیت مانگتا ہوں۔ اے اللہ! میرے عیبوں پر پردہ ڈال دے اور میری گھبراہٹوں کو امن میں بدل دے۔ اے اللہ! میری حفاظت فرما میرے آگے سے، پیچھے سے، دائیں سے، بائیں سے اور اوپر سے، اور میں تیری عظمت کی پناہ مانگتا ہوں کہ اچانک اپنے نیچے سے ہلاک کیا جاؤں۔","ro":"Ae Allah! Main tujh se duniya o aakhirat mein afiyat maangta hoon. Ae Allah! Main tujh se apne deen, duniya, ahl o ayaal aur maal mein maafi aur afiyat maangta hoon. Ae Allah! Mere aibon par parda daal de aur meri ghabrahaton ko aman mein badal de. Ae Allah! Meri hifazat farma mere aage se, peechhe se, daayen se, baayen se aur upar se, aur main teri azmat ki panah maangta hoon ke achanak apne neeche se halaak kiya jaoon.","hi":"ऐ अल्लाह! मैं तुझसे दुनिया व आख़िरत में आफ़ियत माँगता हूँ। ऐ अल्लाह! मैं तुझसे अपने दीन, दुनिया, अहल व अयाल और माल में माफ़ी और आफ़ियत माँगता हूँ। ऐ अल्लाह! मेरे ऐबों पर पर्दा डाल दे और मेरी घबराहटों को अमन में बदल दे। ऐ अल्लाह! मेरी हिफ़ाज़त फ़रमा मेरे आगे से, पीछे से, दाएँ से, बाएँ से और ऊपर से, और मैं तेरी अज़मत की पनाह माँगता हूँ कि अचानक अपने नीचे से हलाक किया जाऊँ।","en":"O Allah! I ask You for well-being in this world and the Hereafter. O Allah! I ask You for pardon and well-being in my religion, my worldly affairs, my family and my wealth. O Allah! Conceal my faults and turn my fears into security. O Allah! Protect me from in front of me, from behind me, from my right, from my left and from above me, and I seek refuge in Your greatness from being struck down unexpectedly from beneath me."},"r":"Sunan Abi Dawud 5074 - Sahih","n":{"ur":"عافیت کا مطلب ہر طرح کی سلامتی ہے: جسم، دین، مال اور گھر والوں کی۔","ro":"Afiyat ka matlab har tarah ki salamati hai: jism, deen, maal aur ghar walon ki.","hi":"आफ़ियत का मतलब हर तरह की सलामती है: जिस्म, दीन, माल और घर वालों की।","en":"Afiyah means safety and well-being of every kind: of the body, the religion, wealth and family."}},{"id":66,"c":"subah","t":{"ro":"Mamlaat sanwarne ki dua (Fatima RA ki wasiyat)","hi":"मामलात सँवारने की दुआ (फ़ातिमा रज़ि. की वसीयत)","en":"Dua for setting one's affairs right (counsel to Fatima RA)"},"a":"يَا حَيُّ يَا قَيُّومُ بِرَحْمَتِكَ أَسْتَغِيثُ، أَصْلِحْ لِي شَأْنِي كُلَّهُ، وَلَا تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ","tl":"Ya Hayyu ya Qayyumu bi rahmatika astaghith, aslih li sha'ni kullahu, wa la takilni ila nafsi tarfata 'ayn","m":{"ur":"اے زندہ! اے سب کو تھامنے والے! میں تیری رحمت کے وسیلے سے فریاد کرتا ہوں، میرے سارے معاملات سنوار دے، اور مجھے پلک جھپکنے کے برابر بھی میرے نفس کے سپرد نہ کر۔","ro":"Ae Zinda! Ae sab ko thaamne wale! Main teri rahmat ke waseele se faryad karta hoon, mere saare mamlaat sanwar de, aur mujhe palak jhapakne ke barabar bhi mere nafs ke supurd na kar.","hi":"ऐ ज़िंदा! ऐ सब को थामने वाले! मैं तेरी रहमत के वसीले से फ़रियाद करता हूँ, मेरे सारे मामलात सँवार दे, और मुझे पलक झपकने के बराबर भी मेरे नफ़्स के सुपुर्द न कर।","en":"O Ever-Living, O Sustainer of all! I seek relief through Your mercy; set right all my affairs, and do not leave me to myself even for the blink of an eye."},"r":"an-Nasa'i fi 'Amalil-Yawm 570 - Hasan (Albani: Sahih al-Jami' 5820)","n":{"ur":"نبی ﷺ نے فاطمہ رضی اللہ عنہا کو یہ صبح و شام پڑھنے کی وصیت کی۔","ro":"Nabi ﷺ ne Fatima RA ko yeh subah o sham padhne ki wasiyat ki.","hi":"नबी ﷺ ने फ़ातिमा रज़ि. को यह सुबह व शाम पढ़ने की वसीयत की।","en":"The Prophet ﷺ advised Fatima RA to recite this every morning and evening."}},{"id":67,"c":"subah","t":{"ro":"Nafs aur shaitan ke shar se panah (Abu Bakr RA ko sikhayi)","hi":"नफ़्स और शैतान के शर से पनाह (अबू बक्र रज़ि. को सिखाई)","en":"Refuge from the evil of the self and Satan (taught to Abu Bakr RA)"},"a":"اللَّهُمَّ عَالِمَ الْغَيْبِ وَالشَّهَادَةِ، فَاطِرَ السَّمَاوَاتِ وَالْأَرْضِ، رَبَّ كُلِّ شَيْءٍ وَمَلِيكَهُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي، وَمِنْ شَرِّ الشَّيْطَانِ وَشِرْكِهِ، وَأَنْ أَقْتَرِفَ عَلَى نَفْسِي سُوءًا أَوْ أَجُرَّهُ إِلَى مُسْلِمٍ","tl":"Allahumma 'alimal-ghaybi wash-shahadah, fatiras-samawati wal-ard, Rabba kulli shay'in wa malikah, ashhadu an la ilaha illa ant, a'udhu bika min sharri nafsi, wa min sharrish-shaytani wa shirkih, wa an aqtarifa 'ala nafsi su'an aw ajurrahu ila muslim.","m":{"ur":"اے اللہ! غیب اور حاضر کے جاننے والے، آسمانوں اور زمین کے پیدا کرنے والے، ہر چیز کے رب اور اس کے مالک! میں گواہی دیتا ہوں کہ تیرے سوا کوئی معبود نہیں۔ میں اپنے نفس کے شر سے، شیطان کے شر اور اس کے شرک سے، اور اس بات سے تیری پناہ مانگتا ہوں کہ میں اپنے آپ پر کوئی برائی کروں یا اسے کسی مسلمان کی طرف کھینچ لاؤں۔","ro":"Ae Allah! Ghaib aur haazir ke jaanne wale, aasmanon aur zameen ke paida karne wale, har cheez ke Rab aur uske malik! Main gawahi deta hoon ke tere siwa koi mabood nahi. Main apne nafs ke shar se, shaitan ke shar aur uske shirk se, aur is baat se teri panah maangta hoon ke main apne aap par koi buraai karoon ya use kisi musalman ki taraf kheench laoon.","hi":"ऐ अल्लाह! ग़ैब और हाज़िर के जानने वाले, आसमानों और ज़मीन के पैदा करने वाले, हर चीज़ के रब और उसके मालिक! मैं गवाही देता हूँ कि तेरे सिवा कोई माबूद नहीं। मैं अपने नफ़्स के शर से, शैतान के शर और उसके शिर्क से, और इस बात से तेरी पनाह माँगता हूँ कि मैं अपने आप पर कोई बुराई करूँ या उसे किसी मुसलमान की तरफ़ खींच लाऊँ।","en":"O Allah, Knower of the unseen and the seen, Creator of the heavens and the earth, Lord and Master of everything! I bear witness that there is no god but You. I seek refuge in You from the evil of my own self, from the evil of Satan and his shirk, and from committing any wrong against myself or bringing it upon any Muslim."},"r":"Sunan Abi Dawud 5067 - Sahih","n":{"ur":"صبح، شام اور سونے سے پہلے پڑھیں۔","ro":"Subah, sham aur sone se pehle padhein.","hi":"सुबह, शाम और सोने से पहले पढ़ें।","en":"Recite it in the morning, in the evening and before sleeping."}},{"id":68,"c":"subah","t":{"ro":"Iman ki tajdeed ka kalimah","hi":"ईमान की तजदीद का कलिमा","en":"Words renewing one's faith"},"a":"رَضِيتُ بِاللَّهِ رَبَّا، وَبِالْإِسْلَامِ دِينًا، وَبِمُحَمَّدٍ نَبِيًّا","tl":"Raditu billahi rabban, wa bil-Islami dinan, wa bi Muhammadin nabiyyan","m":{"ur":"میں اللہ کے رب ہونے، اسلام کے دین ہونے اور محمد ﷺ کے نبی ہونے پر راضی ہوں۔","ro":"Main Allah ke Rab hone, Islam ke deen hone aur Muhammad ﷺ ke Nabi hone par raazi hoon.","hi":"मैं अल्लाह के रब होने, इस्लाम के दीन होने और मुहम्मद ﷺ के नबी होने पर राज़ी हूँ।","en":"I am pleased with Allah as my Lord, with Islam as my religion, and with Muhammad ﷺ as my Prophet."},"r":"Sahih Muslim 1884","n":{"ur":"جو اسے دل سے مانے، اس کے لیے جنت واجب ہو جاتی ہے۔","ro":"Jo ise dil se maane, uske liye jannat wajib ho jaati hai.","hi":"जो इसे दिल से माने, उसके लिए जन्नत वाजिब हो जाती है।","en":"Whoever affirms this sincerely from the heart, Paradise becomes obligatory for him."}},{"id":69,"c":"subah","t":{"ro":"Subhanallah wa bihamdihi (100 martaba)","hi":"सुब्हानल्लाहि व बिहम्दिही (100 मर्तबा)","en":"Subhanallahi wa bihamdihi (100 times)"},"a":"سُبْحَانَ اللَّهِ وَبِحَمْدِهِ","tl":"Subhanallah wa bihamdihi","m":{"ur":"اللہ پاک ہے اور میں اس کی حمد کے ساتھ اس کی تسبیح بیان کرتا ہوں۔","ro":"Allah paak hai aur main uski hamd ke saath uski tasbeeh bayan karta hoon.","hi":"अल्लाह पाक है और मैं उसकी हम्द के साथ उसकी तस्बीह बयान करता हूँ।","en":"Glory be to Allah, and I declare His glory with His praise."},"r":"Sahih Muslim 2692; Sahih al-Bukhari 6405","n":{"ur":"صبح و شام 100 بار پڑھنے سے گناہ معاف ہوتے ہیں۔","ro":"Subah o sham 100 baar padhne se gunah maaf hote hain.","hi":"सुबह व शाम 100 बार पढ़ने से गुनाह माफ़ होते हैं।","en":"Reciting it 100 times in the morning and evening results in the forgiveness of sins."}},{"id":70,"c":"subah","t":{"ro":"La ilaha illallah (100 martaba)","hi":"ला इलाहा इल्लल्लाह (100 मर्तबा)","en":"La ilaha illallah (100 times)"},"a":"لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ","tl":"La ilaha illallahu wahdahu la sharika lah, lahul-mulku wa lahul-hamdu wa huwa 'ala kulli shay'in qadir","m":{"ur":"اللہ کے سوا کوئی معبود نہیں، وہ اکیلا ہے، اس کا کوئی شریک نہیں، اسی کی بادشاہی ہے اور اسی کی حمد ہے اور وہ ہر چیز پر قادر ہے۔","ro":"Allah ke siwa koi mabood nahi, woh akela hai, uska koi shareek nahi, usi ki badshahi hai aur usi ki hamd hai aur woh har cheez par qaadir hai.","hi":"अल्लाह के सिवा कोई माबूद नहीं, वह अकेला है, उसका कोई शरीक नहीं, उसी की बादशाही है और उसी की हम्द है और वह हर चीज़ पर क़ादिर है।","en":"There is no god but Allah, alone, without any partner; to Him belongs the dominion and to Him belongs all praise, and He has power over everything."},"r":"Sahih al-Bukhari 3293; Sahih Muslim 2691","n":{"ur":"دن میں 100 بار پڑھنے سے 10 غلام آزاد کرنے کا ثواب، 100 نیکیاں، 100 گناہ معاف اور شام تک شیطان سے حفاظت۔","ro":"Din mein 100 baar padhne se 10 ghulam azaad karne ka sawab, 100 nekiyan, 100 gunah maaf aur sham tak shaitan se hifazat milti hai.","hi":"दिन में 100 बार पढ़ने से 10 ग़ुलाम आज़ाद करने का सवाब, 100 नेकियाँ, 100 गुनाह माफ़ और शाम तक शैतान से हिफ़ाज़त मिलती है।","en":"Reciting it 100 times in a day earns the reward of freeing 10 slaves, 100 good deeds, the forgiveness of 100 sins, and protection from Satan until the evening."}},{"id":71,"c":"subah","t":{"ro":"Darood Shareef","hi":"दरूद शरीफ़","en":"Durood Shareef (Salawat upon the Prophet)"},"a":"اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ. اللَّهُمَّ بَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا بَارَكْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ","tl":"Allahumma salli 'ala Muhammadin wa 'ala ali Muhammad, kama sallayta 'ala Ibrahima wa 'ala ali Ibrahim, innaka Hamidun Majid. Allahumma barik 'ala Muhammadin wa 'ala ali Muhammad, kama barakta 'ala Ibrahima wa 'ala ali Ibrahim, innaka Hamidun Majid.","m":{"ur":"اے اللہ! محمد ﷺ اور آلِ محمد پر رحمت نازل فرما جیسے تو نے ابراہیم اور آلِ ابراہیم پر رحمت نازل فرمائی، بے شک تو تعریف کے لائق، بزرگی والا ہے۔ اے اللہ! محمد ﷺ اور آلِ محمد پر برکت نازل فرما جیسے تو نے ابراہیم اور آلِ ابراہیم پر برکت نازل فرمائی، بے شک تو تعریف کے لائق، بزرگی والا ہے۔","ro":"Ae Allah! Muhammad ﷺ aur aal-e-Muhammad par rahmat naazil farma jaise tu ne Ibrahim aur aal-e-Ibrahim par rahmat naazil farmai, beshak tu taareef ke laaiq, buzurgi wala hai. Ae Allah! Muhammad ﷺ aur aal-e-Muhammad par barkat naazil farma jaise tu ne Ibrahim aur aal-e-Ibrahim par barkat naazil farmai, beshak tu taareef ke laaiq, buzurgi wala hai.","hi":"ऐ अल्लाह! मुहम्मद ﷺ और आल-ए-मुहम्मद पर रहमत नाज़िल फ़रमा जैसे तूने इब्राहीम और आल-ए-इब्राहीम पर रहमत नाज़िल फ़रमाई, बेशक तू तारीफ़ के लाइक़, बुज़ुर्गी वाला है। ऐ अल्लाह! मुहम्मद ﷺ और आल-ए-मुहम्मद पर बरकत नाज़िल फ़रमा जैसे तूने इब्राहीम और आल-ए-इब्राहीम पर बरकत नाज़िल फ़रमाई, बेशक तू तारीफ़ के लाइक़, बुज़ुर्गी वाला है।","en":"O Allah! Send blessings upon Muhammad ﷺ and the family of Muhammad, as You sent blessings upon Ibrahim and the family of Ibrahim; truly You are Praiseworthy and Glorious. O Allah! Bestow Your favour upon Muhammad ﷺ and the family of Muhammad, as You bestowed Your favour upon Ibrahim and the family of Ibrahim; truly You are Praiseworthy and Glorious."},"r":"Sahih al-Bukhari 3370; Sahih Muslim 408","n":{"ur":"جو مجھ پر ایک بار درود بھیجے، اللہ اس پر 10 رحمتیں نازل کرتا ہے۔","ro":"Jo mujh par ek baar durood bheje, Allah us par 10 rahmatein naazil karta hai.","hi":"जो मुझ पर एक बार दरूद भेजे, अल्लाह उस पर 10 रहमतें नाज़िल करता है।","en":"Whoever sends blessings upon me once, Allah sends ten blessings upon him."}},{"id":72,"c":"subah","t":{"ro":"Sayyidul Istighfar","hi":"सय्यिदुल इस्तिग़फ़ार","en":"Sayyid al-Istighfar (the Master of Seeking Forgiveness)"},"a":"اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ، وَأَبُوءُ بِذَنْبِي فَاغْفِرْ لِي، فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ","tl":"Allahumma anta Rabbi la ilaha illa ant, khalaqtani wa ana 'abduk, wa ana 'ala 'ahdika wa wa'dika mastata'tu, a'udhu bika min sharri ma sana'tu, abu'u laka bini'matika 'alayya, wa abu'u bidhanbi faghfir li, fa-innahu la yaghfirudh-dhunuba illa ant.","m":{"ur":"اے اللہ! تو میرا رب ہے، تیرے سوا کوئی معبود نہیں۔ تو نے مجھے پیدا کیا اور میں تیرا بندہ ہوں، اور اپنی استطاعت کے مطابق تیرے عہد اور وعدے پر قائم ہوں۔ میں نے جو کچھ کیا اس کے شر سے تیری پناہ مانگتا ہوں۔ مجھ پر تیری جو نعمت ہے اس کا اقرار کرتا ہوں اور اپنے گناہ کا اعتراف کرتا ہوں، پس مجھے بخش دے، کیونکہ تیرے سوا کوئی گناہ نہیں بخشتا۔","ro":"Ae Allah! Tu mera Rab hai, tere siwa koi mabood nahi. Tu ne mujhe paida kiya aur main tera banda hoon, aur apni istitaat ke mutabiq tere ahd aur wade par qaayam hoon. Maine jo kuch kiya uske shar se teri panah maangta hoon. Mujh par teri jo naimat hai uska iqrar karta hoon aur apne gunah ka aitraf karta hoon, pas mujhe bakhsh de, kyunke tere siwa koi gunah nahi bakhshta.","hi":"ऐ अल्लाह! तू मेरा रब है, तेरे सिवा कोई माबूद नहीं। तूने मुझे पैदा किया और मैं तेरा बंदा हूँ, और अपनी इस्तिताअत के मुताबिक़ तेरे अहद और वादे पर क़ायम हूँ। मैंने जो कुछ किया उसके शर से तेरी पनाह माँगता हूँ। मुझ पर तेरी जो नेअमत है उसका इक़रार करता हूँ और अपने गुनाह का ऐतराफ़ करता हूँ, पस मुझे बख़्श दे, क्योंकि तेरे सिवा कोई गुनाह नहीं बख़्शता।","en":"O Allah! You are my Lord; there is no god but You. You created me and I am Your servant, and I keep Your covenant and promise as best I can. I seek refuge in You from the evil of what I have done. I acknowledge Your favour upon me and I acknowledge my sin, so forgive me, for none forgives sins except You."},"r":"Sahih al-Bukhari 6306","n":{"ur":"جو یقین کے ساتھ صبح یا شام پڑھے اور اسی دن مر جائے، وہ جنت میں جائے گا۔","ro":"Jo yaqeen ke saath subah ya sham padhe aur usi din mar jaye, woh jannat mein jayega.","hi":"जो यक़ीन के साथ सुबह या शाम पढ़े और उसी दिन मर जाए, वह जन्नत में जाएगा।","en":"Whoever recites it in the morning or evening with firm conviction and dies that same day will enter Paradise."}},{"id":73,"c":"subah","t":{"ro":"Rasulullah ﷺ ka roz ka istighfar (100 martaba)","hi":"रसूलुल्लाह ﷺ का रोज़ का इस्तिग़फ़ार (100 मर्तबा)","en":"The daily istighfar of the Messenger of Allah ﷺ (100 times)"},"a":"أَسْتَغْفِرُ اللَّهَ وَأَتُوبُ إِلَيْهِ","tl":"Astaghfirullaha wa atubu ilayh","m":{"ur":"میں اللہ سے معافی مانگتا ہوں اور اسی کی طرف توبہ کرتا ہوں۔","ro":"Main Allah se maafi maangta hoon aur usi ki taraf tauba karta hoon.","hi":"मैं अल्लाह से माफ़ी माँगता हूँ और उसी की तरफ़ तौबा करता हूँ।","en":"I seek forgiveness from Allah and I turn to Him in repentance."},"r":"Sahih Muslim 2702; Sahih al-Bukhari 6307","n":{"ur":"نبی ﷺ روز 100 بار استغفار کرتے تھے۔","ro":"Nabi ﷺ roz 100 baar istighfar karte the.","hi":"नबी ﷺ रोज़ 100 बार इस्तिग़फ़ार करते थे।","en":"The Prophet ﷺ used to seek forgiveness 100 times every day."}},{"id":74,"c":"subah","t":{"ro":"Gunahon ki muafi ka mukammal istighfar","hi":"गुनाहों की माफ़ी का मुकम्मल इस्तिग़फ़ार","en":"The complete istighfar for forgiveness of sins"},"a":"أَسْتَغْفِرُ اللَّهَ الْعَظِيمَ الَّذِي لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ وَأَتُوبُ إِلَيْهِ","tl":"Astaghfirullahal-'Azim alladhi la ilaha illa huwal-Hayyul-Qayyumu wa atubu ilayh","m":{"ur":"میں اللہ عظمت والے سے بخشش مانگتا ہوں جس کے سوا کوئی معبود نہیں، جو زندہ اور سب کو تھامنے والا ہے، اور میں اسی کی طرف توبہ کرتا ہوں۔","ro":"Main Allah azmat wale se bakhshish maangta hoon jiske siwa koi mabood nahi, jo zinda aur sab ko thaamne wala hai, aur main usi ki taraf tauba karta hoon.","hi":"मैं अल्लाह अज़मत वाले से बख़्शिश माँगता हूँ जिसके सिवा कोई माबूद नहीं, जो ज़िंदा और सब को थामने वाला है, और मैं उसी की तरफ़ तौबा करता हूँ।","en":"I seek forgiveness from Allah, the Almighty, besides whom there is no god, the Ever-Living, the Sustainer of all, and I turn to Him in repentance."},"r":"Sunan Abi Dawud 1517 - Sahih","n":{"ur":"جو یہ کہے، اللہ اسے بخش دیتا ہے، چاہے وہ جنگ سے بھاگا ہو۔","ro":"Jo yeh kahe, Allah use bakhsh deta hai, chahe woh jang se bhaaga ho.","hi":"जो यह कहे, अल्लाह उसे बख़्श देता है, चाहे वह जंग से भागा हो।","en":"Whoever says this, Allah forgives him, even if he had fled from the battlefield."}},{"id":75,"c":"subah","t":{"ro":"Rabbi ghfir li wa tub 'alayya","hi":"रब्बिग़फ़िर ली व तुब अलैय्या","en":"Rabbi ghfir li wa tub 'alayya"},"a":"رَبِّ اغْفِرْ لِي وَتُبْ عَلَيَّ، إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيمُ","tl":"Rabbighfir li wa tub 'alayya, innaka antat-Tawwabur-Rahim","m":{"ur":"اے میرے رب! مجھے بخش دے اور میری توبہ قبول فرما، بے شک تو ہی بہت توبہ قبول کرنے والا، نہایت رحم کرنے والا ہے۔","ro":"Ae mere Rab! Mujhe bakhsh de aur meri tauba qubool farma, beshak tu hi bahut tauba qubool karne wala, nihayat rahm karne wala hai.","hi":"ऐ मेरे रब! मुझे बख़्श दे और मेरी तौबा क़ुबूल फ़रमा, बेशक तू ही बहुत तौबा क़ुबूल करने वाला, निहायत रहम करने वाला है।","en":"My Lord! Forgive me and accept my repentance; truly You are the Ever-Accepting of repentance, the Most Merciful."},"r":"Sunan Abi Dawud 1516 - Sahih","n":{"ur":"نبی ﷺ ایک ہی مجلس میں 100 بار یہ پڑھتے تھے۔","ro":"Nabi ﷺ ek hi majlis mein 100 baar yeh padhte the.","hi":"नबी ﷺ एक ही मजलिस में 100 बार यह पढ़ते थे।","en":"The Prophet ﷺ used to recite this 100 times in a single sitting."}},{"id":76,"c":"subah","t":{"ro":"Saare gunahon ki muafi ki dua","hi":"सारे गुनाहों की माफ़ी की दुआ","en":"Dua for forgiveness of all sins"},"a":"اللَّهُمَّ اغْفِرْ لِي ذَنْبِي كُلَّهُ، دِقَّهُ وَجِلَّهُ، وَأَوَّلَهُ وَآخِرَهُ، وَعَلَانِيَتَهُ وَسِرَّهُ","tl":"Allahummaghfir li dhanbi kullahu, diqqahu wa jillahu, wa awwalahu wa akhirahu, wa 'alaniyatahu wa sirrah.","m":{"ur":"اے اللہ! میرے سارے گناہ بخش دے، چھوٹے بھی اور بڑے بھی، پہلے بھی اور بعد کے بھی، کھلے بھی اور چھپے بھی۔","ro":"Ae Allah! Mere saare gunah bakhsh de, chhote bhi aur bade bhi, pehle bhi aur baad ke bhi, khule bhi aur chhupe bhi.","hi":"ऐ अल्लाह! मेरे सारे गुनाह बख़्श दे, छोटे भी और बड़े भी, पहले भी और बाद के भी, खुले भी और छुपे भी।","en":"O Allah! Forgive all my sins, the small and the great, the first and the last, the open and the hidden."},"r":"Sahih Muslim 483","n":{"ur":"سجدے میں یا ہر وقت پڑھ سکتے ہیں۔","ro":"Sajde mein ya har waqt padh sakte hain.","hi":"सजदे में या हर वक़्त पढ़ सकते हैं।","en":"It can be recited in prostration or at any time."}},{"id":77,"c":"subah","t":{"ro":"Adam AS ki tauba ki dua","hi":"आदम अलैहिस्सलाम की तौबा की दुआ","en":"The dua of repentance of Adam AS"},"a":"رَبَّنَا ظَلَمْنَا أَنفُسَنَا وَإِن لَّمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُونَنَّ مِنَ الْخَاسِرِينَ","tl":"Rabbana zalamna anfusana wa in lam taghfir lana wa tarhamna lanakunanna minal-khasirin","m":{"ur":"اے ہمارے رب! ہم نے اپنی جانوں پر ظلم کیا، اور اگر تو نے ہمیں نہ بخشا اور ہم پر رحم نہ کیا تو ہم ضرور نقصان اٹھانے والوں میں سے ہو جائیں گے۔","ro":"Ae hamare Rab! Hum ne apni jaanon par zulm kiya, aur agar tu ne hamein na bakhsha aur hum par rahm na kiya to hum zaroor nuqsan uthane walon mein se ho jayenge.","hi":"ऐ हमारे रब! हमने अपनी जानों पर ज़ुल्म किया, और अगर तूने हमें न बख़्शा और हम पर रहम न किया तो हम ज़रूर नुक़सान उठाने वालों में से हो जाएँगे।","en":"Our Lord! We have wronged ourselves, and if You do not forgive us and have mercy on us, we will surely be among the losers."},"r":"Surah Al-A'raf 7:23","n":{"ur":"یہ حضرت آدم و حوا علیہما السلام کی توبہ کی دعا ہے۔","ro":"Yeh Hazrat Adam aur Hawwa (AS) ki tauba ki dua hai.","hi":"यह हज़रत आदम और हव्वा अलैहिस्सलाम की तौबा की दुआ है।","en":"This is the dua of repentance of Adam and Eve (peace be upon them)."}},{"id":78,"c":"subah","t":{"ro":"Maafi (Afw) ki dua","hi":"माफ़ी (अफ़्व) की दुआ","en":"Dua for pardon (afw)"},"a":"اللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنِّي","tl":"Allahumma innaka 'afuwwun tuhibbul-'afwa fa'fu 'anni","m":{"ur":"اے اللہ! بے شک تو بہت معاف کرنے والا ہے، معافی کو پسند کرتا ہے، پس مجھے معاف فرما دے۔","ro":"Ae Allah! Beshak tu bahut maaf karne wala hai, maafi ko pasand karta hai, pas mujhe maaf farma de.","hi":"ऐ अल्लाह! बेशक तू बहुत माफ़ करने वाला है, माफ़ी को पसंद करता है, पस मुझे माफ़ फ़रमा दे।","en":"O Allah! You are indeed Most Pardoning, You love to pardon, so pardon me."},"r":"Sunan at-Tirmidhi 3513 - Sahih (Albani: as-Sahiha 3337)","n":{"ur":"خاص طور پر رمضان کی آخری راتوں میں پڑھیں۔","ro":"Khaas taur par Ramzan ki aakhri raaton mein padhein.","hi":"ख़ास तौर पर रमज़ान की आख़िरी रातों में पढ़ें।","en":"Recite it especially on the last nights of Ramadan."}},{"id":79,"c":"mushkil","t":{"ro":"Pareshani aur Takleef ki dua (Dua-ul-Karb)","hi":"परेशानी और तकलीफ़ की दुआ (दुआ-ए-कर्ब)","en":"Dua for distress and hardship (Dua al-Karb)"},"a":"لَا إِلَهَ إِلَّا اللَّهُ الْعَظِيمُ الْحَلِيمُ، لَا إِلَهَ إِلَّا اللَّهُ رَبُّ الْعَرْشِ الْعَظِيمِ، لَا إِلَهَ إِلَّا اللَّهُ رَبُّ السَّمَاوَاتِ وَرَبُّ الْأَرْضِ وَرَبُّ الْعَرْشِ الْكَرِيمِ","tl":"La ilaha illallahul-'Azimul-Halim, la ilaha illallahu Rabbul-'Arshil-'Azim, la ilaha illallahu Rabbus-samawati wa Rabbul-ardi wa Rabbul-'Arshil-Karim.","m":{"ur":"اللہ کے سوا کوئی معبود نہیں جو عظمت والا، بردبار ہے۔ اللہ کے سوا کوئی معبود نہیں جو عرشِ عظیم کا رب ہے۔ اللہ کے سوا کوئی معبود نہیں جو آسمانوں کا رب، زمین کا رب اور عزت والے عرش کا رب ہے۔","ro":"Allah ke siwa koi mabood nahi jo azmat wala, bardbaar hai. Allah ke siwa koi mabood nahi jo arsh-e-azeem ka Rab hai. Allah ke siwa koi mabood nahi jo aasmanon ka Rab, zameen ka Rab aur izzat wale arsh ka Rab hai.","hi":"अल्लाह के सिवा कोई माबूद नहीं जो अज़मत वाला, बुर्दबार है। अल्लाह के सिवा कोई माबूद नहीं जो अर्श-ए-अज़ीम का रब है। अल्लाह के सिवा कोई माबूद नहीं जो आसमानों का रब, ज़मीन का रब और इज़्ज़त वाले अर्श का रब है।","en":"There is no god but Allah, the Almighty, the Forbearing. There is no god but Allah, Lord of the Mighty Throne. There is no god but Allah, Lord of the heavens, Lord of the earth and Lord of the Noble Throne."},"r":"Sahih al-Bukhari 6345; Sahih Muslim 2730","n":{"ur":"پریشانی کے وقت یہ پڑھنے سے دل کو سکون ملتا ہے۔","ro":"Pareshani ke waqt yeh padhne se dil ko sukoon milta hai.","hi":"परेशानी के वक़्त यह पढ़ने से दिल को सुकून मिलता है।","en":"Reciting this in times of distress brings peace to the heart."}},{"id":80,"c":"mushkil","t":{"ro":"Bechaini mein: Allahumma rahmataka arju","hi":"बेचैनी में: अल्लाहुम्म रहमतका अरजू","en":"In restlessness: Allahumma rahmataka arju"},"a":"اللَّهُمَّ رَحْمَتَكَ أَرْجُو، فَلَا تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ، وَأَصْلِحْ لِي شَأْنِي كُلَّهُ، لَا إِلَهَ إِلَّا أَنْتَ","tl":"Allahumma rahmataka arju, fala takilni ila nafsi tarfata 'aynin, wa aslih li sha'ni kullahu, la ilaha illa ant","m":{"ur":"اے اللہ! میں تیری رحمت کا امیدوار ہوں، پس مجھے پلک جھپکنے کے برابر بھی میرے نفس کے سپرد نہ کر، اور میرے سارے معاملات درست کر دے، تیرے سوا کوئی معبود نہیں۔","ro":"Ae Allah! Main teri rahmat ka ummeedwaar hoon, pas mujhe palak jhapakne ke barabar bhi mere nafs ke supurd na kar, aur mere saare mamlaat durust kar de, tere siwa koi mabood nahi.","hi":"ऐ अल्लाह! मैं तेरी रहमत का उम्मीदवार हूँ, पस मुझे पलक झपकने के बराबर भी मेरे नफ़्स के सुपुर्द न कर, और मेरे सारे मामलात दुरुस्त कर दे, तेरे सिवा कोई माबूद नहीं।","en":"O Allah! It is Your mercy that I hope for, so do not leave me to myself even for the blink of an eye, and set right all my affairs; there is no god but You."},"r":"Sunan Abi Dawud 5090 - Hasan (Albani: Sahih al-Jami' 3388)","n":{"ur":"جب انسان خود کو بے بس محسوس کرے تو یہ دعا دل کو مضبوطی دیتی ہے۔","ro":"Jab insaan khud ko be-bas mehsoos kare to yeh dua dil ko mazbooti deti hai.","hi":"जब इंसान ख़ुद को बे-बस महसूस करे तो यह दुआ दिल को मज़बूती देती है।","en":"When a person feels helpless, this dua gives strength to the heart."}},{"id":81,"c":"mushkil","t":{"ro":"Yunus AS ki dua","hi":"यूनुस अलैहिस्सलाम की दुआ","en":"The dua of Yunus AS"},"a":"لَا إِلَهَ إِلَّا أَنْتَ سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظَّالِمِينَ","tl":"La ilaha illa anta subhanaka inni kuntu minaz-zalimin","m":{"ur":"تیرے سوا کوئی معبود نہیں، تو پاک ہے، بے شک میں ظالموں میں سے ہوں۔","ro":"Tere siwa koi mabood nahi, tu paak hai, beshak main zalimon mein se hoon.","hi":"तेरे सिवा कोई माबूद नहीं, तू पाक है, बेशक मैं ज़ालिमों में से हूँ।","en":"There is no god but You; glory be to You! Indeed, I was among the wrongdoers."},"r":"Sunan at-Tirmidhi 3505 - Sahih; Surah Al-Anbiya 21:87","n":{"ur":"ہر مشکل اور حاجت کے لیے پڑھی جا سکتی ہے۔","ro":"Har mushkil aur haajat ke liye padhi ja sakti hai.","hi":"हर मुश्किल और हाजत के लिए पढ़ी जा सकती है।","en":"It can be recited for every difficulty and need."}},{"id":82,"c":"mushkil","t":{"ro":"Gham, Fikr aur Qarz se panah","hi":"ग़म, फ़िक्र और क़र्ज़ से पनाह","en":"Refuge from grief, worry and debt"},"a":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَالْعَجْزِ وَالْكَسَلِ، وَالْبُخْلِ وَالْجُبْنِ، وَضَلَعِ الدَّيْنِ وَغَلَبَةِ الرِّجَالِ","tl":"Allahumma inni a'udhu bika minal-hammi wal-hazan, wal-'ajzi wal-kasal, wal-bukhli wal-jubn, wa dala'id-dayni wa ghalabatir-rijal.","m":{"ur":"اے اللہ! میں تیری پناہ مانگتا ہوں فکر اور غم سے، عاجزی اور سستی سے، بخل اور بزدلی سے، قرض کے بوجھ سے اور لوگوں کے غلبے سے۔","ro":"Ae Allah! Main teri panah maangta hoon fikr aur gham se, aajizi aur susti se, bukhl aur buzdili se, qarz ke bojh se aur logon ke ghalbe se.","hi":"ऐ अल्लाह! मैं तेरी पनाह माँगता हूँ फ़िक्र और ग़म से, आजिज़ी और सुस्ती से, बुख़्ल और बुज़दिली से, क़र्ज़ के बोझ से और लोगों के ग़लबे से।","en":"O Allah! I seek refuge in You from worry and grief, from helplessness and laziness, from miserliness and cowardice, from the burden of debt and from being overpowered by men."},"r":"Sahih al-Bukhari 6369","n":{"ur":"نبی ﷺ اکثر یہ دعا پڑھتے تھے۔","ro":"Nabi ﷺ aksar yeh dua padhte the.","hi":"नबी ﷺ अक्सर यह दुआ पढ़ते थे।","en":"The Prophet ﷺ often recited this dua."}},{"id":83,"c":"mushkil","t":{"ro":"Hasbunallah (Dushman/Khauf ke waqt)","hi":"हस्बुनल्लाह (दुश्मन/ख़ौफ़ के वक़्त)","en":"Hasbunallah (at the time of an enemy or fear)"},"a":"حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ","tl":"Hasbunallahu wa ni'mal-wakil","m":{"ur":"ہمیں اللہ کافی ہے اور وہ بہترین کارساز ہے۔","ro":"Hamein Allah kaafi hai aur woh behtareen kaarsaaz hai.","hi":"हमें अल्लाह काफ़ी है और वह बेहतरीन कारसाज़ है।","en":"Allah is sufficient for us, and He is the best Disposer of affairs."},"r":"Sahih al-Bukhari 4563; Surah Aal-e-Imran 3:173","n":{"ur":"ابراہیم علیہ السلام نے آگ میں ڈالے جانے کے وقت یہ کہا۔","ro":"Ibrahim AS ne aag mein daale jane ke waqt yeh kaha.","hi":"इब्राहीम अलैहिस्सलाम ने आग में डाले जाने के वक़्त यह कहा।","en":"Ibrahim AS said this when he was thrown into the fire."}},{"id":84,"c":"mushkil","t":{"ro":"La hawla wa la quwwata illa billah","hi":"ला हौला व ला क़ुव्वता इल्ला बिल्लाह","en":"La hawla wa la quwwata illa billah"},"a":"لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ","tl":"La hawla wa la quwwata illa billah","m":{"ur":"گناہ سے بچنے کی کوئی طاقت اور نیکی کرنے کی کوئی قوت نہیں مگر اللہ کی مدد سے۔","ro":"Gunah se bachne ki koi taaqat aur neki karne ki koi quwwat nahi magar Allah ki madad se.","hi":"गुनाह से बचने की कोई ताक़त और नेकी करने की कोई क़ुव्वत नहीं मगर अल्लाह की मदद से।","en":"There is no power to avoid sin and no strength to do good except with Allah's help."},"r":"Sahih al-Bukhari 4205; Sahih Muslim 2704","n":{"ur":"یہ جنت کے خزانوں میں سے ایک خزانہ ہے۔","ro":"Yeh jannat ke khazanon mein se ek khazana hai.","hi":"यह जन्नत के ख़ज़ानों में से एक ख़ज़ाना है।","en":"It is one of the treasures of Paradise."}},{"id":85,"c":"mushkil","t":{"ro":"Musibat pahunchne par","hi":"मुसीबत पहुँचने पर","en":"When afflicted by a calamity"},"a":"إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ، اللَّهُمَّ أْجُرْنِي فِي مُصِيبَتِي وَأَخْلِفْ لِي خَيْرًا مِنْهَا","tl":"Inna lillahi wa inna ilayhi raji'un, Allahumma'jurni fi musibati wa akhlif li khayran minha","m":{"ur":"بے شک ہم اللہ ہی کے ہیں اور اسی کی طرف لوٹ کر جانے والے ہیں۔ اے اللہ! مجھے میری مصیبت میں اجر دے اور اس کے بدلے مجھے اس سے بہتر عطا فرما۔","ro":"Beshak hum Allah hi ke hain aur usi ki taraf laut kar jane wale hain. Ae Allah! Mujhe meri musibat mein ajr de aur uske badle mujhe isse behtar ata farma.","hi":"बेशक हम अल्लाह ही के हैं और उसी की तरफ़ लौट कर जाने वाले हैं। ऐ अल्लाह! मुझे मेरी मुसीबत में अज्र दे और उसके बदले मुझे इससे बेहतर अता फ़रमा।","en":"Indeed, to Allah we belong and to Him we shall return. O Allah! Reward me in my affliction and replace it for me with something better."},"r":"Sahih Muslim 918","n":{"ur":"حضرت ام سلمہ رضی اللہ عنہا نے یہ پڑھا تو اللہ نے انہیں نبی ﷺ کی رفاقت (بطور شوہر) عطا فرمائی۔","ro":"Hazrat Umm Salama RA ne yeh padha to Allah ne unhein Nabi ﷺ ki rifaqat (bataur shauhar) ata farmayi.","hi":"हज़रत उम्मे सलमा रज़ि. ने यह पढ़ा तो अल्लाह ने उन्हें नबी ﷺ की रफ़ाक़त (बतौर शौहर) अता फ़रमाई।","en":"When Umm Salama RA recited this, Allah granted her the Prophet ﷺ in marriage."}},{"id":86,"c":"bimari","t":{"ro":"Jism mein dard ho to (Ruqyah)","hi":"जिस्म में दर्द हो तो (रुक़्या)","en":"When there is pain in the body (Ruqyah)"},"a":"بِسْمِ اللَّهِ (3 بار) أَعُوذُ بِاللَّهِ وَقُدْرَتِهِ مِنْ شَرِّ مَا أَجِدُ وَأُحَاذِرُ (7 بار)","tl":"Bismillah (3 times). A'udhu billahi wa qudratihi min sharri ma ajidu wa uhadhir (7 times).","m":{"ur":"اللہ کے نام سے (3 بار)۔ میں اللہ اور اس کی قدرت کی پناہ مانگتا ہوں اس چیز کے شر سے جو میں محسوس کرتا ہوں اور جس سے ڈرتا ہوں (7 بار)۔","ro":"Allah ke naam se (3 baar). Main Allah aur uski qudrat ki panah maangta hoon is cheez ke shar se jo main mehsoos karta hoon aur jis se darta hoon (7 baar).","hi":"अल्लाह के नाम से (3 बार)। मैं अल्लाह और उसकी क़ुदरत की पनाह माँगता हूँ इस चीज़ के शर से जो मैं महसूस करता हूँ और जिससे डरता हूँ (7 बार)।","en":"In the name of Allah (3 times). I seek refuge in Allah and in His power from the evil of what I feel and what I fear (7 times)."},"r":"Sahih Muslim 2202","n":{"ur":"درد کی جگہ پر ہاتھ رکھ کر یہ مسنون علاج کریں۔","ro":"Dard ki jagah par haath rakh kar yeh masnoon ilaaj karein.","hi":"दर्द की जगह पर हाथ रखकर यह मसनून इलाज करें।","en":"Place your hand on the spot of pain and perform this Sunnah remedy."}},{"id":87,"c":"bimari","t":{"ro":"Bimar ke liye shifa ki dua","hi":"बीमार के लिए शिफ़ा की दुआ","en":"Dua for healing of the sick"},"a":"اللَّهُمَّ رَبَّ النَّاسِ، أَذْهِبِ الْبَأْسَ، اشْفِ أَنْتَ الشَّافِي، لَا شِفَاءَ إِلَّا شِفَاؤُكَ، شِفَاءً لَا يُغَادِرُ سَقَمًا","tl":"Allahumma Rabban-nas, adhhibil-ba's, ishfi antash-Shafi, la shifa'a illa shifa'uk, shifa'an la yughadiru saqama.","m":{"ur":"اے اللہ! لوگوں کے رب! تکلیف دور فرما، شفا دے، تو ہی شفا دینے والا ہے، تیری شفا کے سوا کوئی شفا نہیں، ایسی شفا دے جو کوئی بیماری نہ چھوڑے۔","ro":"Ae Allah! Logon ke Rab! Takleef door farma, shifa de, tu hi shifa dene wala hai, teri shifa ke siwa koi shifa nahi, aisi shifa de jo koi bimari na chhode.","hi":"ऐ अल्लाह! लोगों के रब! तकलीफ़ दूर फ़रमा, शिफ़ा दे, तू ही शिफ़ा देने वाला है, तेरी शिफ़ा के सिवा कोई शिफ़ा नहीं, ऐसी शिफ़ा दे जो कोई बीमारी न छोड़े।","en":"O Allah, Lord of mankind! Remove the affliction and grant healing; You are the Healer, there is no healing except Your healing, a healing that leaves no illness behind."},"r":"Sahih al-Bukhari 5675; Sahih Muslim 2191","n":{"ur":"نبی ﷺ بیمار پر ہاتھ پھیرتے اور یہ دعا پڑھتے تھے۔","ro":"Nabi ﷺ bimar par haath pherte aur yeh dua padhte the.","hi":"नबी ﷺ बीमार पर हाथ फेरते और यह दुआ पढ़ते थे।","en":"The Prophet ﷺ would pass his hand over the sick person and recite this dua."}},{"id":88,"c":"bimari","t":{"ro":"Ayyub AS ki dua (Sakht bimari mein)","hi":"अय्यूब अलैहिस्सलाम की दुआ (सख़्त बीमारी में)","en":"The dua of Ayyub AS (in severe illness)"},"a":"أَنِّي مَسَّنِيَ الضُّرُّ وَأَنْتَ أَرْحَمُ الرَّاحِمِينَ","tl":"Anni massaniyad-durru wa anta arhamur-rahimin","m":{"ur":"مجھے تکلیف پہنچی ہے اور تو سب رحم کرنے والوں سے زیادہ رحم کرنے والا ہے۔","ro":"Mujhe takleef pahunchi hai aur tu sab rahm karne walon se zyada rahm karne wala hai.","hi":"मुझे तकलीफ़ पहुँची है और तू सब रहम करने वालों से ज़्यादा रहम करने वाला है।","en":"Indeed, hardship has afflicted me, and You are the Most Merciful of the merciful."},"r":"Surah Al-Anbiya 21:83","n":{"ur":"حضرت ایوب علیہ السلام نے لمبی بیماری میں صبر کیا اور یہ دعا کی۔","ro":"Hazrat Ayyub AS ne lambi bimari mein sabr kiya aur yeh dua ki.","hi":"हज़रत अय्यूब अलैहिस्सलाम ने लंबी बीमारी में सब्र किया और यह दुआ की।","en":"Ayyub AS was patient through a long illness and made this dua."}},{"id":89,"c":"sone","t":{"ro":"Ayatul Kursi","hi":"आयतुल कुर्सी","en":"Ayat al-Kursi"},"a":"اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ ۚ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ ۚ لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ ۗ مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ إِلَّا بِمَا شَاءَ ۚ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ ۖ وَلَا يَئُودُهُ حِفْظُهُمَا ۚ وَهُوَ الْعَلِيُّ الْعَظِيمُ","tl":"Allahu la ilaha illa huwal-Hayyul-Qayyum, la ta'khudhuhu sinatun wa la nawm, lahu ma fis-samawati wa ma fil-ard, man dhal-ladhi yashfa'u 'indahu illa bi-idhnih, ya'lamu ma bayna aydihim wa ma khalfahum, wa la yuhituna bishay'im-min 'ilmihi illa bima sha', wasi'a kursiyyuhus-samawati wal-ard, wa la ya'uduhu hifzuhuma, wa huwal-'Aliyyul-'Azim.","m":{"ur":"اللہ کے سوا کوئی معبود نہیں، وہ زندہ ہے، سب کو تھامنے والا ہے۔ اسے نہ اونگھ آتی ہے نہ نیند۔ جو کچھ آسمانوں میں اور زمین میں ہے سب اسی کا ہے۔ کون ہے جو اس کی اجازت کے بغیر اس کے پاس سفارش کرے؟ وہ جانتا ہے جو ان کے سامنے ہے اور جو ان کے پیچھے ہے، اور وہ اس کے علم میں سے کسی چیز کا احاطہ نہیں کر سکتے مگر جتنا وہ چاہے۔ اس کی کرسی آسمانوں اور زمین کو گھیرے ہوئے ہے، اور ان کی حفاظت اسے تھکاتی نہیں، اور وہ بلند و عظمت والا ہے۔","ro":"Allah ke siwa koi mabood nahi, woh zinda hai, sab ko thaamne wala hai. Use na ungh aati hai na neend. Jo kuch aasmanon mein aur zameen mein hai sab usi ka hai. Kaun hai jo uski ijazat ke baghair uske paas sifarish kare? Woh jaanta hai jo unke saamne hai aur jo unke peechhe hai, aur woh uske ilm mein se kisi cheez ka ihata nahi kar sakte magar jitna woh chahe. Uski kursi aasmanon aur zameen ko gheray hue hai, aur unki hifazat use thakaati nahi, aur woh buland o azmat wala hai.","hi":"अल्लाह के सिवा कोई माबूद नहीं, वह ज़िंदा है, सब को थामने वाला है। उसे न ऊँघ आती है न नींद। जो कुछ आसमानों में और ज़मीन में है सब उसी का है। कौन है जो उसकी इजाज़त के बग़ैर उसके पास सिफ़ारिश करे? वह जानता है जो उनके सामने है और जो उनके पीछे है, और वह उसके इल्म में से किसी चीज़ का इहाता नहीं कर सकते मगर जितना वह चाहे। उसकी कुर्सी आसमानों और ज़मीन को घेरे हुए है, और उनकी हिफ़ाज़त उसे थकाती नहीं, और वह बुलंद व अज़मत वाला है।","en":"There is no god but Allah, the Ever-Living, the Sustainer of all. Neither drowsiness nor sleep overtakes Him. To Him belongs whatever is in the heavens and whatever is on the earth. Who is there that can intercede with Him except by His permission? He knows what is before them and what is behind them, and they encompass nothing of His knowledge except what He wills. His Kursi extends over the heavens and the earth, and preserving them does not tire Him, and He is the Most High, the Most Great."},"r":"Sahih al-Bukhari 2311","n":{"ur":"سوتے وقت پڑھنے سے ایک نگہبان مقرر ہوتا ہے اور شیطان قریب نہیں آتا۔","ro":"Sote waqt padhne se ek nigehbaan muqarrar hota hai aur shaitan qareeb nahi aata.","hi":"सोते वक़्त पढ़ने से एक निगहबान मुक़र्रर होता है और शैतान क़रीब नहीं आता।","en":"Reciting it at bedtime means a guardian is appointed over you and Satan does not come near."}},{"id":90,"c":"sone","t":{"ro":"Teeno Qul (Sone se pehle 3 martaba)","hi":"तीनों क़ुल (सोने से पहले 3 मर्तबा)","en":"The Three Quls (3 times before sleeping)"},"a":"قُلْ هُوَ اللَّهُ أَحَدٌ ﴿١﴾ اللَّهُ الصَّمَدُ ﴿٢﴾ لَمْ يَلِدْ وَلَمْ يُولَدْ ﴿٣﴾ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ ﴿٤﴾ قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ ﴿١﴾ مِنْ شَرِّ مَا خَلَقَ ﴿٢﴾ وَمِنْ شَرِّ غَاسِقٍ إِذَا وَقَبَ ﴿٣﴾ وَمِنْ شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ ﴿٤﴾ وَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ ﴿٥﴾ قُلْ أَعُوذُ بِرَبِّ النَّاسِ ﴿١﴾ مَلِكِ النَّاسِ ﴿٢﴾ إِلَٰهِ النَّاسِ ﴿٣﴾ مِنْ شَرِّ الْوَسْوَاسِ الْخَنَّاسِ ﴿٤﴾ الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ ﴿٥﴾ مِنَ الْجِنَّةِ وَالنَّاسِ ﴿٦﴾","tl":"Qul huwallahu ahad. Allahus-Samad. Lam yalid wa lam yulad. Wa lam yakun lahu kufuwan ahad. Qul a'udhu bi Rabbil-falaq. Min sharri ma khalaq. Wa min sharri ghasiqin idha waqab. Wa min sharrin-naffathati fil-'uqad. Wa min sharri hasidin idha hasad. Qul a'udhu bi Rabbin-nas. Malikin-nas. Ilahin-nas. Min sharril-waswasil-khannas. Alladhi yuwaswisu fi sudurin-nas. Minal-jinnati wan-nas.","m":{"ur":"کہہ دیجیے: وہ اللہ ایک ہے۔ اللہ بے نیاز ہے۔ نہ اس نے کسی کو جنا اور نہ وہ جنا گیا۔ اور نہ کوئی اس کے برابر کا ہے۔ کہہ دیجیے: میں صبح کے رب کی پناہ میں آتا ہوں، اس کی مخلوق کے شر سے، اور اندھیری رات کے شر سے جب وہ چھا جائے، اور گرہوں میں پھونکنے والیوں کے شر سے، اور حسد کرنے والے کے شر سے جب وہ حسد کرے۔ کہہ دیجیے: میں لوگوں کے رب کی پناہ میں آتا ہوں، لوگوں کے بادشاہ کی، لوگوں کے معبود کی، وسوسہ ڈالنے والے پیچھے ہٹ جانے والے کے شر سے، جو لوگوں کے سینوں میں وسوسے ڈالتا ہے، جنوں میں سے اور انسانوں میں سے۔","ro":"Kah dijiye: Woh Allah ek hai. Allah be-niyaz hai. Na us ne kisi ko jana aur na woh jana gaya. Aur na koi uske barabar ka hai. Kah dijiye: Main subah ke Rab ki panah mein aata hoon, uski makhlooq ke shar se, aur andheri raat ke shar se jab woh chha jaye, aur girhon mein phoonkne waliyon ke shar se, aur hasad karne wale ke shar se jab woh hasad kare. Kah dijiye: Main logon ke Rab ki panah mein aata hoon, logon ke badshah ki, logon ke mabood ki, waswasa dalne wale peechhe hat jane wale ke shar se, jo logon ke seenon mein waswase dalta hai, jinnon mein se aur insaanon mein se.","hi":"कह दीजिए: वह अल्लाह एक है। अल्लाह बे-नियाज़ है। न उसने किसी को जना और न वह जना गया। और न कोई उसके बराबर का है। कह दीजिए: मैं सुबह के रब की पनाह में आता हूँ, उसकी मख़लूक़ के शर से, और अँधेरी रात के शर से जब वह छा जाए, और गिरहों में फूँकने वालियों के शर से, और हसद करने वाले के शर से जब वह हसद करे। कह दीजिए: मैं लोगों के रब की पनाह में आता हूँ, लोगों के बादशाह की, लोगों के माबूद की, वसवसा डालने वाले पीछे हट जाने वाले के शर से, जो लोगों के सीनों में वसवसे डालता है, जिन्नों में से और इंसानों में से।","en":"Say: He is Allah, the One. Allah is the Self-Sufficient. He neither begot nor was begotten. And there is none comparable to Him. Say: I seek refuge in the Lord of the daybreak, from the evil of what He has created, and from the evil of the darkness when it settles, and from the evil of those who blow on knots, and from the evil of the envier when he envies. Say: I seek refuge in the Lord of mankind, the King of mankind, the God of mankind, from the evil of the retreating whisperer, who whispers in the hearts of mankind, from among the jinn and mankind."},"r":"Sahih al-Bukhari 5017","n":{"ur":"ہاتھوں میں پھونک کر جسم پر پھیریں، 3 بار کریں۔","ro":"Haathon mein phoonk kar jism par pheren, 3 baar karein.","hi":"हाथों में फूँक कर जिस्म पर फेरें, 3 बार करें।","en":"Blow into your cupped hands and wipe them over your body; do this 3 times."}},{"id":91,"c":"sone","t":{"ro":"Surah Baqarah ki aakhri 2 ayaat","hi":"सूरह बक़रह की आख़िरी 2 आयात","en":"The last 2 verses of Surah al-Baqarah"},"a":"آمَنَ الرَّسُولُ بِمَا أُنزِلَ إِلَيْهِ مِن رَّبِّهِ وَالْمُؤْمِنُونَ ۚ كُلٌّ آمَنَ بِاللَّهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّن رُّسُلِهِ ۚ وَقَالُوا سَمِعْنَا وَأَطَعْنَا ۖ غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ ﴿٢٨٥﴾ لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا ۚ لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ ۗ رَبَّنَا لَا تُؤَاخِذْنَا إِن نَّسِينَا أَوْ أَخْطَأْنَا ۚ رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَا إِصْرًا كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِن قَبْلِنَا ۚ رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِ ۖ وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا ۚ أَنتَ مَوْلَانَا فَانصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ ﴿٢٨٦﴾","tl":"Amanar-Rasulu bima unzila ilayhi mir-Rabbihi wal-mu'minun, kullun amana billahi wa mala'ikatihi wa kutubihi wa rusulih, la nufarriqu bayna ahadim-mir-rusulih, wa qalu sami'na wa ata'na ghufranaka Rabbana wa ilaykal-masir. La yukallifullahu nafsan illa wus'aha, laha ma kasabat wa 'alayha maktasabat, Rabbana la tu'akhidhna in nasina aw akhta'na, Rabbana wa la tahmil 'alayna isran kama hamaltahu 'alal-ladhina min qablina, Rabbana wa la tuhammilna ma la taqata lana bih, wa'fu 'anna waghfir lana warhamna, anta mawlana fansurna 'alal-qawmil-kafirin.","m":{"ur":"رسول ﷺ اس پر ایمان لائے جو ان کے رب کی طرف سے ان پر اتارا گیا، اور مومن بھی۔ سب اللہ پر، اس کے فرشتوں پر، اس کی کتابوں پر اور اس کے رسولوں پر ایمان لائے (اور کہتے ہیں:) ہم اس کے رسولوں میں کوئی فرق نہیں کرتے۔ اور انہوں نے کہا: ہم نے سنا اور مان لیا، اے ہمارے رب! تیری بخشش چاہیے اور تیری ہی طرف لوٹنا ہے۔ اللہ کسی جان پر اس کی طاقت سے زیادہ بوجھ نہیں ڈالتا۔ جو نیکی اس نے کمائی اس کا فائدہ اسی کو، اور جو برائی کمائی اس کا نقصان اسی پر۔ اے ہمارے رب! اگر ہم بھول جائیں یا خطا کریں تو ہمیں نہ پکڑنا۔ اے ہمارے رب! ہم پر وہ بوجھ نہ ڈال جو تو نے ہم سے پہلے لوگوں پر ڈالا۔ اے ہمارے رب! ہم سے وہ بوجھ نہ اٹھوا جس کی ہمیں طاقت نہیں، اور ہمیں معاف کر، ہمیں بخش دے اور ہم پر رحم فرما، تو ہی ہمارا مولیٰ ہے، پس کافروں کے مقابلے میں ہماری مدد فرما۔","ro":"Rasool ﷺ us par imaan laaye jo unke Rab ki taraf se un par utara gaya, aur momin bhi. Sab Allah par, uske farishton par, uski kitabon par aur uske rasoolon par imaan laaye (aur kehte hain:) Hum uske rasoolon mein koi farq nahi karte. Aur unhon ne kaha: Hum ne suna aur maan liya, ae hamare Rab! Teri bakhshish chahiye aur teri hi taraf laut na hai. Allah kisi jaan par uski taaqat se zyada bojh nahi daalta. Jo neki us ne kamaai uska faida usi ko, aur jo buraai kamaai uska nuqsan usi par. Ae hamare Rab! Agar hum bhool jayen ya khata karein to hamein na pakadna. Ae hamare Rab! Hum par woh bojh na daal jo tu ne hum se pehle logon par daala. Ae hamare Rab! Hum se woh bojh na uthwa jiski hamein taaqat nahi, aur hamein maaf kar, hamein bakhsh de aur hum par rahm farma, tu hi hamara Maula hai, pas kaafiron ke muqable mein hamari madad farma.","hi":"रसूल ﷺ उस पर ईमान लाए जो उनके रब की तरफ़ से उन पर उतारा गया, और मोमिन भी। सब अल्लाह पर, उसके फ़रिश्तों पर, उसकी किताबों पर और उसके रसूलों पर ईमान लाए (और कहते हैं:) हम उसके रसूलों में कोई फ़र्क़ नहीं करते। और उन्होंने कहा: हमने सुना और मान लिया, ऐ हमारे रब! तेरी बख़्शिश चाहिए और तेरी ही तरफ़ लौटना है। अल्लाह किसी जान पर उसकी ताक़त से ज़्यादा बोझ नहीं डालता। जो नेकी उसने कमाई उसका फ़ायदा उसी को, और जो बुराई कमाई उसका नुक़सान उसी पर। ऐ हमारे रब! अगर हम भूल जाएँ या ख़ता करें तो हमें न पकड़ना। ऐ हमारे रब! हम पर वह बोझ न डाल जो तूने हमसे पहले लोगों पर डाला। ऐ हमारे रब! हमसे वह बोझ न उठवा जिसकी हमें ताक़त नहीं, और हमें माफ़ कर, हमें बख़्श दे और हम पर रहम फ़रमा, तू ही हमारा मौला है, पस काफ़िरों के मुक़ाबले में हमारी मदद फ़रमा।","en":"The Messenger ﷺ believes in what has been sent down to him from his Lord, and so do the believers. All of them believe in Allah, His angels, His books and His messengers (saying:) We make no distinction between any of His messengers. And they say: We hear and we obey. Your forgiveness, our Lord, and to You is the final return. Allah does not burden a soul beyond its capacity. It will have what it has earned, and it will bear what it has earned. Our Lord! Do not hold us accountable if we forget or make a mistake. Our Lord! Do not place upon us a burden like the one You placed on those before us. Our Lord! Do not burden us with what we have no strength to bear. Pardon us, forgive us, and have mercy on us. You are our Protector, so help us against the disbelieving people."},"r":"Sahih al-Bukhari 5009; Sahih Muslim 807","n":{"ur":"جو رات کو یہ پڑھے، یہ اسے کافی ہو جاتی ہیں۔","ro":"Jo raat ko yeh padhe, yeh use kaafi ho jaati hain.","hi":"जो रात को यह पढ़े, यह उसे काफ़ी हो जाती हैं।","en":"Whoever recites these at night, they will suffice him."}},{"id":92,"c":"sone","t":{"ro":"Sone ki dua","hi":"सोने की दुआ","en":"Dua for going to sleep"},"a":"بِاسْمِكَ اللَّهُمَّ أَمُوتُ وَأَحْيَا","tl":"Bismika Allahumma amutu wa ahya","m":{"ur":"اے اللہ! تیرے ہی نام کے ساتھ میں مرتا ہوں (سوتا ہوں) اور جیتا ہوں (جاگتا ہوں)۔","ro":"Ae Allah! Tere hi naam ke saath main marta hoon (sota hoon) aur jeeta hoon (jaagta hoon).","hi":"ऐ अल्लाह! तेरे ही नाम के साथ मैं मरता हूँ (सोता हूँ) और जीता हूँ (जागता हूँ)।","en":"O Allah! In Your name I die (sleep) and I live (wake)."},"r":"Sahih al-Bukhari 6324","n":{"ur":"نیند کو موت کا بھائی کہا گیا ہے۔","ro":"Neend ko maut ka bhai kaha gaya hai.","hi":"नींद को मौत का भाई कहा गया है।","en":"Sleep is called the brother of death."}},{"id":93,"c":"sone","t":{"ro":"Tasbeeh-e-Fatima RA","hi":"तस्बीह-ए-फ़ातिमा रज़ि.","en":"Tasbih of Fatima RA"},"a":"سُبْحَانَ اللَّهِ (33) الْحَمْدُ لِلَّهِ (33) اللَّهُ أَكْبَرُ (34)","tl":"Subhanallah (33), Alhamdulillah (33), Allahu Akbar (34)","m":{"ur":"اللہ پاک ہے (33 بار)۔ سب تعریف اللہ کے لیے ہے (33 بار)۔ اللہ سب سے بڑا ہے (34 بار)۔","ro":"Allah paak hai (33 baar). Sab taareef Allah ke liye hai (33 baar). Allah sab se bada hai (34 baar).","hi":"अल्लाह पाक है (33 बार)। सब तारीफ़ अल्लाह के लिए है (33 बार)। अल्लाह सबसे बड़ा है (34 बार)।","en":"Glory be to Allah (33 times). All praise is for Allah (33 times). Allah is the Greatest (34 times)."},"r":"Sahih al-Bukhari 3113; Sahih Muslim 2727","n":{"ur":"فاطمہ رضی اللہ عنہا نے خادم مانگا تو نبی ﷺ نے یہ بتایا کہ یہ خادم سے بہتر ہے۔","ro":"Fatima RA ne khadim maanga to Nabi ﷺ ne yeh bataya ke yeh khadim se behtar hai.","hi":"फ़ातिमा रज़ि. ने ख़ादिम माँगा तो नबी ﷺ ने यह बताया कि यह ख़ादिम से बेहतर है।","en":"When Fatima RA asked for a servant, the Prophet ﷺ taught her this and told her it is better than a servant."}},{"id":94,"c":"roz","t":{"ro":"Khana shuru karne se pehle","hi":"खाना शुरू करने से पहले","en":"Before starting to eat"},"a":"بِسْمِ اللَّهِ","tl":"Bismillah","m":{"ur":"اللہ کے نام سے (شروع کرتا ہوں)۔","ro":"Allah ke naam se (shuru karta hoon).","hi":"अल्लाह के नाम से (शुरू करता हूँ)।","en":"In the name of Allah (I begin)."},"r":"Abu Dawud, Tirmidhi (Albani: Sahih — Sahih al-Jami' 380)","n":{"ur":"اگر شروع میں بھول جائیں تو یاد آنے پر کہیں: «بِسْمِ اللَّهِ أَوَّلَهُ وَآخِرَهُ» (اس کے شروع اور آخر میں اللہ کے نام سے)۔","ro":"Agar shuru mein bhool jayen to yaad aane par kahein: «بِسْمِ اللَّهِ أَوَّلَهُ وَآخِرَهُ» (iske shuru aur aakhir mein Allah ke naam se).","hi":"अगर शुरू में भूल जाएँ तो याद आने पर कहें: «بِسْمِ اللَّهِ أَوَّلَهُ وَآخِرَهُ» (इसके शुरू और आख़िर में अल्लाह के नाम से)।","en":"If you forget at the beginning, say when you remember: «بِسْمِ اللَّهِ أَوَّلَهُ وَآخِرَهُ» (In the name of Allah at its beginning and its end)."}},{"id":95,"c":"roz","t":{"ro":"Khana khane ke baad","hi":"खाना खाने के बाद","en":"After eating"},"a":"الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنِي هَذَا وَرَزَقَنِيهِ مِنْ غَيْرِ حَوْلٍ مِنِّي وَلَا قُوَّةٍ","tl":"Alhamdu lillahil-ladhi at'amani hadha wa razaqanihi min ghayri hawlin minni wa la quwwah","m":{"ur":"تمام تعریف اللہ کے لیے ہے جس نے مجھے یہ کھانا کھلایا اور مجھے اپنی طاقت اور قوت کے بغیر یہ عطا کیا۔","ro":"Tamam taareef Allah ke liye hai jis ne mujhe yeh khana khilaya aur mujhe apni taaqat aur quwwat ke baghair yeh ata kiya.","hi":"तमाम तारीफ़ अल्लाह के लिए है जिसने मुझे यह खाना खिलाया और मुझे अपनी ताक़त और क़ुव्वत के बग़ैर यह अता किया।","en":"All praise is for Allah who fed me this food and provided it for me without any power or strength on my part."},"r":"Abu Dawud, Tirmidhi, Ibn Majah (Albani: Hasan — Sahih al-Jami' 6086, Irwa 1989)","n":{"ur":"حدیث میں ہے کہ جو شخص کھانے کے بعد یہ دعا پڑھے اس کے پچھلے گناہ معاف کر دیے جاتے ہیں۔","ro":"Hadees mein hai ke jo shakhs khane ke baad yeh dua padhe uske pichhle gunah maaf kar diye jaate hain.","hi":"हदीस में है कि जो शख़्स खाने के बाद यह दुआ पढ़े उसके पिछले गुनाह माफ़ कर दिए जाते हैं।","en":"It is reported in a hadith that whoever recites this dua after eating has his previous sins forgiven."}},{"id":96,"c":"roz","t":{"ro":"Dawat dene wale ke liye dua","hi":"दावत देने वाले के लिए दुआ","en":"Dua for the host who invited you"},"a":"اللَّهُمَّ بَارِكْ لَهُمْ فِيمَا رَزَقْتَهُمْ، وَاغْفِرْ لَهُمْ وَارْحَمْهُمْ","tl":"Allahumma barik lahum fima razaqtahum, waghfir lahum warhamhum","m":{"ur":"اے اللہ! جو رزق تو نے انہیں دیا اس میں برکت دے، انہیں بخش دے اور ان پر رحم فرما۔","ro":"Ae Allah! Jo rizq tu ne unhein diya usmein barkat de, unhein bakhsh de aur un par rahm farma.","hi":"ऐ अल्लाह! जो रिज़्क़ तूने उन्हें दिया उसमें बरकत दे, उन्हें बख़्श दे और उन पर रहम फ़रमा।","en":"O Allah! Bless them in what You have provided for them, forgive them and have mercy on them."},"r":"Sahih Muslim 2042","n":{"ur":"یہ دعا نبی ﷺ نے اپنے میزبان کے لیے فرمائی۔ کسی کے ہاں کھانا کھا کر میزبان کو یہ دعا دیں۔","ro":"Yeh dua Nabi ﷺ ne apne mezbaan ke liye farmai. Kisi ke haan khana kha kar mezbaan ko yeh dua dein.","hi":"यह दुआ नबी ﷺ ने अपने मेज़बान के लिए फ़रमाई। किसी के यहाँ खाना खाकर मेज़बान को यह दुआ दें।","en":"The Prophet ﷺ made this dua for his host. After eating at someone's home, make this dua for the host."}},{"id":97,"c":"roz","t":{"ro":"Naya kapda pehente waqt","hi":"नया कपड़ा पहनते वक़्त","en":"When wearing new clothes"},"a":"اللَّهُمَّ لَكَ الْحَمْدُ أَنْتَ كَسَوْتَنِيهِ، أَسْأَلُكَ مِنْ خَيْرِهِ وَخَيْرِ مَا صُنِعَ لَهُ، وَأَعُوذُ بِكَ مِنْ شَرِّهِ وَشَرِّ مَا صُنِعَ لَهُ","tl":"Allahumma lakal-hamdu anta kasawtanihi, as'aluka min khayrihi wa khayri ma suni'a lah, wa a'udhu bika min sharrihi wa sharri ma suni'a lah","m":{"ur":"اے اللہ! تیرے ہی لیے سب تعریف ہے، تو نے مجھے یہ پہنایا۔ میں تجھ سے اس کی بھلائی اور جس مقصد کے لیے یہ بنا اس کی بھلائی مانگتا ہوں، اور اس کے شر اور جس مقصد کے لیے یہ بنا اس کے شر سے تیری پناہ چاہتا ہوں۔","ro":"Ae Allah! Tere hi liye sab taareef hai, tu ne mujhe yeh pehnaya. Main tujh se iski bhalai aur jis maqsad ke liye yeh bana uski bhalai maangta hoon, aur iske shar aur jis maqsad ke liye yeh bana uske shar se teri panah chahta hoon.","hi":"ऐ अल्लाह! तेरे ही लिए सब तारीफ़ है, तूने मुझे यह पहनाया। मैं तुझसे इसकी भलाई और जिस मक़सद के लिए यह बना उसकी भलाई माँगता हूँ, और इसके शर और जिस मक़सद के लिए यह बना उसके शर से तेरी पनाह चाहता हूँ।","en":"O Allah! All praise is Yours; You have clothed me with this. I ask You for its good and the good of what it was made for, and I seek refuge in You from its evil and the evil of what it was made for."},"r":"Abu Dawud, Tirmidhi (Albani: Sahih — Sahih al-Jami')","n":{"ur":"نیا کپڑا پہنتے وقت یہ دعا پڑھی جاتی ہے۔","ro":"Naya kapda pehente waqt yeh dua padhi jaati hai.","hi":"नया कपड़ा पहनते वक़्त यह दुआ पढ़ी जाती है।","en":"This dua is recited when putting on new clothes."}},{"id":98,"c":"roz","t":{"ro":"Kapda pehente waqt (aam)","hi":"कपड़ा पहनते वक़्त (आम)","en":"When wearing clothes (general)"},"a":"الْحَمْدُ لِلَّهِ الَّذِي كَسَانِي هَذَا وَرَزَقَنِيهِ مِنْ غَيْرِ حَوْلٍ مِنِّي وَلَا قُوَّةٍ","tl":"Alhamdu lillahil-ladhi kasani hadha wa razaqanihi min ghayri hawlin minni wa la quwwah","m":{"ur":"تمام تعریف اللہ کے لیے ہے جس نے مجھے یہ پہنایا اور میری طاقت اور قوت کے بغیر مجھے عطا کیا۔","ro":"Tamam taareef Allah ke liye hai jis ne mujhe yeh pehnaya aur meri taaqat aur quwwat ke baghair mujhe ata kiya.","hi":"तमाम तारीफ़ अल्लाह के लिए है जिसने मुझे यह पहनाया और मेरी ताक़त और क़ुव्वत के बग़ैर मुझे अता किया।","en":"All praise is for Allah who clothed me with this and provided it for me without any power or strength on my part."},"r":"Abu Dawud, Tirmidhi (Albani: Hasan — Sahih al-Jami' 6086, Irwa 1989)","n":{"ur":"حدیث میں ہے کہ جو شخص کپڑا پہن کر یہ دعا پڑھے اس کے پچھلے گناہ معاف کر دیے جاتے ہیں۔","ro":"Hadees mein hai ke jo shakhs kapda pehen kar yeh dua padhe uske pichhle gunah maaf kar diye jaate hain.","hi":"हदीस में है कि जो शख़्स कपड़ा पहनकर यह दुआ पढ़े उसके पिछले गुनाह माफ़ कर दिए जाते हैं।","en":"It is reported in a hadith that whoever recites this dua after putting on clothes has his previous sins forgiven."}},{"id":99,"c":"roz","t":{"ro":"Aaina dekhte waqt","hi":"आईना देखते वक़्त","en":"When looking in the mirror"},"a":"اللَّهُمَّ كَمَا حَسَّنْتَ خَلْقِي فَحَسِّنْ خُلُقِي","tl":"Allahumma kama hassanta khalqi fahassin khuluqi","m":{"ur":"اے اللہ! جیسے تو نے میری صورت اچھی بنائی، ویسے ہی میرے اخلاق بھی اچھے کر دے۔","ro":"Ae Allah! Jaise tu ne meri soorat achhi banai, waise hi mere akhlaq bhi achhe kar de.","hi":"ऐ अल्लाह! जैसे तूने मेरी सूरत अच्छी बनाई, वैसे ही मेरे अख़लाक़ भी अच्छे कर दे।","en":"O Allah! Just as You made my physical form good, make my character good as well."},"r":"Musnad Ahmad (Albani: Sahih — Sahih al-Jami' 1307, Irwa 74)","n":{"ur":"صورت اللہ کی عطا ہے، اس پر شکر کے ساتھ اچھے اخلاق کی دعا کی جاتی ہے۔","ro":"Soorat Allah ki ata hai, is par shukr ke saath achhe akhlaq ki dua ki jaati hai.","hi":"सूरत अल्लाह की अता है, इस पर शुक्र के साथ अच्छे अख़लाक़ की दुआ की जाती है।","en":"One's appearance is a gift from Allah; along with gratitude for it, one asks for good character."}},{"id":100,"c":"roz","t":{"ro":"Bait-ul-khala jane se pehle","hi":"बैतुल ख़ला जाने से पहले","en":"Before entering the toilet"},"a":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْخُبُثِ وَالْخَبَائِثِ","tl":"Allahumma inni a'udhu bika minal-khubuthi wal-khaba'ith","m":{"ur":"اے اللہ! میں ناپاک جنوں (نر و مادہ) کے شر سے تیری پناہ چاہتا ہوں۔","ro":"Ae Allah! Main napaak jinnon (nar o maada) ke shar se teri panah chahta hoon.","hi":"ऐ अल्लाह! मैं नापाक जिन्नों (नर व मादा) के शर से तेरी पनाह चाहता हूँ।","en":"O Allah! I seek refuge in You from the evil male and female jinn."},"r":"Sahih Bukhari 142, Sahih Muslim 375","n":{"ur":"بیت الخلا میں داخل ہونے سے پہلے (یا کھلی جگہ میں ستر کھولنے سے پہلے) پڑھی جاتی ہے۔","ro":"Bait-ul-khala mein dakhil hone se pehle (ya khuli jagah mein satr kholne se pehle) padhi jaati hai.","hi":"बैतुल ख़ला में दाख़िल होने से पहले (या खुली जगह में सतर खोलने से पहले) पढ़ी जाती है।","en":"It is recited before entering the toilet (or before uncovering oneself in an open place)."}},{"id":101,"c":"roz","t":{"ro":"Bait-ul-khala se nikal kar","hi":"बैतुल ख़ला से निकल कर","en":"After leaving the toilet"},"a":"غُفْرَانَكَ","tl":"Ghufranak","m":{"ur":"(اے اللہ!) میں تیری بخشش مانگتا ہوں۔","ro":"(Ae Allah!) Main teri bakhshish maangta hoon.","hi":"(ऐ अल्लाह!) मैं तेरी बख़्शिश माँगता हूँ।","en":"(O Allah!) I seek Your forgiveness."},"r":"Abu Dawud 30, Tirmidhi 7, Ibn Majah 300","n":{"ur":"بیت الخلا سے نکلنے پر یہ کہا جاتا ہے۔","ro":"Bait-ul-khala se nikalne par yeh kaha jaata hai.","hi":"बैतुल ख़ला से निकलने पर यह कहा जाता है।","en":"This is said upon leaving the toilet."}},{"id":102,"c":"roz","t":{"ro":"Chheenk aane par","hi":"छींक आने पर","en":"When sneezing"},"a":"الْحَمْدُ لِلَّهِ","tl":"Alhamdulillah","m":{"ur":"تمام تعریف اللہ کے لیے ہے۔","ro":"Tamam taareef Allah ke liye hai.","hi":"तमाम तारीफ़ अल्लाह के लिए है।","en":"All praise is for Allah."},"r":"Sahih Bukhari 6224","n":{"ur":"جسے چھینک آئے وہ «الْحَمْدُ لِلَّهِ» کہے، سننے والا «يَرْحَمُكَ اللَّهُ» (اللہ تجھ پر رحم کرے) کہے، اور چھینکنے والا جواب میں «يَهْدِيكُمُ اللَّهُ وَيُصْلِحُ بَالَكُمْ» (اللہ تمہیں ہدایت دے اور تمہارا حال درست کرے) کہے۔","ro":"Jise chheenk aaye woh «الْحَمْدُ لِلَّهِ» kahe, sunne wala «يَرْحَمُكَ اللَّهُ» (Allah tujh par rahm kare) kahe, aur chheenkne wala jawab mein «يَهْدِيكُمُ اللَّهُ وَيُصْلِحُ بَالَكُمْ» (Allah tumhein hidayat de aur tumhara haal durust kare) kahe.","hi":"जिसे छींक आए वह «الْحَمْدُ لِلَّهِ» कहे, सुनने वाला «يَرْحَمُكَ اللَّهُ» (अल्लाह तुझ पर रहम करे) कहे, और छींकने वाला जवाब में «يَهْدِيكُمُ اللَّهُ وَيُصْلِحُ بَالَكُمْ» (अल्लाह तुम्हें हिदायत दे और तुम्हारा हाल दुरुस्त करे) कहे।","en":"The one who sneezes should say «الْحَمْدُ لِلَّهِ»; the listener should say «يَرْحَمُكَ اللَّهُ» (May Allah have mercy on you); and the sneezer replies «يَهْدِيكُمُ اللَّهُ وَيُصْلِحُ بَالَكُمْ» (May Allah guide you and set your affairs right)."}},{"id":103,"c":"roz","t":{"ro":"Salam karna","hi":"सलाम करना","en":"Giving the greeting of salam"},"a":"السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ","tl":"As-salamu 'alaykum wa rahmatullahi wa barakatuh","m":{"ur":"تم پر سلامتی ہو اور اللہ کی رحمت اور اس کی برکتیں ہوں۔","ro":"Tum par salamati ho aur Allah ki rahmat aur uski barkatein hon.","hi":"तुम पर सलामती हो और अल्लाह की रहमत और उसकी बरकतें हों।","en":"Peace be upon you, and the mercy of Allah and His blessings."},"r":"Abu Dawud 5195, Tirmidhi 2689","n":{"ur":"جواب میں «وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ» کہا جاتا ہے۔ پورا سلام کہنے پر زیادہ نیکیاں ملتی ہیں۔","ro":"Jawab mein «وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ» kaha jaata hai. Poora salam kehne par zyada nekiyan milti hain.","hi":"जवाब में «وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ» कहा जाता है। पूरा सलाम कहने पर ज़्यादा नेकियाँ मिलती हैं।","en":"The reply is «وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ». Saying the full greeting earns more good deeds."}},{"id":104,"c":"roz","t":{"ro":"Kisi ne bhalai ki to","hi":"किसी ने भलाई की तो","en":"When someone does you a favour"},"a":"جَزَاكَ اللَّهُ خَيْرًا","tl":"Jazakallahu khayran","m":{"ur":"اللہ تمہیں اچھا بدلہ دے۔","ro":"Allah tumhein achha badla de.","hi":"अल्लाह तुम्हें अच्छा बदला दे।","en":"May Allah reward you with goodness."},"r":"Tirmidhi 2035 (Albani: Sahih — Sahih at-Targhib 969)","n":{"ur":"نبی ﷺ نے فرمایا: جس کے ساتھ کوئی بھلائی کی جائے اور وہ بھلائی کرنے والے سے یہ کہے تو اس نے خوب شکریہ ادا کیا۔","ro":"Nabi ﷺ ne farmaya: Jis ke saath koi bhalai ki jaye aur woh bhalai karne wale se yeh kahe to us ne khoob shukriya ada kiya.","hi":"नबी ﷺ ने फ़रमाया: जिसके साथ कोई भलाई की जाए और वह भलाई करने वाले से यह कहे तो उसने ख़ूब शुक्रिया अदा किया।","en":"The Prophet ﷺ said: Whoever has a favour done to him and says this to the one who did it has thanked him thoroughly."}},{"id":105,"c":"roz","t":{"ro":"Majlis se uthte waqt (Kaffarah-e-Majlis)","hi":"मजलिस से उठते वक़्त (कफ़्फ़ारा-ए-मजलिस)","en":"When rising from a gathering (Kaffarat al-Majlis)"},"a":"سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ","tl":"Subhanakal-lahumma wa bihamdika, ash-hadu an la ilaha illa anta, astaghfiruka wa atubu ilayk","m":{"ur":"اے اللہ! تو پاک ہے اپنی تعریف کے ساتھ، میں گواہی دیتا ہوں کہ تیرے سوا کوئی معبود نہیں، میں تجھ سے بخشش مانگتا ہوں اور تیری طرف رجوع کرتا ہوں۔","ro":"Ae Allah! Tu paak hai apni taareef ke saath, main gawahi deta hoon ke tere siwa koi mabood nahi, main tujh se bakhshish maangta hoon aur teri taraf rujoo karta hoon.","hi":"ऐ अल्लाह! तू पाक है अपनी तारीफ़ के साथ, मैं गवाही देता हूँ कि तेरे सिवा कोई माबूद नहीं, मैं तुझसे बख़्शिश माँगता हूँ और तेरी तरफ़ रुजू करता हूँ।","en":"Glory and praise be to You, O Allah. I bear witness that there is no god but You; I seek Your forgiveness and turn to You in repentance."},"r":"Tirmidhi 3433, Abu Dawud 4859","n":{"ur":"مجلس میں ہونے والی کوتاہیوں کا کفارہ ہے، اس لیے مجلس ختم ہونے پر پڑھیں۔","ro":"Majlis mein hone wali kotahiyon ka kaffarah hai, isliye majlis khatam hone par padhein.","hi":"मजलिस में होने वाली कोताहियों का कफ़्फ़ारा है, इसलिए मजलिस ख़त्म होने पर पढ़ें।","en":"It is an expiation for shortcomings committed in a gathering, so recite it when the gathering ends."}},{"id":106,"c":"roz","t":{"ro":"Gusse ke waqt","hi":"ग़ुस्से के वक़्त","en":"When angry"},"a":"أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ","tl":"A'udhu billahi minash-shaytanir-rajim","m":{"ur":"میں شیطان مردود سے اللہ کی پناہ مانگتا ہوں۔","ro":"Main shaitan mardood se Allah ki panah maangta hoon.","hi":"मैं शैतान मरदूद से अल्लाह की पनाह माँगता हूँ।","en":"I seek refuge in Allah from the accursed Satan."},"r":"Sahih Bukhari 3282, Sahih Muslim 2610","n":{"ur":"نبی ﷺ نے فرمایا کہ مجھے ایک کلمہ معلوم ہے، اگر غصے والا اسے کہے تو اس کا غصہ جاتا رہے گا، اور وہ یہی ہے۔","ro":"Nabi ﷺ ne farmaya ke mujhe ek kalimah maloom hai, agar ghusse wala use kahe to uska ghussa jaata rahega, aur woh yehi hai.","hi":"नबी ﷺ ने फ़रमाया कि मुझे एक कलिमा मालूम है, अगर ग़ुस्से वाला उसे कहे तो उसका ग़ुस्सा जाता रहेगा, और वह यही है।","en":"The Prophet ﷺ said: I know a phrase that, if an angry person says it, his anger will go away; it is this."}},{"id":107,"c":"roz","t":{"ro":"Sawari par baithne ki dua","hi":"सवारी पर बैठने की दुआ","en":"Dua when mounting a vehicle"},"a":"سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ، وَإِنَّا إِلَى رَبِّنَا لَمُنقَلِبُونَ","tl":"Subhanal-ladhi sakhkhara lana hadha wa ma kunna lahu muqrinin, wa inna ila rabbina lamunqalibun","m":{"ur":"پاک ہے وہ ذات جس نے اس (سواری) کو ہمارے قابو میں کر دیا، حالانکہ ہم اسے قابو میں لانے والے نہ تھے، اور بے شک ہم اپنے رب کی طرف لوٹ کر جانے والے ہیں۔","ro":"Paak hai woh zaat jis ne is (sawari) ko hamare qaabu mein kar diya, halaanke hum ise qaabu mein laane wale na the, aur beshak hum apne Rab ki taraf laut kar jane wale hain.","hi":"पाक है वह ज़ात जिसने इस (सवारी) को हमारे क़ाबू में कर दिया, हालाँकि हम इसे क़ाबू में लाने वाले न थे, और बेशक हम अपने रब की तरफ़ लौट कर जाने वाले हैं।","en":"Glory be to Him who has subjected this (vehicle) to us, though we could never have subdued it ourselves, and indeed to our Lord we shall return."},"r":"Surah Az-Zukhruf 43:13-14, Abu Dawud 2602, Tirmidhi 3446","n":{"ur":"گاڑی، بس، جہاز یا کسی بھی سواری پر بیٹھ کر پڑھیں۔ پہلے تین بار «اللَّهُ أَكْبَرُ» اور «الْحَمْدُ لِلَّهِ» کہنا بھی حدیث میں آیا ہے۔","ro":"Gaadi, bus, jahaaz ya kisi bhi sawari par baith kar padhein. Pehle teen baar «اللَّهُ أَكْبَرُ» aur «الْحَمْدُ لِلَّهِ» kehna bhi hadees mein aaya hai.","hi":"गाड़ी, बस, जहाज़ या किसी भी सवारी पर बैठकर पढ़ें। पहले तीन बार «اللَّهُ أَكْبَرُ» और «الْحَمْدُ لِلَّهِ» कहना भी हदीस में आया है।","en":"Recite it upon boarding a car, bus, plane or any vehicle. Saying «اللَّهُ أَكْبَرُ» and «الْحَمْدُ لِلَّهِ» three times beforehand is also reported in the hadith."}},{"id":108,"c":"roz","t":{"ro":"Safar ki dua","hi":"सफ़र की दुआ","en":"Dua for travel"},"a":"اللَّهُمَّ إِنَّا نَسْأَلُكَ فِي سَفَرِنَا هَذَا الْبِرَّ وَالتَّقْوَى، وَمِنَ الْعَمَلِ مَا تَرْضَى، اللَّهُمَّ هَوِّنْ عَلَيْنَا سَفَرَنَا هَذَا وَاطْوِ عَنَّا بُعْدَهُ","tl":"Allahumma inna nas'aluka fi safarina hadhal-birra wat-taqwa, wa minal-'amali ma tarda. Allahumma hawwin 'alayna safarana hadha watwi 'anna bu'dah","m":{"ur":"اے اللہ! ہم تجھ سے اپنے اس سفر میں نیکی اور تقویٰ مانگتے ہیں اور ایسے عمل مانگتے ہیں جن سے تو راضی ہو۔ اے اللہ! ہمارا یہ سفر آسان کر دے اور اس کی دوری ہم پر لپیٹ دے۔","ro":"Ae Allah! Hum tujh se apne is safar mein neki aur taqwa maangte hain aur aise amal maangte hain jin se tu raazi ho. Ae Allah! Hamara yeh safar aasaan kar de aur iski doori hum par lapet de.","hi":"ऐ अल्लाह! हम तुझसे अपने इस सफ़र में नेकी और तक़वा माँगते हैं और ऐसे अमल माँगते हैं जिनसे तू राज़ी हो। ऐ अल्लाह! हमारा यह सफ़र आसान कर दे और इसकी दूरी हम पर लपेट दे।","en":"O Allah! We ask You on this journey of ours for righteousness and piety, and for deeds that please You. O Allah! Make this journey easy for us and fold up its distance for us."},"r":"Sahih Muslim 1342","n":{"ur":"سواری کی دعا کے بعد یہ دعا بھی نبی ﷺ سے ثابت ہے۔","ro":"Sawari ki dua ke baad yeh dua bhi Nabi ﷺ se saabit hai.","hi":"सवारी की दुआ के बाद यह दुआ भी नबी ﷺ से साबित है।","en":"After the dua for mounting a vehicle, this dua is also established from the Prophet ﷺ."}},{"id":109,"c":"roz","t":{"ro":"Naya chand dekhne par","hi":"नया चाँद देखने पर","en":"When seeing the new moon"},"a":"اللَّهُمَّ أَهِلَّهُ عَلَيْنَا بِالْيُمْنِ وَالْإِيمَانِ وَالسَّلَامَةِ وَالْإِسْلَامِ، رَبِّي وَرَبُّكَ اللَّهُ","tl":"Allahumma ahillahu 'alayna bil-yumni wal-imani was-salamati wal-islam, rabbi wa rabbukallah","m":{"ur":"اے اللہ! اس چاند کو ہم پر برکت، ایمان، سلامتی اور اسلام کے ساتھ طلوع فرما۔ (اے چاند!) میرا اور تیرا رب اللہ ہے۔","ro":"Ae Allah! Is chaand ko hum par barkat, imaan, salamati aur Islam ke saath tulu farma. (Ae chaand!) Mera aur tera Rab Allah hai.","hi":"ऐ अल्लाह! इस चाँद को हम पर बरकत, ईमान, सलामती और इस्लाम के साथ तुलू फ़रमा। (ऐ चाँद!) मेरा और तेरा रब अल्लाह है।","en":"O Allah! Bring this moon over us with blessing, faith, safety and Islam. (O moon!) My Lord and your Lord is Allah."},"r":"Tirmidhi 3451 (Albani: Hasan — Sahih al-Jami' 4726, as-Sahiha 1816)","n":{"ur":"نئے مہینے کا چاند دیکھنے پر پڑھی جاتی ہے۔","ro":"Naye mahine ka chaand dekhne par padhi jaati hai.","hi":"नए महीने का चाँद देखने पर पढ़ी जाती है।","en":"It is recited upon seeing the new moon of a month."}},{"id":110,"c":"roz","t":{"ro":"Baarish ke waqt","hi":"बारिश के वक़्त","en":"When it rains"},"a":"اللَّهُمَّ صَيِّبًا نَافِعًا","tl":"Allahumma sayyiban nafi'a","m":{"ur":"اے اللہ! نفع دینے والی بارش برسا۔","ro":"Ae Allah! Nafa dene wali baarish barsa.","hi":"ऐ अल्लाह! नफ़ा देने वाली बारिश बरसा।","en":"O Allah! Let it be a beneficial rain."},"r":"Sahih Bukhari 1032","n":{"ur":"بارش دیکھ کر یہ دعا پڑھی جاتی ہے۔","ro":"Baarish dekh kar yeh dua padhi jaati hai.","hi":"बारिश देखकर यह दुआ पढ़ी जाती है।","en":"This dua is recited upon seeing rain."}},{"id":111,"c":"roz","t":{"ro":"Roza iftar karte waqt","hi":"रोज़ा इफ़्तार करते वक़्त","en":"When breaking the fast"},"a":"ذَهَبَ الظَّمَأُ وَابْتَلَّتِ الْعُرُوقُ وَثَبَتَ الْأَجْرُ إِنْ شَاءَ اللَّهُ","tl":"Dhahabaz-zama'u wabtallatil-'uruqu wa thabatal-ajru in sha'allah","m":{"ur":"پیاس چلی گئی، رگیں تر ہو گئیں اور اگر اللہ نے چاہا تو اجر ثابت ہو گیا۔","ro":"Pyaas chali gayi, ragein tar ho gayin aur agar Allah ne chaha to ajr saabit ho gaya.","hi":"प्यास चली गई, रगें तर हो गईं और अगर अल्लाह ने चाहा तो अज्र साबित हो गया।","en":"The thirst has gone, the veins are moistened, and the reward is confirmed, if Allah wills."},"r":"Abu Dawud 2357 (Albani: Hasan — Sahih al-Jami' 4678)","n":{"ur":"روزہ کھولنے کے بعد پڑھی جاتی ہے۔","ro":"Roza kholne ke baad padhi jaati hai.","hi":"रोज़ा खोलने के बाद पढ़ी जाती है।","en":"It is recited after breaking the fast."}},{"id":112,"c":"roz","t":{"ro":"Rizq-e-halal ki dua","hi":"रिज़्क़-ए-हलाल की दुआ","en":"Dua for lawful provision"},"a":"اللَّهُمَّ اكْفِنِي بِحَلَالِكَ عَنْ حَرَامِكَ وَأَغْنِنِي بِفَضْلِكَ عَمَّنْ سِوَاكَ","tl":"Allahummak-fini bihalalika 'an haramik, wa aghnini bifadlika 'amman siwak","m":{"ur":"اے اللہ! مجھے اپنے حلال کے ذریعے حرام سے کافی ہو جا اور اپنے فضل سے اپنے سوا سب سے بے نیاز کر دے۔","ro":"Ae Allah! Mujhe apne halaal ke zariye haraam se kaafi ho ja aur apne fazl se apne siwa sab se be-niyaz kar de.","hi":"ऐ अल्लाह! मुझे अपने हलाल के ज़रिए हराम से काफ़ी हो जा और अपने फ़ज़्ल से अपने सिवा सब से बे-नियाज़ कर दे।","en":"O Allah! Suffice me with what You have made lawful so that I do not need what You have forbidden, and by Your grace make me independent of everyone besides You."},"r":"Tirmidhi 3563 (Albani: Hasan — as-Sahiha 266)","n":{"ur":"قرض اور تنگی سے نجات اور حلال روزی کے لیے یہ ایک جامع دعا ہے۔","ro":"Qarz aur tangi se nijaat aur halaal rozi ke liye yeh ek jaame dua hai.","hi":"क़र्ज़ और तंगी से निजात और हलाल रोज़ी के लिए यह एक जामे दुआ है।","en":"This is a comprehensive dua for relief from debt and hardship and for lawful livelihood."}},{"id":113,"c":"roz","t":{"ro":"Dunya aur Aakhirat ki bhalai","hi":"दुनिया और आख़िरत की भलाई","en":"Good in this world and the Hereafter"},"a":"رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ","tl":"Rabbana atina fid-dunya hasanatan wa fil-akhirati hasanatan wa qina 'adhaban-nar","m":{"ur":"اے ہمارے رب! ہمیں دنیا میں بھلائی دے اور آخرت میں بھلائی دے اور ہمیں آگ کے عذاب سے بچا۔","ro":"Ae hamare Rab! Hamein duniya mein bhalai de aur aakhirat mein bhalai de aur hamein aag ke azaab se bacha.","hi":"ऐ हमारे रब! हमें दुनिया में भलाई दे और आख़िरत में भलाई दे और हमें आग के अज़ाब से बचा।","en":"Our Lord! Grant us good in this world and good in the Hereafter, and protect us from the punishment of the Fire."},"r":"Surah Al-Baqarah 2:201, Sahih Bukhari 4522","n":{"ur":"انس رضی اللہ عنہ کے مطابق نبی ﷺ کی اکثر دعا یہی ہوتی تھی۔","ro":"Anas RA ke mutabiq Nabi ﷺ ki aksar dua yehi hoti thi.","hi":"अनस रज़ि. के मुताबिक़ नबी ﷺ की अक्सर दुआ यही होती थी।","en":"According to Anas RA, this was the most frequent dua of the Prophet ﷺ."}},{"id":114,"c":"roz","t":{"ro":"Dil ko deen par saabit rakhne ki dua","hi":"दिल को दीन पर साबित रखने की दुआ","en":"Dua for keeping the heart firm on the religion"},"a":"يَا مُقَلِّبَ الْقُلُوبِ ثَبِّتْ قَلْبِي عَلَى دِينِكَ","tl":"Ya muqallibal-qulub, thabbit qalbi 'ala dinik","m":{"ur":"اے دلوں کو پھیرنے والے! میرے دل کو اپنے دین پر ثابت قدم رکھ۔","ro":"Ae dilon ko phernay wale! Mere dil ko apne deen par saabit qadam rakh.","hi":"ऐ दिलों को फेरने वाले! मेरे दिल को अपने दीन पर साबित क़दम रख।","en":"O Turner of hearts! Keep my heart firm upon Your religion."},"r":"Tirmidhi 2140 (Albani: Sahih — as-Sahiha 2091)","n":{"ur":"نبی ﷺ یہ دعا بکثرت کرتے تھے۔","ro":"Nabi ﷺ yeh dua bakasrat karte the.","hi":"नबी ﷺ यह दुआ बकसरत करते थे।","en":"The Prophet ﷺ used to make this dua very often."}},{"id":115,"c":"roz","t":{"ro":"Ilm mein izafe ki dua","hi":"इल्म में इज़ाफ़े की दुआ","en":"Dua for increase in knowledge"},"a":"رَبِّ زِدْنِي عِلْمًا","tl":"Rabbi zidni 'ilma","m":{"ur":"اے میرے رب! میرے علم میں اضافہ فرما۔","ro":"Ae mere Rab! Mere ilm mein izafa farma.","hi":"ऐ मेरे रब! मेरे इल्म में इज़ाफ़ा फ़रमा।","en":"My Lord! Increase me in knowledge."},"r":"Surah Ta-Ha 20:114","n":{"ur":"طلبِ علم کے وقت اور پڑھائی شروع کرتے ہوئے یہ دعا کریں۔","ro":"Talab-e-ilm ke waqt aur padhai shuru karte hue yeh dua karein.","hi":"तलब-ए-इल्म के वक़्त और पढ़ाई शुरू करते हुए यह दुआ करें।","en":"Make this dua while seeking knowledge and when beginning to study."}},{"id":116,"c":"roz","t":{"ro":"Walidain ke liye dua","hi":"वालिदैन के लिए दुआ","en":"Dua for one's parents"},"a":"رَبِّ ارْحَمْهُمَا كَمَا رَبَّيَانِي صَغِيرًا","tl":"Rabbir-hamhuma kama rabbayani saghira","m":{"ur":"اے میرے رب! ان دونوں (ماں باپ) پر رحم فرما جیسے انہوں نے بچپن میں میری پرورش کی۔","ro":"Ae mere Rab! In donon (maa baap) par rahm farma jaise unhon ne bachpan mein meri parwarish ki.","hi":"ऐ मेरे रब! इन दोनों (माँ बाप) पर रहम फ़रमा जैसे उन्होंने बचपन में मेरी परवरिश की।","en":"My Lord! Have mercy on them both (my parents) as they raised me when I was small."},"r":"Surah Al-Isra 17:24","n":{"ur":"والدین کے لیے، زندہ ہوں یا وفات پا چکے ہوں، یہ دعا قرآن میں سکھائی گئی ہے۔","ro":"Walidain ke liye, zinda hon ya wafaat paa chuke hon, yeh dua Quran mein sikhai gayi hai.","hi":"वालिदैन के लिए, ज़िंदा हों या वफ़ात पा चुके हों, यह दुआ क़ुरआन में सिखाई गई है।","en":"This dua for one's parents, whether living or deceased, has been taught in the Quran."}},{"id":117,"c":"roz","t":{"ro":"Bachchon ko nazar aur shaitan se bachane ki dua","hi":"बच्चों को नज़र और शैतान से बचाने की दुआ","en":"Dua to protect children from the evil eye and Satan"},"a":"أُعِيذُكُمَا بِكَلِمَاتِ اللَّهِ التَّامَّةِ مِنْ كُلِّ شَيْطَانٍ وَهَامَّةٍ، وَمِنْ كُلِّ عَيْنٍ لَامَّةٍ","tl":"U'idhukuma bikalimatillahit-tammati min kulli shaytanin wa hammah, wa min kulli 'aynin lammah","m":{"ur":"میں تم دونوں کو اللہ کے مکمل کلمات کی پناہ میں دیتا ہوں ہر شیطان اور زہریلے جانور سے اور ہر نقصان پہنچانے والی نظر سے۔","ro":"Main tum donon ko Allah ke mukammal kalimaat ki panah mein deta hoon har shaitan aur zehreelay janwar se aur har nuqsan pahunchane wali nazar se.","hi":"मैं तुम दोनों को अल्लाह के मुकम्मल कलिमात की पनाह में देता हूँ हर शैतान और ज़हरीले जानवर से और हर नुक़सान पहुँचाने वाली नज़र से।","en":"I seek refuge for you both in the perfect words of Allah, from every devil and every venomous creature, and from every harmful eye."},"r":"Sahih Bukhari 3371","n":{"ur":"نبی ﷺ حسن اور حسین رضی اللہ عنہما کے لیے یہ دعا پڑھ کر دم کرتے تھے۔ ایک بچے کے لیے «أُعِيذُكَ» کہیں۔","ro":"Nabi ﷺ Hasan aur Husain RA ke liye yeh dua padh kar dam karte the. Ek bachche ke liye «أُعِيذُكَ» kahein.","hi":"नबी ﷺ हसन और हुसैन रज़ि. के लिए यह दुआ पढ़कर दम करते थे। एक बच्चे के लिए «أُعِيذُكَ» कहें।","en":"The Prophet ﷺ used to recite this over Hasan and Husain RA as a protective ruqyah. For a single child, say «أُعِيذُكَ»."}},{"id":118,"c":"roz","t":{"ro":"Shaadi par mubarakbad dene ki dua","hi":"शादी पर मुबारकबाद देने की दुआ","en":"Dua for congratulating a newly married couple"},"a":"بَارَكَ اللَّهُ لَكَ، وَبَارَكَ عَلَيْكَ، وَجَمَعَ بَيْنَكُمَا فِي خَيْرٍ","tl":"Barakallahu laka, wa baraka 'alayka, wa jama'a baynakuma fi khayr","m":{"ur":"اللہ تمہارے لیے برکت دے، تم پر برکت نازل کرے اور تم دونوں کو بھلائی میں جمع رکھے۔","ro":"Allah tumhare liye barkat de, tum par barkat naazil kare aur tum donon ko bhalai mein jama rakhe.","hi":"अल्लाह तुम्हारे लिए बरकत दे, तुम पर बरकत नाज़िल करे और तुम दोनों को भलाई में जमा रखे।","en":"May Allah bless you, shower His blessings upon you, and unite you both in goodness."},"r":"Abu Dawud 2130, Tirmidhi 1091 (Albani: isnad Sahih — Sahih Abi Dawud)","n":{"ur":"نئے دولہا یا دلہن کو مبارک باد دیتے وقت یہ دعا دی جاتی ہے۔","ro":"Naye dulha ya dulhan ko mubarakbad dete waqt yeh dua di jaati hai.","hi":"नए दूल्हा या दुल्हन को मुबारकबाद देते वक़्त यह दुआ दी जाती है।","en":"This dua is offered when congratulating a new groom or bride."}},{"id":119,"c":"roz","t":{"ro":"Qabristan mein dakhil hote waqt","hi":"क़ब्रिस्तान में दाख़िल होते वक़्त","en":"When entering the graveyard"},"a":"السَّلَامُ عَلَيْكُمْ أَهْلَ الدِّيَارِ مِنَ الْمُؤْمِنِينَ وَالْمُسْلِمِينَ، وَإِنَّا إِنْ شَاءَ اللَّهُ بِكُمْ لَاحِقُونَ، نَسْأَلُ اللَّهَ لَنَا وَلَكُمُ الْعَافِيَةَ","tl":"As-salamu 'alaykum ahlad-diyari minal-mu'minina wal-muslimin, wa inna in sha'allahu bikum lahiqun, nas'alullaha lana wa lakumul-'afiyah","m":{"ur":"اے ان گھروں کے مومن اور مسلمان باشندو! تم پر سلامتی ہو۔ اگر اللہ نے چاہا تو ہم بھی تم سے ملنے والے ہیں۔ ہم اللہ سے اپنے اور تمہارے لیے عافیت مانگتے ہیں۔","ro":"Ae in gharon ke momin aur musalman baashindo! Tum par salamati ho. Agar Allah ne chaha to hum bhi tum se milne wale hain. Hum Allah se apne aur tumhare liye afiyat maangte hain.","hi":"ऐ इन घरों के मोमिन और मुसलमान बाशिन्दो! तुम पर सलामती हो। अगर अल्लाह ने चाहा तो हम भी तुमसे मिलने वाले हैं। हम अल्लाह से अपने और तुम्हारे लिए आफ़ियत माँगते हैं।","en":"Peace be upon you, O believing and Muslim inhabitants of these abodes. If Allah wills, we will join you. We ask Allah for well-being for ourselves and for you."},"r":"Sahih Muslim 975","n":{"ur":"قبرستان جاتے وقت اہلِ قبور کو سلام کر کے ان کے لیے دعا کی جاتی ہے۔","ro":"Qabristan jaate waqt ahl-e-qubur ko salam kar ke un ke liye dua ki jaati hai.","hi":"क़ब्रिस्तान जाते वक़्त अहले-क़ुबूर को सलाम करके उनके लिए दुआ की जाती है।","en":"When visiting the graveyard, one greets the people of the graves with salam and makes dua for them."}},{"id":120,"c":"ruqya","t":{"ro":"Ruqya Shariah kya hai? (Zaroori usool)","hi":"रुक़्या शरीअ़ा क्या है? (ज़रूरी उसूल)","en":"What is Ruqyah Shar'iyyah? (Essential principles)"},"a":"اعْرِضُوا عَلَيَّ رُقَاكُمْ، لَا بَأْسَ بِالرُّقَى مَا لَمْ يَكُنْ فِيهِ شِرْكٌ","tl":"I'ridu 'alayya ruqakum, la ba'sa bir-ruqa ma lam yakun fihi shirk","m":{"ur":"اپنے دم مجھے سناؤ، دم میں کوئی حرج نہیں جب تک اس میں شرک نہ ہو۔","ro":"Apne dam mujhe sunao, dam mein koi harj nahin jab tak us mein shirk na ho.","hi":"अपने दम मुझे सुनाओ, दम में कोई हर्ज नहीं जब तक उसमें शिर्क न हो।","en":"Present your ruqyah to me; there is no harm in ruqyah as long as it contains no shirk."},"r":"Sahih Muslim 2200; Sahih Bukhari 5678"},{"id":121,"c":"ruqya","t":{"ro":"Surah Al-Fatiha se ruqya","hi":"सूरह अल-फ़ातिहा से रुक़्या","en":"Ruqyah with Surah Al-Fatiha"},"a":"بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ ﴿١﴾ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ﴿٢﴾ الرَّحْمَٰنِ الرَّحِيمِ ﴿٣﴾ مَالِكِ يَوْمِ الدِّينِ ﴿٤﴾ إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ ﴿٥﴾ اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ ﴿٦﴾ صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ ﴿٧﴾","tl":"Bismillahir-Rahmanir-Rahim. Alhamdu lillahi Rabbil-'alamin. Ar-Rahmanir-Rahim. Maliki yawmid-din. Iyyaka na'budu wa iyyaka nasta'in. Ihdinas-siratal-mustaqim. Siratal-ladhina an'amta 'alayhim, ghayril-maghdubi 'alayhim wa lad-dallin.","m":{"ur":"اللہ کے نام سے جو بہت مہربان، نہایت رحم والا ہے۔ تمام تعریف اللہ کے لیے ہے جو سارے جہانوں کا رب ہے۔ بہت مہربان، نہایت رحم والا۔ بدلے کے دن کا مالک۔ ہم تیری ہی عبادت کرتے ہیں اور تجھی سے مدد مانگتے ہیں۔ ہمیں سیدھے راستے کی ہدایت دے۔ ان لوگوں کے راستے کی جن پر تو نے انعام کیا، نہ ان کے راستے کی جن پر غضب ہوا اور نہ گمراہوں کے۔","ro":"Allah ke naam se jo bahut meherbaan, nihayat rahm wala hai. Tamam tareef Allah ke liye hai jo saare jahanon ka Rab hai. Bahut meherbaan, nihayat rahm wala. Badle ke din ka malik. Hum teri hi ibadat karte hain aur tujhi se madad mangte hain. Hamein seedhe raste ki hidayat de. Un logon ke raste ki jin par tune inaam kiya, na un ke raste ki jin par ghazab hua aur na gumrahon ke.","hi":"अल्लाह के नाम से जो बहुत मेहरबान, निहायत रहम वाला है। तमाम तारीफ़ अल्लाह के लिए है जो सारे जहानों का रब है। बहुत मेहरबान, निहायत रहम वाला। बदले के दिन का मालिक। हम तेरी ही इबादत करते हैं और तुझी से मदद माँगते हैं। हमें सीधे रास्ते की हिदायत दे। उन लोगों के रास्ते की जिन पर तूने इनाम किया, न उनके रास्ते की जिन पर ग़ज़ब हुआ और न गुमराहों के।","en":"In the name of Allah, the Most Gracious, the Most Merciful. All praise is for Allah, Lord of all the worlds. The Most Gracious, the Most Merciful. Master of the Day of Judgement. You alone we worship, and You alone we ask for help. Guide us to the straight path. The path of those You have blessed, not of those who earned anger, nor of those who went astray."},"r":"Sahih Bukhari 5736; Sahih Muslim 2201"},{"id":122,"c":"ruqya","t":{"ro":"Ayatul Kursi se hifazat","hi":"आयतुल कुर्सी से हिफ़ाज़त","en":"Protection through Ayat al-Kursi"},"a":"اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ ۚ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ ۚ لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ ۗ مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ إِلَّا بِمَا شَاءَ ۚ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ ۖ وَلَا يَئُودُهُ حِفْظُهُمَا ۚ وَهُوَ الْعَلِيُّ الْعَظِيمُ","tl":"Allahu la ilaha illa huwal-Hayyul-Qayyum, la ta'khudhuhu sinatun wa la nawm, lahu ma fis-samawati wa ma fil-ard, man dhal-ladhi yashfa'u 'indahu illa bi-idhnih, ya'lamu ma bayna aydihim wa ma khalfahum, wa la yuhituna bishay'im-min 'ilmihi illa bima sha', wasi'a kursiyyuhus-samawati wal-ard, wa la ya'uduhu hifzuhuma, wa huwal-'Aliyyul-'Azim.","m":{"ur":"اللہ کے سوا کوئی معبود نہیں، وہ زندہ ہے، سب کو تھامنے والا ہے۔ اسے نہ اونگھ آتی ہے نہ نیند۔ جو کچھ آسمانوں میں اور زمین میں ہے سب اسی کا ہے۔ کون ہے جو اس کی اجازت کے بغیر اس کے پاس سفارش کرے؟ وہ جانتا ہے جو ان کے سامنے ہے اور جو ان کے پیچھے ہے، اور وہ اس کے علم میں سے کسی چیز کا احاطہ نہیں کر سکتے مگر جتنا وہ چاہے۔ اس کی کرسی آسمانوں اور زمین کو گھیرے ہوئے ہے، اور ان کی حفاظت اسے تھکاتی نہیں، اور وہ بلند و عظمت والا ہے۔","ro":"Allah ke siwa koi mabood nahin, woh zinda hai, sab ko thamne wala hai. Use na unghh aati hai na neend. Jo kuchh aasmanon mein aur zameen mein hai sab usi ka hai. Kaun hai jo uski ijazat ke baghair uske paas sifarish kare? Woh jaanta hai jo unke samne hai aur jo unke peechhe hai, aur woh uske ilm mein se kisi cheez ka ihata nahin kar sakte magar jitna woh chahe. Uski kursi aasmanon aur zameen ko gheray hue hai, aur unki hifazat use thakati nahin, aur woh buland o azmat wala hai.","hi":"अल्लाह के सिवा कोई माबूद नहीं, वह ज़िंदा है, सबको थामने वाला है। उसे न ऊँघ आती है न नींद। जो कुछ आसमानों में और ज़मीन में है सब उसी का है। कौन है जो उसकी इजाज़त के बग़ैर उसके पास सिफ़ारिश करे? वह जानता है जो उनके सामने है और जो उनके पीछे है, और वह उसके इल्म में से किसी चीज़ का इहाता नहीं कर सकते मगर जितना वह चाहे। उसकी कुर्सी आसमानों और ज़मीन को घेरे हुए है, और उनकी हिफ़ाज़त उसे थकाती नहीं, और वह बुलंद व अज़मत वाला है।","en":"Allah, there is no deity worthy of worship except Him, the Ever-Living, the Sustainer of all. Neither drowsiness overtakes Him nor sleep. To Him belongs whatever is in the heavens and whatever is on the earth. Who is there that can intercede with Him except by His permission? He knows what is before them and what is behind them, and they encompass nothing of His knowledge except what He wills. His Kursi extends over the heavens and the earth, and their preservation does not tire Him, and He is the Most High, the Most Great."},"r":"Sahih Bukhari 2311"},{"id":123,"c":"ruqya","t":{"ro":"Surah Baqarah ki aakhri 2 ayaat","hi":"सूरह बक़रह की आख़िरी 2 आयात","en":"The last 2 verses of Surah al-Baqarah"},"a":"آمَنَ الرَّسُولُ بِمَا أُنزِلَ إِلَيْهِ مِن رَّبِّهِ وَالْمُؤْمِنُونَ ۚ كُلٌّ آمَنَ بِاللَّهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّن رُّسُلِهِ ۚ وَقَالُوا سَمِعْنَا وَأَطَعْنَا ۖ غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ ﴿٢٨٥﴾ لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا ۚ لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ ۗ رَبَّنَا لَا تُؤَاخِذْنَا إِن نَّسِينَا أَوْ أَخْطَأْنَا ۚ رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَا إِصْرًا كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِن قَبْلِنَا ۚ رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِ ۖ وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا ۚ أَنتَ مَوْلَانَا فَانصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ ﴿٢٨٦﴾","tl":"Amanar-Rasulu bima unzila ilayhi mir-Rabbihi wal-mu'minun, kullun amana billahi wa mala'ikatihi wa kutubihi wa rusulih, la nufarriqu bayna ahadim-mir-rusulih, wa qalu sami'na wa ata'na ghufranaka Rabbana wa ilaykal-masir. La yukallifullahu nafsan illa wus'aha, laha ma kasabat wa 'alayha maktasabat, Rabbana la tu'akhidhna in nasina aw akhta'na, Rabbana wa la tahmil 'alayna isran kama hamaltahu 'alal-ladhina min qablina, Rabbana wa la tuhammilna ma la taqata lana bih, wa'fu 'anna waghfir lana warhamna, anta mawlana fansurna 'alal-qawmil-kafirin.","m":{"ur":"رسول ﷺ اس پر ایمان لائے جو ان کے رب کی طرف سے ان پر اتارا گیا، اور مومن بھی۔ سب اللہ پر، اس کے فرشتوں پر، اس کی کتابوں پر اور اس کے رسولوں پر ایمان لائے (اور کہتے ہیں:) ہم اس کے رسولوں میں کوئی فرق نہیں کرتے۔ اور انہوں نے کہا: ہم نے سنا اور مان لیا، اے ہمارے رب! تیری بخشش چاہیے اور تیری ہی طرف لوٹنا ہے۔ اللہ کسی جان پر اس کی طاقت سے زیادہ بوجھ نہیں ڈالتا۔ جو نیکی اس نے کمائی اس کا فائدہ اسی کو، اور جو برائی کمائی اس کا نقصان اسی پر۔ اے ہمارے رب! اگر ہم بھول جائیں یا خطا کریں تو ہمیں نہ پکڑنا۔ اے ہمارے رب! ہم پر وہ بوجھ نہ ڈال جو تو نے ہم سے پہلے لوگوں پر ڈالا۔ اے ہمارے رب! ہم سے وہ بوجھ نہ اٹھوا جس کی ہمیں طاقت نہیں، اور ہمیں معاف کر، ہمیں بخش دے اور ہم پر رحم فرما، تو ہی ہمارا مولیٰ ہے، پس کافروں کے مقابلے میں ہماری مدد فرما۔","ro":"Rasool ﷺ us par imaan laaye jo unke Rab ki taraf se un par utara gaya, aur momin bhi. Sab Allah par, uske farishton par, uski kitabon par aur uske rasoolon par imaan laaye (aur kehte hain:) Hum uske rasoolon mein koi farq nahi karte. Aur unhon ne kaha: Hum ne suna aur maan liya, ae hamare Rab! Teri bakhshish chahiye aur teri hi taraf laut na hai. Allah kisi jaan par uski taaqat se zyada bojh nahi daalta. Jo neki us ne kamaai uska faida usi ko, aur jo buraai kamaai uska nuqsan usi par. Ae hamare Rab! Agar hum bhool jayen ya khata karein to hamein na pakadna. Ae hamare Rab! Hum par woh bojh na daal jo tu ne hum se pehle logon par daala. Ae hamare Rab! Hum se woh bojh na uthwa jiski hamein taaqat nahi, aur hamein maaf kar, hamein bakhsh de aur hum par rahm farma, tu hi hamara Maula hai, pas kaafiron ke muqable mein hamari madad farma.","hi":"रसूल ﷺ उस पर ईमान लाए जो उनके रब की तरफ़ से उन पर उतारा गया, और मोमिन भी। सब अल्लाह पर, उसके फ़रिश्तों पर, उसकी किताबों पर और उसके रसूलों पर ईमान लाए (और कहते हैं:) हम उसके रसूलों में कोई फ़र्क़ नहीं करते। और उन्होंने कहा: हमने सुना और मान लिया, ऐ हमारे रब! तेरी बख़्शिश चाहिए और तेरी ही तरफ़ लौटना है। अल्लाह किसी जान पर उसकी ताक़त से ज़्यादा बोझ नहीं डालता। जो नेकी उसने कमाई उसका फ़ायदा उसी को, और जो बुराई कमाई उसका नुक़सान उसी पर। ऐ हमारे रब! अगर हम भूल जाएँ या ख़ता करें तो हमें न पकड़ना। ऐ हमारे रब! हम पर वह बोझ न डाल जो तूने हमसे पहले लोगों पर डाला। ऐ हमारे रब! हमसे वह बोझ न उठवा जिसकी हमें ताक़त नहीं, और हमें माफ़ कर, हमें बख़्श दे और हम पर रहम फ़रमा, तू ही हमारा मौला है, पस काफ़िरों के मुक़ाबले में हमारी मदद फ़रमा।","en":"The Messenger ﷺ believes in what has been sent down to him from his Lord, and so do the believers. All of them believe in Allah, His angels, His books and His messengers (saying:) We make no distinction between any of His messengers. And they say: We hear and we obey. Your forgiveness, our Lord, and to You is the final return. Allah does not burden a soul beyond its capacity. It will have what it has earned, and it will bear what it has earned. Our Lord! Do not hold us accountable if we forget or make a mistake. Our Lord! Do not place upon us a burden like the one You placed on those before us. Our Lord! Do not burden us with what we have no strength to bear. Pardon us, forgive us, and have mercy on us. You are our Protector, so help us against the disbelieving people."},"r":"Sahih Bukhari 5009; Sahih Muslim 807"},{"id":124,"c":"ruqya","t":{"ro":"Teeno Qul se dam (sone se pehle aur bimari mein)","hi":"तीनों क़ुल से दम (सोने से पहले और बीमारी में)","en":"Dam with the Three Quls (before sleep and in illness)"},"a":"قُلْ هُوَ اللَّهُ أَحَدٌ ﴿١﴾ اللَّهُ الصَّمَدُ ﴿٢﴾ لَمْ يَلِدْ وَلَمْ يُولَدْ ﴿٣﴾ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ ﴿٤﴾ قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ ﴿١﴾ مِنْ شَرِّ مَا خَلَقَ ﴿٢﴾ وَمِنْ شَرِّ غَاسِقٍ إِذَا وَقَبَ ﴿٣﴾ وَمِنْ شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ ﴿٤﴾ وَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ ﴿٥﴾ قُلْ أَعُوذُ بِرَبِّ النَّاسِ ﴿١﴾ مَلِكِ النَّاسِ ﴿٢﴾ إِلَٰهِ النَّاسِ ﴿٣﴾ مِنْ شَرِّ الْوَسْوَاسِ الْخَنَّاسِ ﴿٤﴾ الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ ﴿٥﴾ مِنَ الْجِنَّةِ وَالنَّاسِ ﴿٦﴾","tl":"Qul huwallahu ahad. Allahus-Samad. Lam yalid wa lam yulad. Wa lam yakun lahu kufuwan ahad. Qul a'udhu bi Rabbil-falaq. Min sharri ma khalaq. Wa min sharri ghasiqin idha waqab. Wa min sharrin-naffathati fil-'uqad. Wa min sharri hasidin idha hasad. Qul a'udhu bi Rabbin-nas. Malikin-nas. Ilahin-nas. Min sharril-waswasil-khannas. Alladhi yuwaswisu fi sudurin-nas. Minal-jinnati wan-nas.","m":{"ur":"کہہ دیجیے: وہ اللہ ایک ہے۔ اللہ بے نیاز ہے۔ نہ اس نے کسی کو جنا اور نہ وہ جنا گیا۔ اور نہ کوئی اس کے برابر کا ہے۔ کہہ دیجیے: میں صبح کے رب کی پناہ میں آتا ہوں، اس کی مخلوق کے شر سے، اور اندھیری رات کے شر سے جب وہ چھا جائے، اور گرہوں میں پھونکنے والیوں کے شر سے، اور حسد کرنے والے کے شر سے جب وہ حسد کرے۔ کہہ دیجیے: میں لوگوں کے رب کی پناہ میں آتا ہوں، لوگوں کے بادشاہ کی، لوگوں کے معبود کی، وسوسہ ڈالنے والے پیچھے ہٹ جانے والے کے شر سے، جو لوگوں کے سینوں میں وسوسے ڈالتا ہے، جنوں میں سے اور انسانوں میں سے۔","ro":"Keh dijiye: Woh Allah ek hai. Allah be-niyaz hai. Na usne kisi ko jana aur na woh jana gaya. Aur na koi uske barabar ka hai. Keh dijiye: Main subah ke Rab ki panah mein aata hoon, uski makhluq ke shar se, aur andheri raat ke shar se jab woh chha jaye, aur girhon mein phoonkne walion ke shar se, aur hasad karne wale ke shar se jab woh hasad kare. Keh dijiye: Main logon ke Rab ki panah mein aata hoon, logon ke badshah ki, logon ke mabood ki, waswasa dalne wale peechhe hat jane wale ke shar se, jo logon ke seenon mein waswase dalta hai, jinnon mein se aur insanon mein se.","hi":"कह दीजिए: वह अल्लाह एक है। अल्लाह बे-नियाज़ है। न उसने किसी को जना और न वह जना गया। और न कोई उसके बराबर का है। कह दीजिए: मैं सुबह के रब की पनाह में आता हूँ, उसकी मख़लूक़ के शर से, और अँधेरी रात के शर से जब वह छा जाए, और गिरहों में फूँकने वालियों के शर से, और हसद करने वाले के शर से जब वह हसद करे। कह दीजिए: मैं लोगों के रब की पनाह में आता हूँ, लोगों के बादशाह की, लोगों के माबूद की, वसवसा डालने वाले पीछे हट जाने वाले के शर से, जो लोगों के सीनों में वसवसे डालता है, जिन्नों में से और इंसानों में से।","en":"Say: He is Allah, the One. Allah is Self-Sufficient. He neither begot nor was begotten. And there is none comparable to Him. Say: I seek refuge in the Lord of the daybreak, from the evil of what He has created, and from the evil of the darkness when it settles, and from the evil of those who blow on knots, and from the evil of the envier when he envies. Say: I seek refuge in the Lord of mankind, the King of mankind, the God of mankind, from the evil of the whispering one who withdraws, who whispers in the hearts of mankind, from among the jinn and mankind."},"r":"Sahih Bukhari 5017"},{"id":125,"c":"ruqya","t":{"ro":"Jism mein dard ho to","hi":"जिस्म में दर्द हो तो","en":"When there is pain in the body"},"a":"بِسْمِ اللَّهِ (3 بار) أَعُوذُ بِاللَّهِ وَقُدْرَتِهِ مِنْ شَرِّ مَا أَجِدُ وَأُحَاذِرُ (7 بار)","tl":"Bismillah (3 times). A'udhu billahi wa qudratihi min sharri ma ajidu wa uhadhir (7 times).","m":{"ur":"اللہ کے نام سے (3 بار)۔ میں اللہ اور اس کی قدرت کی پناہ مانگتا ہوں اس چیز کے شر سے جو میں محسوس کرتا ہوں اور جس سے ڈرتا ہوں (7 بار)۔","ro":"Allah ke naam se (3 baar). Main Allah aur uski qudrat ki panah maangta hoon is cheez ke shar se jo main mehsoos karta hoon aur jis se darta hoon (7 baar).","hi":"अल्लाह के नाम से (3 बार)। मैं अल्लाह और उसकी क़ुदरत की पनाह माँगता हूँ इस चीज़ के शर से जो मैं महसूस करता हूँ और जिससे डरता हूँ (7 बार)।","en":"In the name of Allah (3 times). I seek refuge in Allah and in His power from the evil of what I feel and what I fear (7 times)."},"r":"Sahih Muslim 2202"},{"id":126,"c":"ruqya","t":{"ro":"Bimar par dam ki shifa wali dua","hi":"बीमार पर दम की शिफ़ा वाली दुआ","en":"Healing dua recited over the sick"},"a":"أَذْهِبِ الْبَأْسَ رَبَّ النَّاسِ، اشْفِ وَأَنْتَ الشَّافِي، لَا شِفَاءَ إِلَّا شِفَاؤُكَ، شِفَاءً لَا يُغَادِرُ سَقَمًا","tl":"Adhhibil-ba's, Rabban-nas, ishfi wa antash-Shafi, la shifa'a illa shifa'uk, shifa'an la yughadiru saqama","m":{"ur":"تکلیف دور فرما، اے لوگوں کے رب! شفا دے، تو ہی شفا دینے والا ہے، تیری شفا کے سوا کوئی شفا نہیں، ایسی شفا جو کوئی بیماری نہ چھوڑے۔","ro":"Takleef door farma, ae logon ke Rab! Shifa de, tu hi shifa dene wala hai, teri shifa ke siwa koi shifa nahin, aisi shifa jo koi bimari na chhode.","hi":"तकलीफ़ दूर फ़रमा, ऐ लोगों के रब! शिफ़ा दे, तू ही शिफ़ा देने वाला है, तेरी शिफ़ा के सिवा कोई शिफ़ा नहीं, ऐसी शिफ़ा जो कोई बीमारी न छोड़े।","en":"Remove the harm, O Lord of mankind! Heal, for You are the Healer; there is no healing except Your healing, a healing that leaves no illness behind."},"r":"Sahih Bukhari 5675; Sahih Muslim 2191"},{"id":127,"c":"ruqya","t":{"ro":"Jibreel AS ka dam","hi":"जिबरील अलैहिस्सलाम का दम","en":"The ruqyah of Jibril AS"},"a":"بِاسْمِ اللَّهِ أَرْقِيكَ، مِنْ كُلِّ شَيْءٍ يُؤْذِيكَ، مِنْ شَرِّ كُلِّ نَفْسٍ أَوْ عَيْنِ حَاسِدٍ، اللَّهُ يَشْفِيكَ، بِاسْمِ اللَّهِ أَرْقِيكَ","tl":"Bismillahi arqik, min kulli shay'in yu'dhik, min sharri kulli nafsin aw 'ayni hasid, Allahu yashfik, bismillahi arqik","m":{"ur":"اللہ کے نام سے میں تجھے دم کرتا ہوں، ہر اس چیز سے جو تجھے تکلیف دے، ہر جان کے شر اور حسد کرنے والی آنکھ کے شر سے، اللہ تجھے شفا دے، اللہ کے نام سے میں تجھے دم کرتا ہوں۔","ro":"Allah ke naam se main tujhe dam karta hoon, har us cheez se jo tujhe takleef de, har jaan ke shar aur hasad karne wali aankh ke shar se, Allah tujhe shifa de, Allah ke naam se main tujhe dam karta hoon.","hi":"अल्लाह के नाम से मैं तुझे दम करता हूँ, हर उस चीज़ से जो तुझे तकलीफ़ दे, हर जान के शर और हसद करने वाली आँख के शर से, अल्लाह तुझे शिफ़ा दे, अल्लाह के नाम से मैं तुझे दम करता हूँ।","en":"In the name of Allah I perform ruqyah for you, from everything that harms you, from the evil of every soul and of the envious eye; may Allah heal you. In the name of Allah I perform ruqyah for you."},"r":"Sahih Muslim 2186"},{"id":128,"c":"ruqya","t":{"ro":"Nazar aur hasad se shifa ka dam","hi":"नज़र और हसद से शिफ़ा का दम","en":"Ruqyah for healing from the evil eye and envy"},"a":"بِاسْمِ اللَّهِ يُبْرِيكَ، وَمِنْ كُلِّ دَاءٍ يَشْفِيكَ، وَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ، وَمِنْ شَرِّ كُلِّ ذِي عَيْنٍ","tl":"Bismillahi yubrik, wa min kulli da'in yashfik, wa min sharri hasidin idha hasad, wa min sharri kulli dhi 'ayn","m":{"ur":"اللہ کے نام سے وہ تجھے تندرست کرے، ہر بیماری سے تجھے شفا دے، حسد کرنے والے کے شر سے جب وہ حسد کرے، اور ہر نظر لگانے والی آنکھ کے شر سے۔","ro":"Allah ke naam se woh tujhe tandurust kare, har bimari se tujhe shifa de, hasad karne wale ke shar se jab woh hasad kare, aur har nazar lagane wali aankh ke shar se.","hi":"अल्लाह के नाम से वह तुझे तंदुरुस्त करे, हर बीमारी से तुझे शिफ़ा दे, हसद करने वाले के शर से जब वह हसद करे, और हर नज़र लगाने वाली आँख के शर से।","en":"In the name of Allah, may He cure you, heal you from every disease, from the evil of the envier when he envies, and from the evil of every eye that afflicts."},"r":"Sahih Muslim 2185"},{"id":129,"c":"ruqya","t":{"ro":"Nazar se hifazat (Allah ke mukammal kalimaat)","hi":"नज़र से हिफ़ाज़त (अल्लाह के मुकम्मल कलिमात)","en":"Protection from the evil eye (Allah's perfect words)"},"a":"أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّةِ مِنْ كُلِّ شَيْطَانٍ وَهَامَّةٍ، وَمِنْ كُلِّ عَيْنٍ لَامَّةٍ","tl":"A'udhu bikalimatillahit-tammati min kulli shaytanin wa hammatin, wa min kulli 'aynin lammah","m":{"ur":"میں اللہ کے مکمل کلمات کی پناہ مانگتا ہوں ہر شیطان اور زہریلے جانور سے اور ہر نقصان پہنچانے والی نظر سے۔","ro":"Main Allah ke mukammal kalimaat ki panah maangta hoon har shaitan aur zehreelay janwar se aur har nuqsan pahunchane wali nazar se.","hi":"मैं अल्लाह के मुकम्मल कलिमात की पनाह माँगता हूँ हर शैतान और ज़हरीले जानवर से और हर नुक़सान पहुँचाने वाली नज़र से।","en":"I seek refuge in the perfect words of Allah from every devil and every venomous creature, and from every harmful eye."},"r":"Sahih Bukhari 3371"},{"id":130,"c":"ruqya","t":{"ro":"Kisi jagah utarte waqt har nuqsan se hifazat","hi":"किसी जगह उतरते वक़्त हर नुक़सान से हिफ़ाज़त","en":"Protection from all harm upon stopping at a place"},"a":"أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ","tl":"A'udhu bikalimatillahit-tammati min sharri ma khalaq","m":{"ur":"میں اللہ کے مکمل کلمات کی پناہ مانگتا ہوں اس کی مخلوق کے شر سے۔","ro":"Main Allah ke mukammal kalimaat ki panah maangta hoon uski makhluq ke shar se.","hi":"मैं अल्लाह के मुकम्मल कलिमात की पनाह माँगता हूँ उसकी मख़लूक़ के शर से।","en":"I seek refuge in the perfect words of Allah from the evil of what He has created."},"r":"Sahih Muslim 2708"},{"id":131,"c":"ruqya","t":{"ro":"Ghar mein Surah Al-Baqarah ki tilawat","hi":"घर में सूरह अल-बक़रह की तिलावत","en":"Reciting Surah Al-Baqarah in the home"},"a":"لَا تَجْعَلُوا بُيُوتَكُمْ مَقَابِرَ، إِنَّ الشَّيْطَانَ يَنْفِرُ مِنَ الْبَيْتِ الَّذِي تُقْرَأُ فِيهِ سُورَةُ الْبَقَرَةِ","tl":"La taj'alu buyutakum maqabir, inna ash-shaytana yanfiru minal-bayti alladhi tuqra'u fihi suratul-Baqarah","m":{"ur":"اپنے گھروں کو قبرستان نہ بناؤ، بے شک شیطان اس گھر سے بھاگتا ہے جس میں سورۃ البقرہ پڑھی جاتی ہے۔","ro":"Apne gharon ko qabristan na banao, beshak shaitan us ghar se bhaagta hai jis mein Surah Al-Baqarah padhi jaati hai.","hi":"अपने घरों को क़ब्रिस्तान न बनाओ, बेशक शैतान उस घर से भागता है जिसमें सूरह अल-बक़रह पढ़ी जाती है।","en":"Do not make your homes into graveyards; indeed Satan flees from the house in which Surah Al-Baqarah is recited."},"r":"Sahih Muslim 780"},{"id":132,"c":"ruqya","t":{"ro":"Zakhm ya dard par masnoon dam (mitti aur thook ke saath)","hi":"ज़ख़्म या दर्द पर मस्नून दम (मिट्टी और थूक के साथ)","en":"Sunnah ruqyah for a wound or pain (with soil and saliva)"},"a":"بِسْمِ اللَّهِ، تُرْبَةُ أَرْضِنَا، بِرِيقَةِ بَعْضِنَا، يُشْفَى سَقِيمُنَا، بِإِذْنِ رَبِّنَا","tl":"Bismillah, turbatu ardina, bi riqati ba'dina, yushfa saqimuna, bi idhni Rabbina","m":{"ur":"اللہ کے نام سے، ہماری زمین کی مٹی، ہم میں سے بعض کے تھوک کے ساتھ، ہمارا بیمار ہمارے رب کے حکم سے شفا پائے۔","ro":"Allah ke naam se, hamari zameen ki mitti, hum mein se baaz ke thook ke saath, hamara bimar hamare Rab ke hukm se shifa paye.","hi":"अल्लाह के नाम से, हमारी ज़मीन की मिट्टी, हम में से बाज़ के थूक के साथ, हमारा बीमार हमारे रब के हुक्म से शिफ़ा पाए।","en":"In the name of Allah, the soil of our earth, with the saliva of some of us, may our sick be healed, by the permission of our Lord."},"r":"Sahih Bukhari 5745; Sahih Muslim 2194"},{"id":133,"c":"ruqya","t":{"ro":"Shaitan ke waswase (iman aur sawalat) se bachne ka tareeqa","hi":"शैतान के वस्वसे (ईमान और सवालात) से बचने का तरीक़ा","en":"How to deal with Satan's whispers (about faith and doubts)"},"a":"أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ، آمَنْتُ بِاللَّهِ وَرُسُلِهِ","tl":"A'udhu billahi minash-shaytanir-rajim, amantu billahi wa rusulih","m":{"ur":"میں شیطان مردود سے اللہ کی پناہ مانگتا ہوں، میں اللہ اور اس کے رسولوں پر ایمان لایا۔","ro":"Main shaitan mardood se Allah ki panah maangta hoon, main Allah aur uske rasoolon par iman laya.","hi":"मैं शैतान मरदूद से अल्लाह की पनाह माँगता हूँ, मैं अल्लाह और उसके रसूलों पर ईमान लाया।","en":"I seek refuge in Allah from the accursed Satan; I believe in Allah and His messengers."},"r":"Sahih Bukhari 3276; Sahih Muslim 134"},{"id":134,"c":"ruqya","t":{"ro":"Bure khwab ya dar wale khwab se hifazat","hi":"बुरे ख़्वाब या डरावने ख़्वाब से हिफ़ाज़त","en":"Protection from a bad or frightening dream"},"a":"أَعُوذُ بِاللَّهِ مِنْ شَرِّهَا وَمِنْ شَرِّ الشَّيْطَانِ","tl":"A'udhu billahi min sharriha wa min sharrish-shaytan","m":{"ur":"میں اس (خواب) کے شر سے اور شیطان کے شر سے اللہ کی پناہ مانگتا ہوں۔","ro":"Main is (khwab) ke shar se aur shaitan ke shar se Allah ki panah maangta hoon.","hi":"मैं इस (ख़्वाब) के शर से और शैतान के शर से अल्लाह की पनाह माँगता हूँ।","en":"I seek refuge in Allah from the evil of this (dream) and from the evil of Satan."},"r":"Sahih Muslim 2261; Sahih Bukhari 7044"},{"id":135,"c":"ruqya","t":{"ro":"Koi cheez pasand aaye to (nazar se bachne ke liye)","hi":"कोई चीज़ पसंद आए तो (नज़र से बचने के लिए)","en":"When you admire something (to guard against the evil eye)"},"a":"مَا شَاءَ اللَّهُ لَا قُوَّةَ إِلَّا بِاللَّهِ","tl":"Ma sha'Allah, la quwwata illa billah","m":{"ur":"جو اللہ چاہے (وہی ہوتا ہے)، اللہ کے بغیر کوئی طاقت نہیں۔","ro":"Jo Allah chahe (wahi hota hai), Allah ke baghair koi taaqat nahin.","hi":"जो अल्लाह चाहे (वही होता है), अल्लाह के बग़ैर कोई ताक़त नहीं।","en":"What Allah wills (comes to pass); there is no power except with Allah."},"r":"Surah Al-Kahf 18:39. (Nazar lagne ka haq hona: Sahih Muslim 2188. Nazar se bachne ke liye pasandida cheez par «baarak Allahu feeh / Allahumma baarik alayh» kehna bhi sunnat hai.)"},{"id":136,"c":"ruqya","t":{"ro":"Azan se shaitan ka bhaagna","hi":"अज़ान से शैतान का भागना","en":"Satan flees at the call to prayer"},"a":"إِذَا نُودِيَ لِلصَّلَاةِ أَدْبَرَ الشَّيْطَانُ وَلَهُ ضُرَاطٌ حَتَّى لَا يَسْمَعَ التَّأْذِينَ","tl":"Idha nudiya lis-salati adbarash-shaytanu wa lahu durat, hatta la yasma'at-ta'dhin","m":{"ur":"جب نماز کے لیے اذان دی جاتی ہے تو شیطان پیٹھ پھیر کر بھاگتا ہے اور ہوا خارج کرتا ہے تاکہ اذان نہ سنے۔","ro":"Jab namaz ke liye azan di jaati hai to shaitan peeth pher kar bhaagta hai aur hawa kharij karta hai taake azan na sune.","hi":"जब नमाज़ के लिए अज़ान दी जाती है तो शैतान पीठ फेरकर भागता है और हवा ख़ारिज करता है ताकि अज़ान न सुने।","en":"When the call to prayer is made, Satan turns his back and flees, passing wind, so that he does not hear the adhan."},"r":"Sahih Bukhari 608; Sahih Muslim 389"},{"id":137,"c":"ruqya","t":{"ro":"Ghar mein dakhil hote aur khana khate waqt Allah ka naam","hi":"घर में दाख़िल होते और खाना खाते वक़्त अल्लाह का नाम","en":"Mentioning Allah's name when entering the home and when eating"},"a":"إِذَا دَخَلَ الرَّجُلُ بَيْتَهُ فَذَكَرَ اللَّهَ عِنْدَ دُخُولِهِ وَعِنْدَ طَعَامِهِ، قَالَ الشَّيْطَانُ: لَا مَبِيتَ لَكُمْ وَلَا عَشَاءَ","tl":"Idha dakhalar-rajulu baytahu fa dhakarAllaha 'inda dukhulihi wa 'inda ta'amihi, qalash-shaytanu: la mabita lakum wa la 'asha'","m":{"ur":"جب آدمی اپنے گھر میں داخل ہوتے وقت اور کھانے کے وقت اللہ کا ذکر کرتا ہے تو شیطان (اپنے ساتھیوں سے) کہتا ہے: تمہارے لیے نہ رات گزارنے کی جگہ ہے نہ کھانا۔","ro":"Jab aadmi apne ghar mein dakhil hote waqt aur khane ke waqt Allah ka zikr karta hai to shaitan (apne saathiyon se) kehta hai: Tumhare liye na raat guzarne ki jagah hai na khana.","hi":"जब आदमी अपने घर में दाख़िल होते वक़्त और खाने के वक़्त अल्लाह का ज़िक्र करता है तो शैतान (अपने साथियों से) कहता है: तुम्हारे लिए न रात गुज़रने की जगह है न खाना।","en":"When a man enters his home and mentions Allah upon entering and upon eating, Satan says (to his companions): There is no lodging for you and no dinner."},"r":"Sahih Muslim 2018"},{"id":138,"c":"ruqya","t":{"ro":"Shifa ke masnoon asbab: Kalonji aur Shahad","hi":"शिफ़ा के मस्नून असबाब: कलौंजी और शहद","en":"Prophetic means of healing: Black seed and honey"},"a":"عَلَيْكُمْ بِهَذِهِ الْحَبَّةِ السَّوْدَاءِ، فَإِنَّ فِيهَا شِفَاءً مِنْ كُلِّ دَاءٍ إِلَّا السَّامَ","tl":"'Alaykum bihadhihil-habbatis-sawda', fa inna fiha shifa'an min kulli da'in illas-sam","m":{"ur":"اس کالے دانے (کلونجی) کو لازم پکڑو، کیونکہ اس میں موت کے سوا ہر بیماری کی شفا ہے۔","ro":"Is kaale daane (kalonji) ko lazim pakdo, kyunke is mein maut ke siwa har bimari ki shifa hai.","hi":"इस काले दाने (कलौंजी) को लाज़िम पकड़ो, क्योंकि इसमें मौत के सिवा हर बीमारी की शिफ़ा है।","en":"Hold fast to this black seed, for it contains a cure for every disease except death."},"r":"Sahih Bukhari 5688; Sahih Muslim 2215; Quran 16:69; Sahih Bukhari 5684"}];
